INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4e10f9b4-6d7c-5768-a022-07e8755789ad', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 6, 6, 'የመርከቡም አለቃ ወደ እርሱ ቀርቦ፥ “ምነው ተኝተሃል? እንዳንጠፋ እግዚአብሔር ያድነን ዘንድ ተነሥተህ አምላክህን ጥራ” አለው።'),
  ('4356bd56-f31a-55c0-a2d5-4d96c6063f78', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 7, 7, 'እርስ በርሳቸውም፥ “ይህ ክፉ ነገር በማን ምክንያት እንደ አገኘን እናውቅ ዘንድ ኑ፤ ዕጣ እንጣጣል” ተባባሉ። ዕጣም ተጣጣሉ፤ ዕጣውም በዮናስ ላይ ወደቀ።'),
  ('86bd32bb-3dc5-53a3-a327-e0e5de7fa64e', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 8, 8, 'የዚያን ጊዜም፥ “ይህ ክፉ ነገር በማን ምክንያት እንዳገኘን እባክህ ንገረን፤ ሥራህ ምንድን ነው? ከወዴትስ መጣህ? ወዴትስ ትሄዳለህ? ሀገርህ የት ነው? ወገንህስ ምንድን ነው?” አሉት።'),
  ('ebc265df-5de4-5388-a772-634360f0cc44', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 9, 9, 'እርሱም፥ “እኔ ዕብራዊ የእግዚአብሔር ባሪያ ነኝ፤ ባሕሩንና የብሱን የፈጠረውን የሰማይን አምላክ እግዚአብሔርን አመልካለሁ” አላቸው።'),
  ('5234ab76-4281-5ee6-a670-a9da60629374', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 10, 10, 'እነዚያም ሰዎች ከእግዚአብሔር ፊት እንደ ኰበለለ እርሱ ስለ ነገራቸው ዐውቀዋልና እጅግ ፈርተው፥ “ይህ ያደረግኸው ምንድን ነው?” አሉት።'),
  ('8eda98e2-8566-5ceb-a751-1afb50cfe9fb', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 11, 11, 'ባሕሩ ይታወክ ነበርና፥ ታላቅ ማዕበልም ተነሥቶ ነበርና፥ “ባሕሩ ጸጥ ይልልን ዘንድ እንግዲህ ምን እናድርግህ?” አሉት።'),
  ('280415dd-c89d-5288-a806-a594d4ccb82f', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 12, 12, 'እርሱም፥ “ይህ ታላቅ ማዕበል በእኔ ምክንያት እንደ አገኛችሁ ዐውቃለሁና አንሥታችሁ ወደ ባሕሩ ጣሉኝ፤ ባሕሩም ጽጥ ይልላችኋል” አላቸው።'),
  ('37913f0f-66be-5ea2-ae45-e4f87f98267b', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 13, 13, 'ሰዎቹ ግን ወደ ምድሩ ሊመለሱ አጥብቀው ቀዘፉ፤ ዳሩ ግን ባሕሩ እጅግ አብዝቶ ይናወጥባቸው ነበርና አልቻሉም።'),
  ('65b09f6b-2d7b-517c-af27-7cd5b71963e7', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 14, 14, 'ሁሉም አንድ ሆነው ወደ እግዚአብሔር ጮኹ፤ “አቤቱ! አንተ እንደ ወደድህ አድርገሃልና ስለዚህ ሰው ነፍስ አታጥፋን፤ ንጹሕ ደምንም አታድርግብን።” አሉ።'),
  ('36edc2be-3be5-5e70-a15e-ef916eef427f', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 15, 15, 'ዮናስንም ወስደው ወደ ባሕሩ ጣሉት፤ ባሕሩም ከመናወጡ ጸጥ አለ።'),
  ('5f6c2fa7-eb06-558c-af4c-fb5d55afbcf7', 'c3425ff5-865e-5de8-a929-ed2a636630dc', 'ba5a2fcf-e777-5b66-a97d-57a102593fcf', 16, 16, 'ሰዎቹም እግዚአብሔርን እጅግ ፈሩ፤ ለእግዚአብሔርም መሥዋዕት አቀረቡ፤ ስእለትንም ተሳሉ።'),
  ('b0d13beb-51ec-5575-a8b1-f2c2f2647bc3', '97fb980f-9654-581c-ad42-837d545b3305', '9b2e6780-d88e-56a0-aa0a-bb503a299a54', 1, 1, 'እግዚአብሔርም ዮናስን ይውጠው ዘንድ ታላቅ ዓሣ አንበሪን አዘዘ፤ ዮናስም ሦስት ቀንና ሦስት ሌሊት በዓሣ አንበሪው ሆድ ውስጥ ነበረ።'),
  ('46fc7a5b-a698-5019-a01d-d7838337eced', '97fb980f-9654-581c-ad42-837d545b3305', '9b2e6780-d88e-56a0-aa0a-bb503a299a54', 2, 2, 'ዮናስም በዓሣ አንበሪው ሆድ ውስጥ ሆኖ ወደ አምላኩ ወደ እግዚአብሔር ጸለየ፥'),
  ('9bd6426f-0e92-5655-a558-7ead39f28aa2', '97fb980f-9654-581c-ad42-837d545b3305', '9b2e6780-d88e-56a0-aa0a-bb503a299a54', 3, 3, '“በመከራዬ ሳለሁ ወደ አምላኬ ወደ እግዚአብሔር ጮኽሁ፤'),
  ('c1509dd0-6bbf-5d8d-a65c-677be5e343cd', '97fb980f-9654-581c-ad42-837d545b3305', '9b2e6780-d88e-56a0-aa0a-bb503a299a54', 4, 4, 'ወደ ጥልቁ ወደ ባሕሩ ውስጥ ጣልኸኝ፥'),
  ('c9e91eb7-d184-5636-a968-bc804bc43344', '97fb980f-9654-581c-ad42-837d545b3305', '9b2e6780-d88e-56a0-aa0a-bb503a299a54', 5, 5, 'እኔም፦ ከዐይንህ ፊት ተጣልሁ፤'),
  ('3cff1438-75b8-531f-a1c5-13fdddd539f9', '97fb980f-9654-581c-ad42-837d545b3305', '9b2e6780-d88e-56a0-aa0a-bb503a299a54', 6, 6, 'ውኃ እስከ ነፍሴ ድረስ ፈሰሰ፤'),
  ('ee663725-a656-5883-a902-9e909495531c', '97fb980f-9654-581c-ad42-837d545b3305', '9b2e6780-d88e-56a0-aa0a-bb503a299a54', 7, 7, 'እነሆ ራሴ ወደ ታች ወደ ተራሮች መሠረት ወረደ፤'),
  ('22217ac9-62ac-5c0d-a363-17b7283a0d92', '97fb980f-9654-581c-ad42-837d545b3305', '9b2e6780-d88e-56a0-aa0a-bb503a299a54', 8, 8, 'ነፍሴ በዛለችብኝ ጊዜ እግዚአብሔርን አሰብሁት፤'),
  ('161cbf60-e213-561b-a8c7-bdb897f0ff55', '97fb980f-9654-581c-ad42-837d545b3305', '9b2e6780-d88e-56a0-aa0a-bb503a299a54', 9, 9, 'ከንቱነትንና ሐሰትን የሚጠብቁ፤'),
  ('b1801685-2ea4-56f2-a463-0775930cda32', '97fb980f-9654-581c-ad42-837d545b3305', '9b2e6780-d88e-56a0-aa0a-bb503a299a54', 10, 10, 'እኔ ግን ከምስጋናና ከኑዛዜ ቃል ጋር እሠዋልሃለሁ፤'),
  ('4feb2921-8b61-5380-a089-97f4d7c4ee2a', '97fb980f-9654-581c-ad42-837d545b3305', '9b2e6780-d88e-56a0-aa0a-bb503a299a54', 11, 11, 'እግዚአብሔርም ዓሣ አንበሪውን አዘዘው፤ እርሱም ዮናስን በየብስ ላይ ተፋው።'),
  ('2660ea79-2378-5328-af03-b92e238030b9', '9d9f2a4b-234b-5456-acec-5032ed56fd28', '5b9abb33-e56c-5677-a680-70623f5a38e9', 1, 1, 'የእግዚአብሔርም ቃል ሁለተኛ ወደ ዮናስ እንዲህ ሲል መጣ፦'),
  ('6341b4ae-8d33-5437-a678-fa091d1a9b76', '9d9f2a4b-234b-5456-acec-5032ed56fd28', '5b9abb33-e56c-5677-a680-70623f5a38e9', 2, 2, '“ተነሥተህ ወደዚያች ወደ ታላቂቱ ከተማ ወደ ነነዌ ሂድ፤ የነገርሁህንም የመጀመሪያውን ስብከት ስበክላት” አለው።'),
  ('769fac4c-64f6-5364-a672-a3457de5aa6f', '9d9f2a4b-234b-5456-acec-5032ed56fd28', '5b9abb33-e56c-5677-a680-70623f5a38e9', 3, 3, 'ዮናስም ተነሥቶ እንደ እግዚአብሔር ቃል ወደ ነነዌ ሄደ፤ ነነዌም ታላቅ ከተማ ነበረች፤ የቅጥርዋም ዙሪያ በእግር የሦስት ቀን መንገድ ያህል ነበረ።'),
  ('7a6f85e2-1eca-5741-aa0a-608dd9b8c83b', '9d9f2a4b-234b-5456-acec-5032ed56fd28', '5b9abb33-e56c-5677-a680-70623f5a38e9', 4, 4, 'ዮናስም የአንድ ቀን መንገድ ያህል ወደ ከተማዪቱ ውስጥ ሊገባ ጀመረ፤ ጮኾም፥ “በሦስት ቀን ውስጥ ነነዌ ትገለበጣለች አለ።”'),
  ('42711ea9-15d2-5ad5-adb8-4e5939e3c199', '9d9f2a4b-234b-5456-acec-5032ed56fd28', '5b9abb33-e56c-5677-a680-70623f5a38e9', 5, 5, 'የነነዌ ሰዎችም እግዚአብሔርን አመኑ፤ ለጾም ዐዋጅ ነገሩ፤ ከታላቁም ጀምሮ እስከ ታናሹ ድረስ ማቅ ለበሱ።'),
  ('c48ae095-8612-5348-a7f2-b4d313224b9e', '9d9f2a4b-234b-5456-acec-5032ed56fd28', '5b9abb33-e56c-5677-a680-70623f5a38e9', 6, 6, 'ወሬውም ወደ ነነዌ ንጉሥ ደረሰ፤ እርሱም ከዙፋኑ ተነሥቶ መጐናጸፊያውን አወለቀ፤ ማቅም ለበሰ፤ በአመድም ላይ ተቀመጠ።'),
  ('24ec1eec-27cd-5d43-ae4d-1817d9f91c74', '9d9f2a4b-234b-5456-acec-5032ed56fd28', '5b9abb33-e56c-5677-a680-70623f5a38e9', 7, 7, 'ዐዋጅም አስነገረ፤ በነነዌም ውስጥ የንጉሡንና የመኳንንቱን ትእዛዝ አሳወጀ፤ እንዲህም አለ፥ “ሰዎችና እንስሶች፥ ላሞችና በጎች አንዳች አይቅመሱ፤ አይሰማሩም፤ ውኃንም አይጠጡ፤'),
  ('3c2c3ac9-2fe2-5e20-aea2-a13cc7dc2be9', '9d9f2a4b-234b-5456-acec-5032ed56fd28', '5b9abb33-e56c-5677-a680-70623f5a38e9', 8, 8, 'ሰዎችና እንስሶችም ማቅ ይልበሱ፤ ወደ እግዚአብሔርም በአንድነት ይጩኹ፤ ሰዎችም ሁሉ ከክፉ መንገዳቸውና በእጃቸው ከአለው ግፍ ይመለሱ።'),
  ('96c4f7f7-29a5-54f9-a2b5-ad9508fa63a5', '9d9f2a4b-234b-5456-acec-5032ed56fd28', '5b9abb33-e56c-5677-a680-70623f5a38e9', 9, 9, 'እኛ እንዳንጠፋ እግዚአብሔር ይምራን፥ ከጽኑ ቁጣውም ይመለስ እንደሆነ ማን ያውቃል?”'),
  ('832d808d-b1f6-52c6-aaf4-c5100a502e53', '9d9f2a4b-234b-5456-acec-5032ed56fd28', '5b9abb33-e56c-5677-a680-70623f5a38e9', 10, 10, 'እግዚአብሔርም ከክፉ መንገዳቸው እንደተመለሱ ሥራቸውን አየ፤ እግዚአብሔርም ያደርግባቸው ዘንድ ከተናገረው ክፉ ነገር ተመለሰ፤ አላደረገውምም።'),
  ('367458ac-800f-5d7d-a2d9-9416f67e169f', '4165c29d-01b8-5a08-afd6-27ad7e16c133', '055b196c-3a1e-55d9-a53e-5b9f1ad97cf4', 1, 1, 'ዮናስም ፈጽሞ አዘነ፤ ተከዘም።'),
  ('079adb2b-3116-52c4-ad5e-0f0c5a64289e', '4165c29d-01b8-5a08-afd6-27ad7e16c133', '055b196c-3a1e-55d9-a53e-5b9f1ad97cf4', 2, 2, 'ወደ እግዚአብሔርም ጸለየ፤ እንዲህም አለ፥ “አቤቱ፥ በሀገሬ ሳለሁ የተናገርሁት ይህ አልነበረምን? አንተ ቸርና ይቅር ባይ፥ ታጋሽም፥ ምሕረትህም የበዛ፥ ከክፉው ነገርም የምትመለስ አምላክ እንደ ሆንህ ዐውቄ ነበርና ስለዚህ ወደ ተርሴስ ለመኰብለል ፈጥኜ ነበር።'),
  ('2241147b-70fc-525e-a53c-cb4144e49ab1', '4165c29d-01b8-5a08-afd6-27ad7e16c133', '055b196c-3a1e-55d9-a53e-5b9f1ad97cf4', 3, 3, 'አሁንም አቤቱ! ከሕይወት ሞት ይሻለኛልና እባክህ! ነፍሴን ከእኔ ውሰድ።”'),
  ('d8f9bdf7-43b4-5891-ae59-07839cc1f568', '4165c29d-01b8-5a08-afd6-27ad7e16c133', '055b196c-3a1e-55d9-a53e-5b9f1ad97cf4', 4, 4, 'እግዚአብሔርም ዮናስን፥ “ፈጽመህ ታዝናለህን?” አለው።'),
  ('c89805a3-a05f-59f4-a18f-7f2fc605d13f', '4165c29d-01b8-5a08-afd6-27ad7e16c133', '055b196c-3a1e-55d9-a53e-5b9f1ad97cf4', 5, 5, 'ዮናስም ከከተማዪቱ ወጣ፤ በከተማዪቱም ፊት ለፊት ተቀመጠ፤ በከተማዪቱም የሚሆነውን እስኪያይ ድረስ በዚያ ለራሱ ዳስ ሠርቶ ከጥላው በታች ተቀመጠ።'),
  ('db49b03e-e506-5c50-afba-831eb55ffe37', '4165c29d-01b8-5a08-afd6-27ad7e16c133', '055b196c-3a1e-55d9-a53e-5b9f1ad97cf4', 6, 6, 'እግዚአብሔር አምላክም ቅልን አዘዘ፤ ከጭንቀቱም ታድነው ዘንድ በራሱ ላይ ጥላ እንድትሆን በዮናስ ራስ ላይ ከፍ ከፍ አደረጋት፤ ዮናስም ስለ ቅሊቱ እጅግ ደስ አለው።'),
  ('c787ea10-c8e4-55d3-ac96-816ddc6c5e79', '4165c29d-01b8-5a08-afd6-27ad7e16c133', '055b196c-3a1e-55d9-a53e-5b9f1ad97cf4', 7, 7, 'በነጋው ግን ወገግ ባለ ጊዜ እግዚአብሔር ትልን አዘዘ፤ እርስዋም ቅሊቱን መታቻት፤ ደረቀችም።'),
  ('698d77c1-1527-534d-a0aa-e5e45171d8e1', '4165c29d-01b8-5a08-afd6-27ad7e16c133', '055b196c-3a1e-55d9-a53e-5b9f1ad97cf4', 8, 8, 'ፀሐይም በወጣች ጊዜ እግዚአብሔር ትኩስ የምሥራቅ ነፋስን አዘዘ፤ ዮናስንም እስኪዝል ድረስ ፀሐይ ራሱን መታው፤ ለራሱም ተስፋ ቈርጦ፥ “ከሕይወት ሞት ይሻለኛል” አለ።'),
  ('1a6d7ce2-3a7c-5122-a9b7-63b1bdb7665d', '4165c29d-01b8-5a08-afd6-27ad7e16c133', '055b196c-3a1e-55d9-a53e-5b9f1ad97cf4', 9, 9, 'እግዚአብሔርም ዮናስን፥ “በውኑ ስለዚች ቅል ታዝናለህን?” አለው። እርሱም፥ “እስክሞት ድረስ እጅግ አዝኛለሁ” አለ።'),
  ('4387e815-d206-5670-adc2-90205ea4606c', '4165c29d-01b8-5a08-afd6-27ad7e16c133', '055b196c-3a1e-55d9-a53e-5b9f1ad97cf4', 10, 10, 'እግዚአብሔርም፥ “አንተ ትበቅል ዘንድ ላልደከምህባት፥ ላላሳደግሃትም፥ በአንድ ሌሊት ለበቀለች፥ በአንድ ሌሊትም ለደረቀችው ቅል አዝነሃል።'),
  ('abfaf0ca-5435-5e5a-a93d-6023324022d4', '4165c29d-01b8-5a08-afd6-27ad7e16c133', '055b196c-3a1e-55d9-a53e-5b9f1ad97cf4', 11, 11, 'እኔስ ቀኛቸውንና ግራቸውን የማይለዩ ከመቶ ሃያ ሺህ የሚበልጡ ሰዎችና ብዙ እንስሶች ላሉባት ለታላቂቱ ከተማ ለነነዌ አላዝንምን?” አለው።'),
  ('254302b4-3f4c-5337-afd7-dd05b19be07e', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 1, 1, 'ስለ ነነዌ የተነገረ ሸክም፣ የኤልቆሻዊው የናሆም የራእዩ መጽሐፍ ይህ ነው።'),
  ('6e461a58-93de-51d9-a999-e089a3dc97e1', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 2, 2, 'እግዚአብሔር ቀናተኛና ተበቃይ አምላክ ነው፣ እግዚአብሔር ተበቃይና መዓትን የተሞላ ነው፣ እግዚአብሔር ተቃዋሚዎቹን ይበቀላል፥ ለጠላቶቹም ቍጣውን ይጠብቃል።'),
  ('8b37ef5d-0b17-592f-a357-863ba63736dc', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 3, 3, 'እግዚአብሔር ትዕግሥተኛ፥ ኃይሉም ታላቅ ነው፥ በደለኛውንም፦ ንጹሕ ነህ አይልም፣ እግዚአብሔር በወጀብና በዐውሎ ነፋስ ውስጥ መንገድ አለው፥ ደመናም የእግሩ ትቢያ ነው።'),
  ('c2f00fb4-48ff-5cce-a5b5-674fe4f28ba0', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 4, 4, 'ባሕሩንም ይገሥጻታል፥ ያደርቃትማል፥ ወንዞችንም ሁሉ ያደርቃል፣ ባሳንና ቀርሜሎስም ላልተዋል፥ የሊባኖስም አበባ ጠውልጎአል።'),
  ('19c1b52c-3757-54cd-a913-ef5eb1b3263f', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 5, 5, 'ተራሮችም ከእርሱ የተነሣ ታወኩ፥ ኮረብቶችም ቀለጡ፣ ምድርና ዓለም የሚኖሩበትም ሁሉ ከፊቱ ተናወጡ።'),
  ('1590888f-d9ec-5ab6-a77c-85278765f29d', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 6, 6, 'በቍጣው ፊት የሚቆም ማን ነው? የቍጣውንም ትኵሳት ማን ይታገሣል? መዓቱ እንደ እሳት ይፈስሳል፥ ከእርሱም የተነሣ ዓለቆች ተሰነጠቁ።'),
  ('be511d3e-da14-5416-a354-3bb354195dc3', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 7, 7, 'እግዚአብሔር መልካም ነው፥ በመከራ ቀንም መሸሸጊያ ነው፣ በእርሱ የሚታመኑትንም ያውቃል።'),
  ('0f679160-d744-59b2-acc4-8e23e301f613', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 8, 8, 'ስፍራዋን ግን በሚያጥለቀልቅ ጎርፍ ፈጽሞ ያጠፋታል፥ ጠላቶቹንም ወደ ጨለማ ያሳድዳቸዋል።'),
  ('1166ec2f-7e49-5a49-a944-da6a3dffe523', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 9, 9, 'በእግዚአብሔር ላይ የምታስቡት ምንድር ነው? እርሱ ፈጽሞ ያጠፋል፥ መከራም ሁለተኛ አይነሣም።'),
  ('57651a87-7150-5a1f-af93-470c5ea55e55', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 10, 10, 'እርስ በእርሳቸው እንደ ተመሰቃቀለ እሾህ ቢሆኑ፥ በመጠጣቸውም ቢሰክሩ እንደ ደረቅ ገለባ ፈጽመው ይጠፋሉ።'),
  ('52a3c636-0ab0-5c67-adcf-94da8d8e968e', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 11, 11, 'በእግዚአብሔር ላይ በክፉ የሚያስብ፥ ክፋትን የሚመክር፥ ከአንተ ዘንድ ወጥቶአል።'),
  ('b72d23ea-ad75-5cbb-a117-0c933b7e1229', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 12, 12, 'እግዚአብሔር እንዲህ ይላል፦ ኃይለኞችና ብዙዎች ቢሆኑ እንዲሁ ይቈረጣሉ፥ እርሱም ያልቃል። እኔም አስጨንቄሃለሁ፥ ነገር ግን ከእንግዲህ ወዲህ አላስጨንቅህም።'),
  ('4a55358c-309c-571a-ada6-d583e6f8b350', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 13, 13, 'አሁንም ቀንበሩን ከአንተ እሰብራለሁ፥ እስራትህንም እበጥሳለሁ።'),
  ('59c57017-86e2-5bc6-a385-48e58d887407', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 14, 14, 'እግዚአብሔርም ከስምህ ማንም ከእንግዲህ ወዲህ እንዳይዘራ ስለ አንተ አዝዞአል፣ ከአምላኮችህ ቤት የተቀረጸውንና ቀልጦ የተሠራውን ምስል አጠፋለሁ። አንተም የተጠቃህ ነህና መቃብርህን እምሳለሁ።'),
  ('fbaec5da-64b1-539c-a4e3-a3b31a1c4af5', '8e576072-0a86-5235-a2fa-9b31a7edec50', '95bb5d6a-d31a-5a6f-ae85-3771d6a0cdc4', 15, 15, 'እነሆ፥ የምስራችን የሚያመጣ ሰላምንም የሚያወራ ሰው እግር በተራሮች ላይ ነው! ይሁዳ ሆይ፥ አጥፊው ፈጽሞ ጠፍቶአልና፥ ከእንግዲህም ወዲህ በአንተ ዘንድ አያልፍምና ዓመት በዓሎችህን አድርግ፥ ስእለቶችህን ክፈል።'),
  ('115236c1-f20e-5ebc-a674-d381fecc16fa', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 1, 1, 'የሚቀጠቅጥ በአንተ ላይ ወጥቶአል፣ ምሽግን ጠብቅ፥ መንገድንም ሰልል፣ ወገብህን አጽና፥ ኃይልህንም እጅግ አበርታ።'),
  ('3158621e-ac4e-5fc9-aaf4-9351d4b4eea6', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 2, 2, 'ዘራፊዎች ዘርፈዋቸዋልና፥ የወይናቸውንም አረግ አጥፍተዋልና እግዚአብሔር የያዕቆብን ክብር እንደ እስራኤል ክብር ይመልሳል።'),
  ('c4466ecf-bd52-547e-ac9b-48cde5f99b31', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 3, 3, 'የኃያላኑ ጋሻ ቀልቶአል፥ ጽኑዓንም ቀይ ልብስ ለብሰዋል። እርሱም በሚያዘጋጅበት ቀን ሰረገሎች እንደ እሳት ይንቦገቦጋሉ፣ የጦሩም ሶመያ ይወዛወዛል።'),
  ('d40566b8-42d4-5053-a254-dd8d8930f5ec', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 4, 4, 'ሰረገሎች በመንገድ ላይ ይነጕዳሉ፥ አደባባይም ይጋጫሉ፣ መልካቸው እንደ ፋና ነው፥ እንደ መብረቅም ይከንፋሉ።'),
  ('1cb75448-12a4-5552-a6cc-bddb40a2a10f', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 5, 5, 'መሳፍንቱን ያስባል፣ በአረማመዳቸው ይሰናከላሉ፣ ፈጥነው በቅጥርዋ ላይ ይወጣሉ፥ መጠጊያም ተዘጋጀለት።'),
  ('9fefd0a0-3a12-5b53-a4c9-20ffd41db225', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 6, 6, 'የወንዞቹም መዝጊያዎች ተከፈቱ፥ የንጉሡ ቤትም ቀለጠች።'),
  ('29682077-5cbc-51c4-a4e1-666f405917aa', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 7, 7, 'ንግሥት ተገለጠች፥ ተማረከችም፥ ሴቶች ባሪያዎችዋም እንደ ርግብ እየጮኹና ደረታቸውን እየመቱ ዋይ ዋይ ይላሉ።'),
  ('26893262-8377-5a98-aac8-3394520b9567', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 8, 8, 'ነነዌ ግን ከዱሮ ዘመን ጀምራ እንደ ተከማቸ ውኃ ነበረች፣ አሁን ግን ይሸሻሉ፣ እነርሱም፦ ቁሙ፥ ቁሙ ይላሉ፥ ነገር ግን የሚመለስ የለም።'),
  ('7d6e2052-7fa6-5a77-a3fe-dcedd0afe369', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 9, 9, 'መዝገብዋ መጨረሻ የለውምና፥ የከበረውም የዕቃዋ ሁሉ ብዛት አይቈጠርምና ብሩን በዝብዙ፥ ወርቁንም በዝብዙ።'),
  ('78a02bce-8e3f-54dc-a7db-359a16e0c925', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 10, 10, 'ባዶና ባድማ ምድረ በዳም ሆናለች፣ ልብ ቀልጦአል፥ ጕልበቶችም ተብረክርከዋል፣ በወገብም ሁሉ ሕማም አለ፥ የሰዎችም ሁሉ ፊት ጠቍሮአል።'),
  ('7fc26321-20e7-5a07-a212-b49771f4655e', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 11, 11, 'የአንበሾችም መደብ፥ የአንበሾችም ደቦል የሚሰማራበት፥ አንበሳውና አንበሳይቱ ግልገሉም ሳይፈሩ የሚሄዱት ስፍራ ወዴት ነው?'),
  ('f432c610-267a-5ff8-a28e-48f258aa4201', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 12, 12, 'አንበሳው ለልጆቹ የሚበቃውን ነጠቀ፥ ለእንስቶቹም ሰበረላቸው ዋሻውን በንጥቂያ፥ መደቡንም በቅሚያ ሞልቶታል።'),
  ('a1616a8a-ca6d-53cf-a9e9-229e67af3d15', '5c4f3123-2688-5602-a8af-f5f6b0e4dc28', '0998230e-b2f3-56d9-a279-599b6b6c2c83', 13, 13, 'እነሆ በአንቺ ላይ ነኝ፥ ይላል የሠራዊት ጌታ እግዚአብሔር፣ ሰረገሎችዋንም አቃጥዬ አጤሳለሁ፥ ሰይፍም የአንበሳ ደቦሎችሽን ይበላቸዋል፣ ንጥቂያሽንም ከምድር አጠፋለሁ፥ የመልክተኞችሽን ድምፅ ከእንግዲህ ወዲህ አይሰማም።'),
  ('5c0bb134-365a-5903-aa22-4fce449beb89', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 1, 1, 'ለደም ከተማ ወዮላት! በሁለንተናዋ ሐሰትና ቅሚያ ሞልቶባታል፣ ንጥቂያ ከእርስዋ አያልቅም።'),
  ('582f39d9-73ac-5ba5-af73-dbd7ec6b73ca', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 2, 2, 'የአለንጋ ድምፅ፥ የመንኰራኵርም ድምፅ፥ የፈረሶችም ኮቴ፥ የፈጣን ሰረገላም ጩኸት ተሰምቶአል፣'),
  ('4f40a25b-f9e1-50ca-af80-3cd2560dcf5e', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 3, 3, 'ፈረሰኛው ይጋልባል፥ ሰይፍም ይንቦገቦጋል፥ ጦርም ይብለጨለጫል፣ የተገደሉትም ይበዛሉ፥ በድኖችም በክምር ይከመራሉ፥ ሬሳቸውም አይቈጠርም፣ በሬሳቸውም ይሰናከላሉ።'),
  ('4c7259a1-ba0d-52e7-a380-b3c729f772cb', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 4, 4, 'ስለ ተዋበችው ጋለሞታ ግልሙትና ብዛት ይህ ሆኖአል፣ እርስዋም በመተትዋ እጅግ በለጠች፥ አሕዛብንም በግልሙትናዋ፥ ወገኖችንም በመተትዋ ሸጠች።'),
  ('79cf7708-7745-555d-aeeb-00f583745785', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 5, 5, 'እነሆ፥ በአንቺ ላይ ነኝ፥ ይላል የሠራዊት ጌታ እግዚአብሔር፥ ልብስሽን በፊትሽ እገልጣለሁ፣ ኅፍረተ ሥጋሽንም ለአሕዛብ፥ ነውርሽንም ለመንግሥታት አሳያለሁ።'),
  ('4859f09d-5dd4-5fe8-a919-effa85251723', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 6, 6, 'ርኵሰትንም በላይሽ እጥላለሁ፥ እንቅሽማለሁ፥ ማላገጫም አደርግሻለሁ።'),
  ('8353c7fe-5449-5387-a652-a1c7aebeec87', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 7, 7, 'የሚያይሽም ሁሉ ከአንቺ ሸሽቶ፦ ነነዌ ባድማ ሆናለች፣ የሚያለቅስላትስ ማን ነው? የሚያጽናናትንስ ከወዴት እፈልጋለሁ? ይላል።'),
  ('dfdde4b8-1d7a-583a-a493-ce12e1920b97', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 8, 8, 'አንቺ በመስኖች መካከል ከተቀመጠችው፥ ውኃም በዙሪያዋ ከነበራት፥ ምሽግዋም ባሕር ከነበረ፥ ቅጥርዋም በባሕር ውስጥ ከነበረ ከኖእ አሞን ትበልጫለሽን?'),
  ('655ef38f-f990-5e82-a583-fa36d5a6913e', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 9, 9, 'ኢትዮጵያና ግብጽ የማይቈጠር ኃይልዋ ነበሩ፣ ፉጥና ልብያ ረዳቶችዋ ነበሩ።'),
  ('1db3ee65-9aa5-5701-a1c3-6086c72131d5', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 10, 10, 'እርስዋ ግን ተማርካ ፈለሰች፣ ሕፃናቶችዋ በመንገድ ሁሉ ራስ ላይ ተፈጠፈጡ፣ በከበርቴዎችዋም ላይ ዕጣ ተጣጣሉ፥ ታላላቆችዋም ሁሉ በሰንሰለት ታሰሩ።'),
  ('f9dbd005-e5d8-5c9d-a8c3-d776f16d7017', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 11, 11, 'አንቺም ትሰክሪአለሽ ወራዳም ትሆኛለሽ፣ አንቺ ደግሞ ከጠላት የተነሣ መጠጊያን ትፈልጊአለሽ።'),
  ('ee8e48e7-8aa6-504b-ae81-97a4f97bedfa', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 12, 12, 'አምባሽ ሁሉ የመጀመሪያውን የበሰለ ፍሬ እንደ ያዙ እንደ በለስ ዛፎች ነው፣ ቢወዛወዝ በሚበላው አፍ ውስጥ ይወድቃል።'),
  ('dab3b6d9-45e1-524a-adcb-dce5c2c901dd', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 13, 13, 'እነሆ፥ በመካከልሽ ያሉ ሕዝብሽ ሴቶች ናቸው፣ የአገርሽ በሮች ለጠላቶችሽ ፈጽሞ ተከፍተዋል፥ እሳትም መወርወሪያዎችህን በልቶአል።'),
  ('c25e7410-a09e-5efc-a2e5-ca720ef17bb3', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 14, 14, 'ከብበው ያስጨንቁሻልና ውኃን ቅጂ፣ አምባሽን አጠንክሪ፣ ወደ ጭቃ ገብተሽ እርገጪ፣ የጡብን መሠሪያ ያዢ።'),
  ('f7145d8a-3bd3-5960-a174-5cc1f45688d7', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 15, 15, 'በዚያ እሳት ይበላሻል፥ ሰይፍ ያጠፋሻል፥ እንደ ደጎብያ ይበላሻል፣ እንደ ደጎብያ ብዢ፥ እንደ አንበጣም ተባዢ።'),
  ('7ecd1dc2-0123-5d89-a6b3-2ca851a260be', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 16, 16, 'ነጋዴዎችሽን ከሰማይ ከዋክብት ይልቅ አበዛሽ፣ ደጎብያ ተዘረጋ፥ በረረም።'),
  ('b7bcdf2f-a5ab-5906-a803-a9f47a7b2a8f', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 17, 17, 'በአንቺ ዘንድ ዘውድ የጫኑት እንደ አንበጣ፥ አለቆችሽም እንደሚንቀሳቀሱ ኩብኩባዎች ናቸው፣ በብርድ ቀን በቅጥር ውስጥ ይቀመጣሉ፥ ፀሐይም በወጣች ጊዜ ያኰበኵባሉ፣ ስፍራቸው በየት እንደ ሆነ አይታወቅም።'),
  ('36add612-302a-51d8-ab21-1a61c2268e29', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 18, 18, 'የአሦር ንጉሥ ሆይ፥ እረኞችህ አንቀላፍተዋል፣ መኳንንቶችህም ዐርፈዋል፣ ሕዝብህም በተራሮች ላይ ተበትኖአል፥ የሚሰበስበውም የለም።'),
  ('a6fca502-613f-5f35-ac2b-9e3a7237293e', '5e69a8eb-d076-5f6e-a48c-a5a857d23020', '4d9c6833-502c-5712-a996-c291c7349e8a', 19, 19, 'ስብራትህ አይፈወስም፥ ቁስልህም ክፉ ነው፣ ወሬህንም የሚሰሙ ሁሉ እጃቸውን በአንተ ላይ ያጨበጭባሉ፣ ክፋትህ ሁልጊዜ ያላለፈችበት ሰው ማን ነውና?'),
  ('876acac5-b1f4-5018-a00e-cd779f89b090', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 1, 1, 'ነቢዩ ዕንባቆም ያየው ሸክም ይህ ነው።'),
  ('59c037e3-56ec-53be-a5d3-f166aab9f2f1', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 2, 2, 'አቤቱ፥ እኔ ስጮኽ የማትሰማው እስከ መቼ ነው? ስለ ግፍ ወደ አንተ እጮኻለሁ፥ አንተም አታድንም።'),
  ('9c19239f-0bd0-5eb7-a4a7-a7edcfb4f66c', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 3, 3, 'በደልንስ ስለ ምን አሳየኸኝ? ጠማምነትንስ ስለ ምን ትመለከታለህ? ጥፋትና ግፍ በፊቴ ነው፣ ጠብና ክርክር ይነሣሉ።'),
  ('06137a6f-4c02-5d3f-a910-bc3bd18de06c', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 4, 4, 'ስለዚህ ሕግ ላልቶአል፥ ፍርድም ድል ነሥቶ አይወጣም፣ ኃጢአተኛ ጻድቅን ይከብባልና፣ ስለዚህ ፍርድ ጠማማ ሆኖ ይወጣል።'),
  ('3ece91b7-d0e5-5142-a236-d96d7c4f0ec2', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 5, 5, 'እናንተ የምትንቁ ሆይ፥ አንድ ቢተርክላችሁ ስንኳ የማታምኑትን ሥራ በዘመናችሁ እሠራለሁና እዩ፥ ተመልከቱ፥ ተደነቁ።'),
  ('99d4798a-a2a3-52da-a832-73b40e58aa59', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 6, 6, 'እነሆ፥ የእነርሱ ያልሆነውን መኖሪያ ይወርሱ ዘንድ በምድር ስፋት ላይ የሚሄዱትን መራሮችንና ፈጣኖችን ሕዝብ ከለዳውያንን አስነሣለሁ።'),
  ('0615ada1-dd61-5ee4-a8c5-87f9bee14168', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 7, 7, 'እነርሱ የሚያስፈሩና የሚያስደነግጡ ናቸው፣ ፍርዳቸውና ክብራቸው ከራሳቸው ይወጣል።'),
  ('244b35a5-1812-57c2-a60a-f4cd11a28504', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 8, 8, 'ፈረሶቻቸውም ከነብር ይልቅ ፈጣኖች ናቸው፥ ከማታም ተኵላ ይልቅ ጨካኞች ናቸው፣ ፈረሰኞቻቸውም ይንሳፈፋሉ፥ ከሩቅም ይመጣሉ፥ ለመብልም እንደሚቸኵል ንስር ይበርራሉ።'),
  ('7d4837e4-c03f-5af1-a634-fb88dbba67e2', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 9, 9, 'ሁሉም ለግፍ ሥራ ይመጣሉ፥ ፊታቸውንም እንደ ምሥራቅ ነፋስ ያቀናሉ፣ ምርኮኞችንም እንደ አሸዋ ይሰበስባሉ።'),
  ('e16af788-4020-5b1e-a4a7-b9e2426f2267', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 10, 10, 'በነገሥታት ላይ ያላግጣሉ፥ መሳፍንትም ዋዛ ሆነውላቸዋል፣ በምሽጉ ሁሉ ይስቃሉ፥ አፈሩንም ከምረው ይወስዱታል።'),
  ('f982f569-048b-5122-a725-e982117b6cfb', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 11, 11, 'የዚያን ጊዜም እንደ ነፋስ አልፎ ይሄዳል፥ ይበድልማል፣ ኃይሉንም አምላክ ያደርገዋል።'),
  ('bb4eab12-0372-566f-a861-e99ad4f2e0bf', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 12, 12, 'አቤቱ፥ የተቀደስህ አምላኬ ሆይ፥ አንተ ከዘላለም ጀምሮ አልነበርህምን? እኛ አንሞትም፣ አቤቱ፥ ለፍርድ ሠርተኸዋል፥ ለተግሣጽም አድርገኸዋል።'),
  ('43951f25-8c23-585e-a90d-71a9713acc59', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 13, 13, 'ዓይኖችህ ክፉ እንዳያዩ ንጹሐን ናቸው፥ ጠማምነትንም ትመለከት ዘንድ አትችልም፣ አታላዮችንስ ለምን ትመለከታለህ? ኃጢአተኛውስ ከእርሱ ይልቅ ጻድቅ የሆነውን ሲውጠው ስለምን ዝም ትላለህ?'),
  ('27917cb0-f508-5ef0-a18b-7751485a2371', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 14, 14, 'ሰዎችንም እንደ ባሕር ዓሣዎች፥ አለቃም እንደሌላቸው ተንቀሳቃሾች ለምን ታደርጋቸዋለህ?'),
  ('88304db2-2abe-5f04-a6b8-a7016959a66c', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 15, 15, 'ሁሉን በመቃጥን ያወጣል፥ በመረቡም ይይዛቸዋል፥ በአሽክላውም ውስጥ ያከማቻቸዋል፣ ስለዚህ ደስ እያለው እልል ይላል።'),
  ('865df825-ac4d-5e03-a6e8-4e66bdc09a7d', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 16, 16, 'እድል ፈንታው በእነርሱ ሰብታለችና፥ መብሉም በዝቶአልና ስለዚህ ለመረቡ ይሠዋል፥ ለአሽክላውም ያጥናል።'),
  ('994865b3-b89a-56bb-ad06-565c205f9cea', 'ca057305-7adc-55aa-a721-e2acc03c2f41', 'ee6d464a-e536-53c7-a49d-a0eab4f5b14f', 17, 17, 'ስለዚህ መረቡን ይጥላልን? አሕዛብንም ዘወትር ይገድል ዘንድ አይራራምን?'),
  ('1097720c-10ef-5003-ab3a-ef519ff41166', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 1, 1, 'በመጠበቂያዬ ላይ እቆማለሁ፥ በአምባ ላይም እወጣለሁ፣ የሚናገረኝንም፥ ስለ ክርክሬም የምመልሰውን አውቅ ዘንድ እመለከታለሁ።'),
  ('b645eca2-116e-57fa-a2bc-2a28d0886cbd', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 2, 2, 'እግዚአብሔርም መለሰልኝ እንዲህም አለ፦ አንባቢው ይፈጥን ዘንድ ራእዩን ጻፍ፥ በጽላትም ላይ ግለጠው።'),
  ('b8bc3bf2-ebde-5339-a7b8-60bee191d23e', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 3, 3, 'ራእዩ ገና እስከ ተወሰነው ጊዜ ነው፥ ወደ ፍጻሜውም ይቸኵላል፥ እርሱም አይዋሽም፣ ቢዘገይም በእርግጥ ይመጣልና ታገሠው፣ እርሱ አይዘገይም።'),
  ('69fab017-b7f9-5888-a011-ba5d4a0dc307', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 4, 4, 'እነሆ፥ ነፍሱ ኰርታለች፥ በውስጡም ቅን አይደለችም፣ ጻድቅ ግን በእምነቱ በሕይወት ይኖራል።'),
  ('bd88da77-33da-505b-a795-21ba644a390a', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 5, 5, 'እርሱ አታላይና ኵሩ ሰው ነው፣ በስፍራው ዐርፎ አይቀመጥም፣ ስስቱን እንደ ሲኦል ያሰፋል፥ እርሱም እንደ ሞት አይጠግብም፣ አሕዛብንም ሁሉ ወደ እርሱ ይሰበስባል፥ ወገኖቹንም ሁሉ ወደ እርሱ ያከማቻል።'),
  ('56a7415e-04e8-5dc3-aa35-5e362ab47610', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 6, 6, 'እነዚህ ሁሉ፦ ለእርሱ ያልሆነውን ወደ እርሱ ለሚሰበስብ መያዣውንም ለራሱ የሚያበዛ ወዮለት! እስከ መቼ ነው? እያሉ ምሳሌ አይመስሉበትምን?'),
  ('f0348945-f51c-5309-a2c7-f29ea713c56b', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 7, 7, 'ተረትም አይተርቱበትምን? የሚነክሱህ ድንገት አይነሡብህምን? የሚያስጨንቁህም ይነቃሉ፣ ለእነርሱም ብዝበዛ ትሆናለህ።'),
  ('42fe69aa-f5db-5c76-a86b-da152a23b79e', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 8, 8, 'የሰውን ደም ስላፈሰስህ፥ በምድሪቱና በከተማይቱም በእርስዋም በሚኖሩ ሁሉ ላይ ስላደረግኸው ግፍ፥ አንተ ብዙዎችን አሕዛብን በዝብዘሃልና ከአሕዛብ የቀሩት ሁሉ ይበዘብዙሃል።'),
  ('e68d10a4-fe71-5307-ae96-025dc94ab008', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 9, 9, 'ከክፉ እንዲድን ጐጆውን በከፍታ ላይ ያደርግ ዘንድ ለቤቱ ክፉ ትርፍን ለሚሰበስብ ወዮለት!'),
  ('296edb4a-d227-5360-aec7-3d6ecb95bfc4', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 10, 10, 'ብዙ አሕዛብን አጥፍተሃልና ለቤትህ እፍረትን መክረሃል፥ በነፍስህም ላይ ኃጢአትን አድርገሃል።'),
  ('ff5037d0-92db-5d97-af52-b803aa45f57d', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 11, 11, 'ድንጋይም ከግንብ ውስጥ ይጮኻል፥ እንጨትም ከውቅር ውስጥ ይመልስለታል።'),
  ('b4051270-d5eb-554d-a03e-5204e787058c', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 12, 12, 'ከተማን በደም ለሚሠራ፥ ከተማንም በኃጢአት ለሚመሠርት ወዮለት!'),
  ('ef434974-669f-5092-abcd-031abfdce815', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 13, 13, 'እነሆ፥ አሕዛብ ስለ እሳት እንዲሠሩ፥ ወገኖችም ስለ ከንቱነት እንዲደክሙ ከሠራዊት ጌታ ከእግዚአብሔር ዘንድ የሆነ አይደለምን?'),
  ('d7018433-49cd-5d9b-aa5a-f617a4eb160f', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 14, 14, 'ውኃ ባሕርን እንደሚከድን ምድር የእግዚአብሔርን ክብር በማወቅ ትሞላለችና።'),
  ('e99deb78-a4d8-5e9c-a34a-0a2e648cb1c6', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 15, 15, 'ኅፍረተ ሥጋውን ለማየት ባልንጀራውን ለሚያጠጣ፥ ክፉንም ለሚጨምርበት፥ ለሚያሰክረውም ወዮለት!'),
  ('fa8d14e7-d26d-56d2-aba2-cbca21434a0b', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 16, 16, 'በክብር ፋንታ እፍረት ሞልቶብሃል፣ አንተ ደግሞ ጠጥተህ ተንገድገድ፣ የእግዚአብሔር የቀኙ ጽዋ ይመለስብሃል፥ እፍረትም በክብርህ ላይ ይሆናል።'),
  ('25c69979-5d07-5342-a0aa-9f874bfb3a7f', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 17, 17, 'የሰውንም ደም ስላፈሰስህ፥ በምድሪቱና በከተማይቱም በእርስዋም በሚኖሩ ሁሉ ላይ ስላደረግኸው ግፍ፥ በሊባኖስ ላይ የሠራኸው ግፍ ይከድንሃል፣ የአራዊትም አደጋ ያስፈራራሃል።'),
  ('868f1cb8-1231-5df4-a15c-b93078213ccc', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 18, 18, 'የተቀረጸውን ምስል ሠሪው የቀረጸው ለምን ጥቅም ነው? ዲዳንም ጣዖት ይሠራ ዘንድ ሠሪው የታመነበቱ፥ ሐሰትን የሚያስተምር ቀልጦ የተሠራ ምን ይጠቅማል?'),
  ('158625ec-88d3-5d5c-a2e9-a23f2abb2b98', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 19, 19, 'እንጨቱን፦ ንቃ፥ ዲዳውንም ድንጋይ፦ ተነሣ ለሚለው ወዮለት! በውኑ ይህ ያስተምራልን? እነሆ፥ በወርቅና በብር ተለብጦአል፥ ምንም እስትንፋስ የለበትም።'),
  ('6f21c8c6-9842-54d8-a9d3-51e97e0e306e', '5c48a16c-69df-51bb-af62-3bdb18ff6ef3', 'b2fe7b7b-6c4a-51a7-acbf-95bc88293e72', 20, 20, 'እግዚአብሔር ግን በተቀደሰ መቅደሱ አለ፣ ምድርም ሁሉ በፊቱ ዝም ትበል።'),
  ('a39e9cf6-fb48-5f5f-a0b4-808a87c109a2', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 1, 1, 'የነቢዩ የዕንባቆም ጸሎት በመዝሙር።'),
  ('391ad961-3b50-5ebf-a1ec-8c941dc06d54', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 2, 2, 'አቤቱ፥ ዝናህን ሰምቼ ፈራሁ፣'),
  ('c8444be2-49ad-54da-af0d-fa34e83ebf9b', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 3, 3, 'እግዚአብሔር ከቴማን፥'),
  ('44583c40-5736-5ab8-a706-8348a18a7d60', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 4, 4, 'ፀዳሉም እንደ ብርሃን ነው፣'),
  ('9168f942-5353-5764-a61d-561f806f5677', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 5, 5, 'ቸነፈር በፊቱ ይሄዳል፥'),
  ('390c73f2-588a-517a-a470-b4abbefedd7a', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 6, 6, 'ቆመ፥ ምድርንም አወካት፣'),
  ('64bfa552-740c-5fd4-abf2-3b0061f52f31', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 7, 7, 'የኢትዮጵያ ድንኳኖች ሲጨነቁ አየሁ፣'),
  ('c595a4ca-e61a-5ef2-a44a-3567f140211d', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 8, 8, 'በውኑ እግዚአብሔር በወንዞች ላይ ተቈጥቶአልን?'),
  ('7d5d0812-9c8b-5ff6-a6d9-51fcddee4b2d', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 9, 9, 'በቃልህ እንደ ማልህ'),
  ('7ff27760-d0cf-577a-aaed-6cfceffa9cf4', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 10, 10, 'ተራሮች አንተን አይተው ተጨነቁ፣'),
  ('f31c65c0-0ea7-5d45-abc8-6e3aff8ec3f8', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 11, 11, 'ፍላጾችህ ከወጡበት ብርሃን የተነሣ፥'),
  ('a0063b67-b3cb-5014-a9b5-71f29ef00d5b', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 12, 12, 'በምድር ላይ በመዓት ተራመድህ፣'),
  ('97e85c36-ea46-5a26-a4ea-33aaa77f18d3', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 13, 13, 'ሕዝብህን ለመታደግ፥'),
  ('5120cfb6-0bfd-527e-a3c7-38a3c73c6990', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 14, 14, 'የአለቆችን ራስ በገዛ በትራቸው ወጋህ፣'),
  ('d01a5909-1d5d-5003-a429-d5bb80b1883d', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 15, 15, 'ፈረሶችህን በባሕር፥'),
  ('7016157b-1751-5784-a213-1eaf1386baae', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 16, 16, 'እኔ ሰምቻለሁ፥ ልቤም ደነገጠብኝ፣'),
  ('763c1972-0aa1-5990-a687-b097e16e9e20', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 17, 17, 'ምንም እንኳ በለስም ባታፈራ፥'),
  ('aca1582e-4dc8-567a-a79c-0833f49744cf', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 18, 18, 'እኔ ግን በእግዚአብሔር ደስ ይለኛል፣'),
  ('7cbfc7cb-1303-5299-a259-e62d071df60e', '32cd61a5-95aa-5b7d-a977-5b99952efc8c', 'e7876f3b-7c03-59a0-aecb-fd2f8545e630', 19, 19, 'ጌታ እግዚአብሔር ኃይሌ ነው፣'),
  ('29b83e61-cfd7-56ad-a4e4-4b0352f5655b', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 1, 1, 'በይሁዳ ንጉሥ በአሞጽ ልጅ በኢዮስያስ ዘመን ወደ ሕዝቅያስ ልጅ ወደ አማርያ ልጅ ወደ ጎዶልያስ ልጅ ወደ ኵሲ ልጅ ወደ ሶፎንያስ የመጣ የእግዚአብሔር ቃል ይህ ነው።'),
  ('44764111-6f89-5a08-a461-d5faa14e4604', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 2, 2, 'ነገርን ሁሉ ከምድር ፊት ፈጽሜ አጠፋለሁ፥ ይላል እግዚአብሔር።'),
  ('b58a3fee-8047-58c5-ab5d-46816c766969', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 3, 3, 'ሰውንና እንስሳን አጠፋለሁ፣ የሰማይን ወፎችና የባሕርን ዓሣዎች ማሰናከያንም ከኃጢአተኞች ጋር አጠፋለሁ፣ ሰውንም ከምድር ፊት እቈርጣለሁ፥ ይላል እግዚአብሔር።'),
  ('d8512608-b3f4-588b-aec8-06bed7a26cff', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 4, 4, 'እጄንም በይሁዳ ላይ በኢየሩሳሌምም በሚኖሩት ሁሉ ላይ እዘረጋለሁ፣ ከዚህም ስፍራ የበኣልን ቅሬታና የጣዖታቱን ካህናት ስም አጠፋለሁ፣'),
  ('f7e5f1d6-ebda-5612-a69e-d5ed668eee59', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 5, 5, 'በሰገነትም ላይ ለሰማይ ሠራዊት የሚሰግዱትን፥ በእግዚአብሔርና በንጉሣቸው በሚልኮም ምለው የሚሰግዱትን፥'),
  ('a3f8df12-0d70-51b6-aac4-b37b14547e70', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 6, 6, 'እግዚአብሔርንም ከመከተል የተመለሱትን፥ እግዚአብሔርንም ያልፈለጉትንና ያልጠየቁትን አጠፋለሁ።'),
  ('8e81782f-9c36-5d2b-a3eb-6e37e18108f7', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 7, 7, 'የእግዚአብሔር ቀን ቀርቦአልና፥ እግዚአብሔር መሥዋዕትን አዘጋጅቶአልና፥ የጠራቸውንም ቀድሶአልና በጌታ በእግዚአብሔር ፊት ዝም በሉ።'),
  ('f4bb6ec3-acf7-565a-a1af-423ddfa8ee77', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 8, 8, 'በእግዚአብሔርም መሥዋዕት ቀን አለቆችንና የንጉሥን ልጆች እንግዳ ልብስ የሚለብሱትንም ሁሉ እቀጣለሁ።'),
  ('9fdc2cda-c3ca-5369-aa2d-ddabd5e2db46', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 9, 9, 'በዚያም ቀን በመድረኩ ላይ የሚዘልሉትን፥ የጌታቸውን ቤት ዓመፃንና ሽንገላን የሚሞሉትን እቀጣለሁ።'),
  ('54511037-2818-596b-abd9-2bccb0605c41', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 10, 10, 'በዚያ ቀን፥ ይላል እግዚአብሔር፥ ከዓሣው በር የጩኸት ድምፅ፥ ከከተማውም በሁለተኛው ክፍል ውካታ፥ ከኮረብቶቹም ታላቅ ሽብር ይሆናል።'),
  ('22c68b76-2484-5388-a490-929c2f73b279', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 11, 11, 'እናንተ በመክቴሽ የምትኖሩ ሆይ፥ የከነዓን ሕዝብ ሁሉ ጠፍተዋልና፥ ብርም የተሸከሙ ሁሉ ተቈርጠዋልና አልቅሱ።'),
  ('5e00eb7a-c2bb-5d43-addd-6cf488929efd', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 12, 12, 'በዚያም ዘመን ኢየሩሳሌምን በመብራት እመረምራለሁ፣ በአተላቸውም ላይ የሚቀመጡትን፥ በልባቸውም፦ እግዚአብሔር መልካምን አያደርግም፥ ክፉም አያደርግም የሚሉትን ሰዎች እቀጣለሁ።'),
  ('0b851a30-6f26-5155-a483-ee701e7d2c50', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 13, 13, 'ብልጥግናቸውም ለምርኮ ይሆናል፥ ቤቶቻቸውም ይፈርሳሉ፣ ቤቶችንም ይሠራሉ፥ ነገር ግን አይቀመጡባቸውም፣ ወይንንም ይተክላሉ፥ የወይን ጠጁን ግን አይጠጡም።'),
  ('7a562738-c210-5662-a640-5e8ba863fe1e', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 14, 14, 'ታላቁ የእግዚአብሔር ቀን ቀርቦአል፣ የእግዚአብሔር ቀን ድምፅ ቀርቦአል እጅግም ፈጥኖአል፣ ኃያሉም በዚያ በመራራ ልቅሶ ይጮኻል።'),
  ('b4129abb-cee1-5520-acd5-137d2df508f4', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 15, 15, 'ያ ቀን የመዓት ቀን የመከራና የጭንቀት ቀን፥ የመፍረስና የመጥፋት ቀን፥ የጨለማና የጭጋግ ቀን፥ የደመናና የድቅድቅ ጨለማ ቀን፥'),
  ('9176ad02-ca6b-500a-ace4-8c30185c99bb', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 16, 16, 'በተመሸጉ ከተሞችና በረዘሙ ግንቦች ላይ የመለከትና የሰልፍ ጩኸት ቀን ነው።'),
  ('832d1cff-2718-5018-a33c-08207e41bcdd', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 17, 17, 'በእግዚአብሔርም ላይ ኃጢአት ሠርተዋልና እንደ ዕውር እስኪሄዱ ድረስ ሰዎችን አስጨንቃለሁ፣ ደማቸውም እንደ ትቢያ፥ ሥጋቸውም እንደ ጕድፍ ይፈስሳል።'),
  ('3b3fb152-c4c1-551e-aaa8-2408948f2cd1', '8bf4879b-e2f2-52d7-a0ec-a3814c005a9a', 'de8ec24f-8ec5-5db2-ad70-e04d1318fcb4', 18, 18, 'በእግዚአብሔርም ቍጣ ቀን ብራቸውና ወርቃቸው ሊያድናቸው አይችልም፣ እርሱም በምድር የሚኖሩትን ሁሉ ፈጥኖ ይጨርሳቸዋልና ምድር ሁሉ በቅንዓቱ እሳት ትበላለች።'),
  ('92d91f41-3fe2-5b40-a74b-280c50eb73d3', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 1, 1, 'እናንተ እፍረት የሌላችሁ ሕዝብ ሆይ፥ ትእዛዝ ሳይወጣ፥ ቀኑም እንደ ገለባ ሳያልፍ፥ የእግዚአብሔርም ቍጣ ትኵሳት ሳይመጣባችሁ፥ የእግዚአብሔርም ቍጣ ቀን ሳይደርስባችሁ ተሰብሰቡ፥ ተከማቹም።'),
  ('a7eb3255-17f4-57dc-aa2b-1def16fab4b0', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 2, 3, 'እናንተ ፍርዱን የጠበቃችሁ የምድር ትሑታን ሁሉ፥ እግዚአብሔርን ፈልጉ፣ ጽድቅንም ፈልጉ፥ ትሕትናንም ፈልጉ፣ ምናልባት በእግዚአብሔር ቍጣ ቀን ትሰወሩ ይሆናል።'),
  ('39fbe275-f775-5a33-a35d-f40b6945b0b5', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 3, 4, 'ጋዛ ትበረበራለች፥ አስቀሎናም ባድማ ትሆናለች፣ አዛጦንንም በቀትር ወደ ውጭ ያሳድዱአታል፥ አቃሮንም ትነቀላለች።'),
  ('09ecc81a-0007-5394-acce-49d5e2e5b99c', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 4, 5, 'በባሕር ዳር ለሚኖሩ ለከሊታውያን ሕዝብ ወዮላቸው! የፍልስጥኤማውያን ምድር ከነዓን ሆይ፥ የእግዚአብሔር ቃል በአንተ ላይ ነው፥ የሚቀመጥብህም ሰው እንዳይኖር አጠፋሃለሁ።'),
  ('1685eddd-f482-5e83-ad4c-447e2a917fad', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 5, 6, 'ቀርጤስም የእረኞች መኖሪያና የመንጎች በረት ይሆናል።'),
  ('f2c48bd0-b9ef-5bfa-a710-f0a6200bba0a', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 6, 7, 'የባሕሩም ዳር ለይሁዳ ቤት ቅሬታ ይሆናል፥ በዚያም ይሰማራሉ፣ አምላካቸው እግዚአብሔር ይጐበኛቸዋልና፥ ምርኮአቸውንም ይመልሳልና በአስቀሎና ቤቶች ውስጥ ማታ ይተኛሉ።'),
  ('8fe88a21-7cea-5e1a-a6c5-407839084d3e', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 7, 8, 'በሕዝቤም ላይ ያላገጡባትን፥ በድንበራቸውም ላይ እየታበዩ የተናገሩባትን የሞዓብን ማላገጥና የአሞንን ልጆች ስድብ ሰምቻለሁ።'),
  ('9a2026c1-2059-5409-adde-ac956f92af6a', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 8, 9, 'ስለዚህ የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እኔ ሕያው ነኝና በእርግጥ ሞዓብ እንደ ሰዶም፥ የአሞንም ልጆች እንደ ገሞራ፥ የሳማ ስፍራና የጨው ጕድጓድ ለዘላለምም ምድረ በዳ ሆነው ይኖራሉ፣ የሕዝቤም ቅሬታ ይበዘብዛቸዋል፥ ከወገኔም የተረፉት ይወርሱአቸዋል።'),
  ('6e9c52f0-9aa0-553a-a04e-a1fdef4b56a0', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 9, 10, 'በሠራዊት ጌታ በእግዚአብሔር ሕዝብ ላይ አላግጠዋልና፥ እየታበዩም ተናግረዋልና ይህ ስለ ትዕቢታቸው ያገኛቸዋል።'),
  ('e37806e9-a6f6-55a0-aa3e-21bfe6863daf', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 10, 11, 'እግዚአብሔር በእነርሱ ላይ የተፈራ ይሆናል፥ የምድርንም አማልክት ሁሉ ያከሳቸዋል፣ በአሕዛብም ደሴቶች ሁሉ ላይ የሚኖሩ ሰዎች ሁሉ በስፍራቸው ሆነው ለእርሱ ይሰግዳሉ።'),
  ('c1e27312-da68-582d-a985-57239f24899c', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 11, 12, 'እናንተም ኢትዮጵያውያን ደግሞ፥ በሰይፌ ትገደላላችሁ።'),
  ('e1948a0a-83ef-5316-a883-33013d7006af', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 12, 13, 'እርሱም በሰሜን ላይ እጁን ይዘረጋል፥ አሦርንም ያጠፋል፣ ነነዌንም ባድማ፥ እንደ በረሃም ደረቅ ያደርጋታል።'),
  ('4caf13ff-b6e7-5cc6-a303-08fb3b3ba85d', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 13, 14, 'መንጎችም የምድርም አራዊት ሁሉ በውስጥዋ ይመሰጋሉ፣ ይብራና ጃርት በዓምዶችዋ መካከል ያድራሉ፣ ድምፃቸው በመስኮቶችዋ ይጮኻል፣ የዝግባም እንጨት ሥራ ይገለጣልና በመድረኮችዋ ላይ ጥፋት ይሆናል።'),
  ('e41f8cb1-1f70-582e-a0a4-0de2e2cd48b6', '739838ec-fe7c-5e4a-a3df-934c498a2bb7', '09b9184b-96d8-5306-a95f-506c6dfa3125', 14, 15, 'ተዘልላ የተቀመጠች፥ በልብዋም፦ እኔ ነኝ፥ ከእኔም በቀር ሌላ የለም ያለች ደስተኛይቱ ከተማ ይህች ናት፣ አራዊት የሚመሰጉባት ባድማ እንዴት ሆነች! በእርስዋ በኩል የሚያልፈው ሁሉ እጁን እያወዛወዘ ያፍዋጫል።'),
  ('3c82e14c-c197-58dd-a911-8a0bf790ce87', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 1, 1, 'ለዓመፀኛይቱና ለረከሰች ለአስጨናቂይቱም ከተማ ወዮላት!'),
  ('eedf2727-91eb-5ac7-a66f-925143febacd', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 2, 2, 'ድምፅን አልሰማችም፥ ተግሣጽንም አልተቀበለችም፣ በእግዚአብሔርም አልታመነችም፥ ወደ አምላክዋም አልቀረበችም።'),
  ('1456e147-9f10-514c-ae7a-a668d802b2f0', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 3, 3, 'በውስጥዋ ያሉ አለቆችዋ እንደሚያገሡ አንበሶች ናቸው፣ ፈራጆችዋም እስከ ነገ ድረስ ምንም እንደማያስቀሩ እንደ ማታ ተኵላዎች ናቸው።'),
  ('27f8ed86-19a8-5259-a6d9-95da07611ea3', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 4, 4, 'ነቢያቶችዋ ቅሌታሞችና ተንኰለኞች ሰዎች ናቸው፣ ካህናቶችዋም መቅደሱን አርክሰዋል፥ በሕግም ላይ ግፍ ሠርተዋል።'),
  ('275e3e21-8bfd-553d-afb5-6f0a5c906fbb', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 5, 5, 'እግዚአብሔር በውስጥዋ ጻድቅ ነው፣ ክፋትን አያደርግም፣ ፍርዱን በየማለዳው ወደ ብርሃን ያወጣል፥ ሳያወጣውም አይቀርም፣ ዓመፀኛው ግን እፍረትን አያውቅም።'),
  ('870666d8-fc86-5534-a006-c9d918ee327c', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 6, 6, 'አሕዛብን አጥፍቻለሁ፣ ግንቦቻቸው ሁሉ ፈርሰዋል፣ መንገዳቸውን ማንም እንዳያልፍባት ምድረ በዳ አድርጌአለሁ፥ ከተሞቻቸውም ማንም እንዳይኖርባቸው፥ አንድስ እንኳ እንዳይቀመጥባቸው ፈርሰዋል።'),
  ('df11fc34-e7a6-56b4-a860-2150c80e28e5', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 7, 7, 'እኔም- ይፈሩኛል፥ ተግሣጽንም ይቀበላሉ፣ ካዘዝኋትም ሁሉ ከዓይንዋ ምንም አይጠፋም ብዬ ነበር፣ እነርሱ ግን በማለዳ ተነሥተው ድርጊታቸውን ሁሉ አረከሱ።'),
  ('ed5586cc-da66-551c-aa13-54dd8f8b8bcc', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 8, 8, 'መዓቴንና የቍጣዬን ትኵሳት ሁሉ አፈስስባቸው ዘንድ ፍርዴ አሕዛብን ለመሰብሰብ፥ መንግሥታትንም ለማከማቸት ነውና፥ ምድርም ሁሉ በቅንዓቴ እሳት ትበላለችና ስለዚህ ለመበዝበዝ እስከምነሣበት ቀን ድረስ ጠብቁኝ፥ ይላል እግዚአብሔር።'),
  ('c5312eee-2296-5da6-a776-0ef3a8e027d9', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 9, 9, 'በዚያን ጊዜም አሕዛብ ሁሉ አንድ ሆነው እግዚአብሔርን ያገለግሉት ዘንድ ስሙን እንዲጠሩ ንጹሕን ልሳን እመልስላቸዋለሁ።'),
  ('3e3d9afa-13a1-5e76-a82f-28cf6757f65f', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 10, 10, 'ከኢትዮጵያ ወንዞች ማዶ የሚማልዱኝ፥ የተበተኑትን ሴቶች ልጆቼ፥ ቍርባኔን ያመጡልኛል።'),
  ('a710d48c-c2b0-5f9c-aefa-dad55458b444', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 11, 11, 'በዚያን ጊዜ እየታበዩ የሚፎክሩትን ከመካከልሽ አወጣለሁና፥ አንቺም በቅዱስ ተራራዬ ዳግመኛ አትኰሪምና በዚያ ቀን በእኔ ላይ ተላልፈሽ በሠራሽው ሥራ ሁሉ አታፍሪም።'),
  ('4de6526a-f239-5659-ac07-697e91d3e205', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 12, 12, 'በመካከልሽም የዋህና ትሑት ሕዝብን አስቀራለሁ፣ በእግዚአብሔርም ስም ይታመናሉ።'),
  ('c7d1d87d-3ccf-577a-a9c8-1215699d26f8', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 13, 13, 'የእስራኤል ቅሬታ ኃጢአትን አይሠሩም፥ ሐሰትንም አይናገሩም፥ በአፋቸውም ውስጥ ተንኰለኛ ምላስ አይገኝም፣ እነርሱም ይሰማራሉ፥ ይመሰጉማል፥ የሚያስፈራቸውም የለም።'),
  ('c6e15820-bc5b-56cd-a9f0-94da2099c27c', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 14, 14, 'የጽዮን ልጅ ሆይ፥ ዘምሪ፣ እስራኤል ሆይ፥ እልል በል፣ የኢየሩሳሌም ልጅ ሆይ፥ በፍጹም ልብሽ ሐሴት አድርጊ ደስም ይበልሽ።'),
  ('2e800d33-94cc-55fa-af1e-b52c08705c78', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 15, 15, 'እግዚአብሔር ፍርድሽን አስወግዶአል፥ ጠላትሽንም ጥሎአል፣ የእስራኤል ንጉሥ እግዚአብሔር በመካከልሽ አለ፥ ከእንግዲህም ወዲህ ክፉ ነገርን አታዪም።'),
  ('0f90c7d8-de3c-55e1-aec8-e46f971cdceb', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 16, 16, 'በዚያን ቀን ለኢየሩሳሌም፦ ጽዮን ሆይ፥ አትፍሪ፥ እጆችሽም አይዛሉ።'),
  ('ffebf7b4-125b-5288-ab2e-217062ba3559', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 17, 17, 'አምላክሽ እግዚአብሔር በመካከልሽ ታዳጊ ኃያል ነው፣ በደስታ በአንቺ ደስ ይለዋል፥ በፍቅሩም ያርፋል፥ በእልልታም በአንቺ ደስ ይለዋል ይባላል።'),
  ('fcc125eb-d81e-58d9-afde-ac3f5c5fb1d5', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 18, 18, 'ከጉባኤው ርቀው የሚያዝኑትን፥ ከአንቺም የሆኑትን እሰበስባለሁ፣ ስድብ እንደ ሸክም ከብዶባቸው ነበር።'),
  ('f7a4ae40-6095-5c55-a2d6-b643cafafa22', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 19, 19, 'በዚያ ዘመን እነሆ፥ ባስጨነቁሽ ሁሉ ላይ አደርግባቸዋለሁ፣ አንካሳይቱንም አድናለሁ፥ የተጣለችውንም እሰበስባታለሁ፣ ባፈሩባትም ምድር ሁሉ ላይ ለምስጋናና ለከበረ ስም አደርጋቸዋለሁ።'),
  ('2715b039-597a-545b-a24e-1778bc89c38b', 'bd8bf1db-f86b-527d-a551-2e1bb1615c64', 'b5efca3a-8a88-5c4f-a1ac-5e36c6e0fb34', 20, 20, 'በዚያ ዘመን አስገባችኋለሁ፥ በዚያም ዘመን እሰበስባችኋለሁ፣ ምርኮአችሁንም በዓይናችሁ ፊት በመለስሁ ጊዜ በምድር አሕዛብ ሁሉ መካከል ለከበረ ስምና ለምስጋና አደርጋችኋለሁ፥ ይላል እግዚአብሔር።'),
  ('4201ceb7-3ecd-5e86-a508-ac123e1abfa0', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 1, 1, 'በንጉሡ በዳርዮስ በሁለተኛው ዓመት በስድስተኛው ወር ከወሩም በመጀመሪያው ቀን የእግዚአብሔር ቃል በነቢዩ በሐጌ እጅ ወደ ይሁዳ አለቃ ወደ ሰላትያል ልጅ ወደ ዘሩባቤል፥ ወደ ታላቁም ካህን ወደ ኢዮሴዴቅ ልጅ ወደ ኢያሱ እንዲህ ሲል መጣ፦'),
  ('ec2e27bf-cad0-52b9-a8ca-e13f7c2d3ac0', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 2, 2, 'የሠራዊት ጌታ እግዚአብሔር፦ ይህ ሕዝብ፦ ዘመኑ አልደረሰም፥ የእግዚአብሔር ቤት የሚሠራበት ዘመን አልደረሰም ይላል ብሎ ተናገረ።'),
  ('163e3b3e-528a-5b8e-ac32-a0067c8b0864', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 3, 3, 'የእግዚአብሔርም ቃል በነቢዩ በሐጌ እጅ እንዲህ ሲል መጣ፦'),
  ('00c35e19-d856-5ccc-a92b-8fd3d9bf339f', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 4, 4, 'በውኑ ይህ ቤት ፈርሶ ሳለ እናንተ ራሳችሁ በተሸለሙ ቤቶቻችሁ ለመኖር ጊዜው ነውን?'),
  ('f6baadae-74e9-59d7-a60e-65f84bc31f4c', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 5, 5, 'አሁንም የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ልባችሁን በመንገዳችሁ ላይ አድርጉ።'),
  ('5882e9ec-2315-591a-af7e-ac9c323809ca', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 6, 6, 'ብዙ ዘራችሁ፥ ጥቂትም አገባችሁ፣ በላችሁ፥ ነገር ግን አልጠገባችሁም፣ ጠጣችሁ፥ ነገር ግን አልረካችሁም፣ ለበሳችሁ፥ ነገር ግን አልሞቃችሁም፣ ደመወዙን የተቀበለ ሰው በቀዳዳ ከረጢት ያደርገው ዘንድ ደመወዙን ተቀበለ።'),
  ('7840042c-a3dd-5f6e-abd5-362df8fe1fda', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 7, 7, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ልባችሁን በመንገዳችሁ ላይ አድርጉ።'),
  ('b25df078-fb2f-57f5-a225-fd09b15a336a', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 8, 8, 'ወደ ተራራው ውጡ፥ እንጨትንም አምጡ፥ ቤቱንም ሥሩ፣ እኔም በእርሱ ደስ ይለኛል፥ እኔም እመሰገናለሁ፥ ይላል እግዚአብሔር።'),
  ('b7b6da9d-e558-56ad-a334-16a26039d455', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 9, 9, 'እናንተ ብዙ ነገርን ተስፋ አደረጋችሁ፥ እነሆም፥ ጥቂት ሆነ፣ ወደ ቤትም ባገባችሁት ጊዜ እፍ አልሁበት። ይህ ስለ ምንድር ነው? ይላል የሠራዊት ጌታ እግዚአብሔር። እናንተ ሁሉ ወደ እየቤታችሁ እየሮጣችሁ የእኔ ቤት ፈርሶ ስለ ተቀመጠ ነው።'),
  ('a0a54053-fa44-573f-a127-e668aa87abc2', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 10, 10, 'ስለዚህ ሰማያት በላያችሁ ጠልን ከልክለዋል፥ ምድሪቱም ፍሬዋን ከልክላለች።'),
  ('85f8d5e5-59a5-5b20-a342-2d227a30de3d', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 11, 11, 'እኔም በምድርና በተራሮች፥ በእህልና በወይንም፥ በዘይትና ምድርም በምታበቅለው ላይ፥ በሰዎችና በእንስሶችም ላይ፥ እጅም በሚደክምበት ሁሉ ላይ ድርቅን ጠርቻለሁ።'),
  ('81822fdf-b882-5f71-af57-4ac14c08ce61', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 12, 12, 'የሰላትያልም ልጅ ዘሩባቤል፥ ታላቁም ካህን የኢዮሴዴቅ ልጅ ኢያሱ፥ የቀሩትም ሕዝብ ሁሉ የአምላካቸውን የእግዚአብሔርን ድምፅ የነቢዩንም የሐጌን ቃል፥ አምላካቸው እግዚአብሔር እንደ ላከው ሁሉ ሰሙ፣ ሕዝቡም በእግዚአብሔር ፊት ፈሩ።'),
  ('f4765c22-5e7c-513a-a33a-5e48c5824588', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 13, 13, 'የእግዚአብሔርም መልእክተኛ ሐጌ በእግዚአብሔር መልእክት ሕዝቡን፦ እኔ ከእናንተ ጋር ነኝ፥ ይላል እግዚአብሔር ብሎ ተናገረ።'),
  ('1ba7e3f0-f77f-53ef-a1a1-5df82470c35b', '2a50335b-13c7-5911-a80d-4a4250633f98', 'd9556001-11be-5e80-ab5d-f025a35430e0', 14, 14, 'እግዚአብሔርም የይሁዳን አለቃ የሰላትያልን ልጅ የዘሩባቤልን መንፈስ፥ የታላቁንም ካህን የኢዮሴዴቅን ልጅ የኢያሱን መንፈስ፥ የቀሩትንም ሕዝብ ሁሉ መንፈስ አስነሣ፣ በንጉሡም በዳርዮስ በሁለተኛው ዓመት በስድስተኛው ወር ከወሩም በሀያ አራተኛው ቀን መጡ፥ የአምላካቸውንም የሠራዊትን ጌታ የእግዚአብሔርን ቤት ሠሩ።'),
  ('d0e1002d-ce54-5fca-a889-b58a43596e29', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 1, 1, 'በሰባተኛው ወር ከወሩም በሀያ አንደኛው ቀን የእግዚአብሔር ቃል በነቢዩ በሐጌ እጅ እንዲህ ሲል መጣ፦'),
  ('9a382360-9463-58ad-a750-cd5204f52020', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 2, 2, 'ለይሁዳ አለቃ ለሰላትያል ልጅ ለዘሩባቤል፥ ለታላቁም ካህን ለኢዮሴዴቅ ልጅ ለኢያሱ፥ ለቀሩትም ሕዝብ እንዲህ ስትል ተናገር፦'),
  ('f8172c6d-bc28-58dc-aa92-76a246fdffcc', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 3, 3, 'በቀድሞ ክብሩ ሳለ ይህን ቤት ያየ በእናንተ መካከል የቀረ ማን ነው? ዛሬስ እንዴት ሆኖ አያችሁት? በዓይናችሁ እንደ ምናምን አይደለምን?'),
  ('9804169e-e120-5a22-a66e-907084767d2e', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 4, 4, 'አሁን ግን፥ ዘሩባቤል ሆይ፥ በርታ፥ ይላል እግዚአብሔር፣ ታላቁም ካህን የኢዮሴዴቅ ልጅ ኢያሱ ሆይ፥ በርታ፥ እናንተም የአገሩ ሕዝብ ሆይ፥ በርቱና ሥሩ፥ ይላል እግዚአብሔር፣ እኔ ከእናንተ ጋር ነኝና፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('98b4ac85-042d-54c4-ad5b-ab876dfc6558', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 5, 5, 'መንፈሴም በመካከላችሁ ይኖራልና አትፍሩ።'),
  ('757d2f76-02ee-5e0e-abc5-22789348bbea', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 6, 6, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላልና፦ ገና አንድ ጊዜ በቅርብ ዘመን እኔ ሰማያትንና ምድርን ባሕርንና የብስንም አናውጣለሁ፣'),
  ('3b896bd7-6893-5d52-ac61-d3e936553c96', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 7, 7, 'አሕዛብን ሁሉ አናውጣለሁ፥ በአሕዛብ ሁሉ የተመረጠውም ዕቃ ይመጣል፣ ይህንም ቤት በክብር እሞላዋለሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('960f2b7c-5414-5227-ac2c-5b52866236b5', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 8, 8, 'ብሩ የእኔ ነው፥ ወርቁም የእኔ ነው፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('01454aa0-549e-50bb-a64f-8dcdf285e7f2', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 9, 9, 'ከፊተኛው ይልቅ የዚህ የሁለተኛው ቤት ክብር ይበልጣል፥ ይላል የሠራዊት ጌታ እግዚአብሔር፣ በዚህም ስፍራ ሰላምን እሰጣለሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('b6a84476-6779-5af0-acd9-2675d5eb693e', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 10, 10, 'በዳርዮስም በሁለተኛው ዓመት በዘጠነኛው ወር በሀያ አራተኛው ቀን የእግዚአብሔር ቃል በነቢዩ በሐጌ እጅ እንዲህ ሲል መጣ፦'),
  ('9ffea1e7-f415-572d-a4a6-9df79d50a6ab', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 11, 11, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ካህናቱን ስለ ሕጉ ጠይቅ፣'),
  ('ba94ef92-4e2e-5329-a219-895ccbb4ec0c', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 12, 12, 'አንድ ሰው የተቀደሰ ሥጋ በልብሱ ዘርፍ ቢይዝ፥ በዘርፉም እንጀራ ወይም ወጥ፥ ወይም የወይን ጠጅ፥ ወይም ዘይት፥ ወይም ማናቸውም መብል ቢነካ ያ የተነካው በውኑ ይቀደሳልን? ብለህ ካህናቱን ጠይቃቸው፣ ካህናቱም፦ አይሆንም ብለው መለሱ።'),
  ('3e8c5378-c1be-5524-adaf-576e9ea8d795', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 13, 13, 'ሐጌም፦ በሬሳ የረከሰ ሰው ከእነዚህ አንዱን ቢነካ ያ የተነካው በውኑ ይረክሳልን? አለ። ካህናቱም፦ አዎን ይረክሳል ብለው መለሱ።'),
  ('70014b97-68b7-5300-a74a-68d4f3bea276', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 14, 14, 'ሐጌም መልሶ እንዲህ አለ፦ ይህ ሕዝብና ይህ ወገን በፊቴ እንዲሁ ነው፥ ይላል እግዚአብሔር፣ የእጃቸውም ሥራ ሁሉ እንዲሁ ነው፣ በዚያም ያቀረቡት ነገር ርኩስ ነው።'),
  ('aaf955cb-879c-568c-a2e2-2df578ac4459', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 15, 15, 'አሁንም ድንጋይ በድንጋይ ላይ በእግዚአብሔር መቅደስ ሳይነባበር፥ ከዛሬ ጀምራችሁ ወዳለፈው ዘመን ልብ አድርጉ።'),
  ('b9160ede-b246-5d15-acb3-180a3d682f3c', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 16, 16, 'በዚያን ዘመን ሁሉ ሰው ሀያ መስፈሪያ ወዳለበት ምርት በመጣ ጊዜ፥ የተገኘው አሥር መስፈሪያ ብቻ ነው፣ አምሳ ማድጋም ይቀዳ ዘንድ ወደ መጥመቂያው በመጣ ጊዜ፥ የተገኘው ሀያ ብቻ ነው።'),
  ('48ae8928-d03e-5f6a-a2d7-2d30d3e5cb22', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 17, 17, 'በእጃችሁ ሥራ ሁሉ ላይ በዋግና በአረማሞ በበረዶም መታኋችሁ፣ እናንተ ግን ወደ እኔ አልተመለሳችሁም፥ ይላል እግዚአብሔር።'),
  ('ebc37994-df19-59cc-a0bb-656b25de3a6d', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 18, 18, 'ከዛሬው ከዘጠነኛው ወር ከሀያ አራተኛው ቀን ጀምራችሁ የሚመጣውን ዘመን ልብ አድርጉ፣ የእግዚአብሔር መቅደስ መሠረት ከተተከለበት ቀን ጀምሮ ልብ አድርጉ።'),
  ('87e42b07-6417-5b70-a6f2-fc2f39039860', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 19, 19, 'ዘር በጎተራ ገና ይኖራልን? ወይንና በለስ ሮማንና ወይራ አላፈሩም፣ ከዚህች ቀን ጀምሬ እባርካችኋለሁ።'),
  ('1fafe544-e1d6-5a47-a2ad-3c45b433d910', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 20, 20, 'በወሩ በሀያ አራተኛው ቀን የእግዚአብሔር ቃል ሁለተኛ ወደ ሐጌ እንዲህ ሲል መጣ፦'),
  ('8743921d-05a3-56d3-a927-453fcd1a8c86', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 21, 21, 'ለይሁዳ አለቃ ለዘሩባቤል ተናገር እንዲህም በል፦ ሰማያትንና ምድርን አናውጣለሁ፣'),
  ('db24910e-0d12-56b9-abf1-394717eaa0bd', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 22, 22, 'የመንግሥታትንም ዙፋን እገለብጣለሁ፥ የአሕዛብንም መንግሥታት ኃይል አጠፋለሁ፣ ሰረገሎችንና የሚቀመጡባቸውንም እገለብጣለሁ፣ ፈረሶችና ፈረሰኞቻቸውም እያንዳንዳቸው በወንድማቸው ሰይፍ ይወድቃሉ።'),
  ('21c0818d-4b8a-5421-a56f-677e4b60ca66', '292ef798-596a-5955-aa22-2821848f7263', '313de2b5-5be0-50a7-a648-3bfeb4ce6d5b', 23, 23, 'ባሪያዬ የሰላትያል ልጅ ዘሩባቤል ሆይ፥ በዚያ ቀን እወስድሃለሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር፣ እኔ መርጬሃለሁና፥ ይላል እግዚአብሔር፥ እንደ ቀለበት ማተሚያ አደርግሃለሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('26b55afe-3d1d-5838-af32-5cea36cbb54a', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 1, 1, 'በዳርዮስ በሁለተኛው ዓመት በስምንተኛው ወር የእግዚአብሔር ቃል ወደ አዶ ልጅ ወደ በራክዩ ልጅ ወደ ነቢዩ ወደ ዘካርያስ እንዲህ ሲል መጣ፦'),
  ('cc2a7482-c4f1-5d0f-a26b-f1b49e25d680', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 2, 2, 'እግዚአብሔር በአባቶቻችሁ ላይ እጅግ ተቈጥቶ ነበር።'),
  ('b9ab640f-3fc2-5930-a3c6-c04ce7003e2e', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 3, 3, 'ስለዚህ እንዲህ በላቸው፦ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ወደ እኔ ተመለሱ፥ ይላል የሠራዊት ጌታ እግዚአብሔር፥ እኔም ወደ እናንተ እመለሳለሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('e23abe5f-be39-52f4-a38d-5fb854ea3ba5', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 4, 4, 'የቀደሙት ነቢያት ለአባቶቻችሁ እንዲህ ብለው ሰብከዋል፦ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ከክፉ መንገዳችሁና ከክፉ ሥራችሁ ተመለሱ፣ እነርሱ ግን አልሰሙም፥ እኔንም አላደመጡም፣ እንደ እነርሱ አትሁኑ፥ ይላል እግዚአብሔር።'),
  ('b81d8b0b-7657-503f-af9e-8d2a41e4c1c6', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 5, 5, 'አባቶቻችሁ ወዴት ናቸው? ነቢያትስ ለዘላለም በሕይወት ይኖራሉን?'),
  ('fb235278-9ed5-52a4-a334-f7c4c3f6f895', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 6, 6, 'ለባሪያዎቼስ ለነቢያት ያዘዝኋቸው ቃሎቼና ሥርዓቴ በአባቶቻችሁ ላይ አልደረሱምን? እነርሱም ተመልሰው፦ የሠራዊት ጌታ እግዚአብሔር በመንገዳችንና በሥራችን መጠን ያደርግብን ዘንድ እንዳሰበ እንዲሁ አድርጎብናል አሉ።'),
  ('d1a65302-c2b9-507c-add2-caa37596de6d', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 7, 7, 'በዳርዮስ በሁለተኛው ዓመት ሳባጥ በሚባል በአሥራ አንደኛው ወር በሀያ አራተኛው ቀን የእግዚአብሔር ቃል ወደ አዶ ልጅ ወደ በራክዩ ልጅ ወደ ነቢዩ ወደ ዘካርያስ እንዲህ ሲል መጣ፦'),
  ('71e6c7a6-ca06-52fd-ad8d-1897a2fb3620', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 8, 8, 'እነሆም፥ አንድ ሰው በመጋላ ፈረስ ተቀምጦ በሌሊት አየሁ፥ እርሱም በሸለቆው ውስጥ ባሉ በባርሰነት ዛፎች መካከል ቆሞ ነበር፣ በስተ ኋላውም መጋላና ሐመር አንባላይም ፈረሶች ነበሩ።'),
  ('b989ab10-cb0a-5f67-a7cb-093b6fdaa143', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 9, 9, 'እኔም፦ ጌታዬ ሆይ፥ እነዚህ ምንድር ናቸው? አልሁ። ከእኔም ጋር ይነጋገር የነበረው መልአክ፦ እነዚህ ምን እንደ ሆኑ አሳይሃለሁ አለኝ።'),
  ('b5cbc87a-3b66-5c39-a3c8-d72f8e2033b2', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 10, 10, 'በባርሰነት ዛፎች መካከልም ቆሞ የነበረው ሰው፦ እነዚህ በምድር ላይ ይመላለሱ ዘንድ እግዚአብሔር የላካቸው ናቸው ብሎ መለሰ።'),
  ('0aa8c281-48c2-5abb-aa31-5a51411bc36e', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 11, 11, 'በባርሰነት ዛፎች መካከልም ቆሞ የነበረውን የእግዚአብሔርን መልአክ፦ በምድር ላይ ተመላለስን፥ እነሆም፥ ምድር ሁሉ ዝም ብላ ዐርፋ ተቀምጣለች ብለው መለሱለት።'),
  ('dc5ae387-6ef5-568c-a8cd-30e62f3964f9', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 12, 12, 'የእግዚአብሔርም መልአክ መልሶ፦ አቤቱ፥ የሠራዊት ጌታ ሆይ፥ እነዚህ ሰባ ዓመት የተቈጣሃቸውን ኢየሩሳሌምንና የይሁዳን ከተሞች የማትምራቸው እስከ መቼ ነው? አለ።'),
  ('203b327b-c8da-580a-a1da-bf2ef2c732c9', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 13, 13, 'እግዚአብሔርም መልሶ ከእኔ ጋር ይነጋገር ለነበረው መልአክ በመልካምና በሚያጽናና ቃል ተናገረው።'),
  ('8c7c07be-8b69-57a4-a9c2-031432a9cef0', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 14, 14, 'ስለዚህም ከእኔ ጋር ይነጋገር የነበረው መልአክ እንዲህ አለኝ፦ ስበክ እንዲህም በል፦ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እኔ በታላቅ ቅንዓት በኢየሩሳሌምና በጽዮን ቀንቻለሁ።'),
  ('00c63e60-8e79-535e-a77c-d7cf68c5de42', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 15, 15, 'እኔ ጥቂት ብቻ ተቈጥቼ ሳለሁ እነርሱ ክፋትን ስላገዙት፥ ባልተቸገሩት አሕዛብ ላይ እጅግ ተቈጥቻለሁ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('738d9e2b-1d3b-5c2f-a504-7d1cb9e648f2', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 16, 16, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፦ ወደ ኢየሩሳሌም በምሕረት ተመልሻለሁ፣ ቤቴ ይሠራባታል፣ በኢየሩሳሌምም ላይ ገመድ ይዘረጋበታል፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('14685d0d-03c1-5682-ac19-de058df10469', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 17, 17, 'ደግሞም እንዲህ ስትል ስበክ፦ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ከተሞቼ ደግሞ በበጎ ነገር ይረካሉ፣ እግዚአብሔርም ደግሞ ጽዮንን ያጽናናል፥ ኢየሩሳሌምንም ደግሞ ይመርጣል።'),
  ('db1c4822-a036-559b-ad0b-a719e9205296', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 18, 18, 'ዓይኖቼንም አንሥቼ እነሆ፥ አራት ቀንዶች አየሁ።'),
  ('bc52aacf-4794-5eef-ab55-6977c440f322', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 19, 19, 'ከእኔም ጋር ይነጋገር የነበረውን መልአክ፦ እነዚህ ምንድር ናቸው? አልሁት። እርሱም፦ እነዚህ ይሁዳንና እስራኤልን ኢየሩሳሌምንም የበተኑ ቀንዶች ናቸው ብሎ መለሰልኝ።'),
  ('2d111f18-ce71-5c87-a15e-a42d9baa081b', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 20, 20, 'እግዚአብሔርም አራት ጠራቢዎች አሳየኝ።'),
  ('f4277374-1b7e-5878-aa62-3c00ae046538', 'fcf95571-9266-5de2-a6c7-96d43ba5d326', '917eafe2-23e5-59c2-a3cf-619b6ab6dc75', 21, 21, 'እኔም፦ እነዚህ የመጡት ምን ሊሠሩ ነው? አልሁ። እርሱም፦ አንድ ሰው ራሱን እስከማያነሣ ድረስ እነዚህ ቀንዶች ይሁዳን የበተኑ ናቸው፣ እነዚህ ግን ሊያስፈራሩአቸው፥ የይሁዳንም አገር ይበትኑ ዘንድ ቀንዳቸውን ያነሡትን የአሕዛብን ቀንዶች ሊጥሉ መጥተዋል ብሎ ተናገረ።'),
  ('e2dd099d-bb7c-5360-ada0-36afce4a242f', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 1, 1, 'ዓይኖቼንም አነሣሁ፣ እነሆም፥ በእጁ የመለኪያ ገመድ የያዘ አንድ ሰውን አየሁ።'),
  ('11ccc0ef-a6db-50be-ad81-1381fe1c3b61', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 2, 2, 'እኔም፦ አንተ ወዴት ትሄዳለህ? አልሁ። እርሱም፦ የኢየሩሳሌምን ወርድና ርዝመት ስንት መሆኑን ሰፍሬ አይ ዘንድ እሄዳለሁ አለኝ።'),
  ('7a665002-d9f4-5f8f-ab4e-446f93ad39de', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 3, 3, 'እነሆም፥ ከእኔ ጋር ይነጋገር የነበረው መልአክ ወጣ፥ ሌላም መልአክ ሊገናኘው ወጣ፥ እንዲህም አለው፦'),
  ('400a4494-fc31-5b06-acf5-7fda01e1b067', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 4, 4, 'ሩጥ፥ ይህንም ጕልማሳ እንዲህ በለው፦ ኢየሩሳሌም በውስጥዋ ካሉት ሰዎችና እንስሶች ብዛት የተነሣ ቅጥር እንደሌላቸው መንደሮች ሆና ትኖራለች።'),
  ('c2b59511-a523-5fce-a8fc-2a52f9ec8e8e', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 5, 5, 'እኔ በዙሪያዋ የእሳት ቅጥር እሆንላታለሁ፥ በውስጥዋም ክብርን እሆናለሁ፥ ይላል እግዚአብሔር።'),
  ('cadfb956-3cfa-5246-a26f-a51e1ec0b7b8', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 6, 6, 'እናንተ ሆይ፥ ከሰሜን ምድር ሽሹ፥ ይላል እግዚአብሔር፣ እንደ አራቱ የሰማይ ነፋሳት በትኛችኋለሁና፥ ይላል እግዚአብሔር።'),
  ('955c21ed-83fd-590e-a361-31f389bb6734', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 7, 7, 'አንቺ ከባቢሎን ሴት ልጅ ጋር የምትኖሪ ጽዮን ሆይ፥ ኰብልዪ።'),
  ('904391da-86e2-5957-a8b6-69f07ac61881', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 8, 8, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላልና፦ ከክብሩ በኋላ ወደ በዘበዙአችሁ አሕዛብ ልኮኛል፣ የሚነካችሁ የዓይኑን ብሌን የሚነካ ነውና።'),
  ('b3b4c14d-a543-5463-a705-52655eb01889', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 9, 9, 'እነሆ፥ እጄን በላያቸው አወዛውዛለሁ፥ ተገዝተው ለነበሩት ብዝበዛ ይሆናሉ፣ የሠራዊት ጌታ እግዚአብሔርም እንደ ላከኝ ታውቃላችሁ።'),
  ('8a0d77dc-fe9f-5547-a0fc-4296969eb1a0', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 10, 10, 'የጽዮን ልጅ ሆይ፥ እነሆ፥ መጥቼ በመካከልሽ እኖራለሁና ዘምሪ ደስም ይበልሽ፥ ይላል እግዚአብሔር።'),
  ('5fe1e7ea-6553-505f-ae95-f0b9a8892869', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 11, 11, 'በዚያም ቀን ብዙ አሕዛብ ወደ እግዚአብሔር ይጠጋሉ፥ ሕዝብም ይሆኑኛል፣ በመካከልሽም እኖራለሁ፥ የሠራዊት ጌታ እግዚአብሔርም ወደ አንቺ እንደ ላከኝ ታውቂአለሽ።'),
  ('7d0d7873-dd80-50eb-af86-1cb16c9bf70d', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 12, 12, 'እግዚአብሔርም ይሁዳን እድል ፈንታው አድርጎ በተቀደሰችው ምድር ይወርሰዋል፥ ኢየሩሳሌምንም ዳግመኛ ይመርጣል።'),
  ('4b3cc3ac-3daf-5cbe-a5c7-7c4617c0b549', 'd8525d54-60bf-5094-a9c4-7c2538a94b20', '363457a2-23fe-57af-a009-c0ce79933d51', 13, 13, 'እግዚአብሔር ከተቀደሰ ማደሪያው ነቅቶአልና ሥጋ ለባሽ ሁሉ ሆይ፥ በፊቱ ዝም በል።'),
  ('329da286-225e-5d6a-a612-16e16426ad32', '0b18966f-1088-57a3-ad9a-15a8bd409c34', 'ca4518f9-7443-5ab6-a4c3-a9fa60141287', 1, 1, 'እርሱም ታላቁን ካህን ኢያሱን በእግዚአብሔር መልአክ ፊት ቆሞ አሳየኝ፥ ሰይጣንም ይከስሰው ዘንድ በስተ ቀኙ ቆሞ ነበር።'),
  ('2bac8343-d148-5a1e-a629-4c2af642af20', '0b18966f-1088-57a3-ad9a-15a8bd409c34', 'ca4518f9-7443-5ab6-a4c3-a9fa60141287', 2, 2, 'እግዚአብሔርም ሰይጣንን፦ ሰይጣን ሆይ፥ እግዚአብሔር ይገሥጽህ፣ ኢየሩሳሌምን የመረጠ እግዚአብሔር ይገሥጽህ፣ በውኑ ይህ ከእሳት የተነጠቀ ትንታግ አይደለምን? አለው።'),
  ('4a0f76f4-e779-5ed6-a99a-788d6b42b853', '0b18966f-1088-57a3-ad9a-15a8bd409c34', 'ca4518f9-7443-5ab6-a4c3-a9fa60141287', 3, 3, 'ኢያሱም እድፋም ልብስ ለብሶ በመልአኩ ፊት ቆሞ ነበር።'),
  ('35d0633a-58cf-51b3-aa15-c32c333451ed', '0b18966f-1088-57a3-ad9a-15a8bd409c34', 'ca4518f9-7443-5ab6-a4c3-a9fa60141287', 4, 4, 'እርሱም መልሶ በፊቱ የቆሙትን፦ እድፋሙን ልብስ ከእርሱ ላይ አውልቁ አላቸው። እርሱንም፦ እነሆ፥ አበሳህን ከአንተ አርቄአለሁ፥ ጥሩ ልብስም አለብስሃለሁ አለው።'),
  ('f1389b8d-1822-5805-a0fe-c966e656b82a', '0b18966f-1088-57a3-ad9a-15a8bd409c34', 'ca4518f9-7443-5ab6-a4c3-a9fa60141287', 5, 5, 'ደግሞ፦ ንጹሕ ጥምጥም በራስ ላይ አድርጉ አለ። እነርሱም በራሱ ላይ ንጹሕ ጥምጥም አደረጉ፥ ልብስንም አለበሱት፣ የእግዚአብሔርም መልአክ በአጠገቡ ቆሞ ነበር።'),
  ('5b0cf2ca-6926-573f-ae22-e7943f49e9d5', '0b18966f-1088-57a3-ad9a-15a8bd409c34', 'ca4518f9-7443-5ab6-a4c3-a9fa60141287', 6, 6, 'የእግዚአብሔርም መልአክ በኢያሱ እንዲህ ሲል አዳኘበት፦'),
  ('a017ad50-71bb-591b-a5ea-eae6f8bf699e', '0b18966f-1088-57a3-ad9a-15a8bd409c34', 'ca4518f9-7443-5ab6-a4c3-a9fa60141287', 7, 7, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ በመንገዴ ብትሄድ ትእዛዜንም ብትጠብቅ፥ በቤቴ ላይ ትፈርዳለህ፥ አደባባዮቼንም ትጠብቃለህ፥ በዚህም ከቆሙት ከእነዚህ ጋር መግባትን እሰጣለሁ።'),
  ('cee5f981-81f9-5576-a929-d6577ad8c739', '0b18966f-1088-57a3-ad9a-15a8bd409c34', 'ca4518f9-7443-5ab6-a4c3-a9fa60141287', 8, 8, 'ታላቁ ካህን ኢያሱ ሆይ፥ ስማ፣ በፊትህም የሚቀመጡት ባልንጀሮች ለምልክት የሚሆኑ ሰዎች ናቸውና ይስሙ፣ እነሆ፥ እኔ ባሪያዬን ቍጥቋጥ አወጣለሁ።'),
  ('c11f579f-eabd-5110-aaea-3da68cfbfeaa', '0b18966f-1088-57a3-ad9a-15a8bd409c34', 'ca4518f9-7443-5ab6-a4c3-a9fa60141287', 9, 9, 'በኢያሱ ፊት ያኖርሁት ድንጋይ እነሆ አለ፣ በአንዱ ድንጋይ ላይ ሰባት ዓይኖች አሉ፣ እነሆ፥ ቅርጹን እቀርጻለሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር፥ የዚያችንም ምድር በደል በአንድ ቀን አስወግዳለሁ።'),
  ('3e0701e1-bf8f-5f26-a6fb-7e5a06488c9b', '0b18966f-1088-57a3-ad9a-15a8bd409c34', 'ca4518f9-7443-5ab6-a4c3-a9fa60141287', 10, 10, 'በዚያ ቀን፥ ይላል የሠራዊት ጌታ እግዚአብሔር፥ እያንዳንዱ ከወይኑና ከበለሱ በታች ሆኖ ባልንጀራውን ይጠራል።'),
  ('315f8286-da36-5a45-a86f-3e30b4da4c59', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 1, 1, 'ከእኔም ጋር ይነጋገር የነበረው መልአክ ተመልሶ ከእንቅልፋ እንደሚነቃ ሰው አነቃኝ።'),
  ('536f1b3c-3a4f-519c-a4a7-ee40920ef0ea', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 2, 2, 'እርሱም፦ የምታየው ምንድር ነው? አለኝ። እኔም፦እነሆ፥ ሁለንተናው ወርቅ የሆነውን መቅረዝ አየሁ፣ የዘይትም ማሰሮ በራሱ ላይ ነበረ፥ ሰባትም መብራቶች ነበሩበት፣ በራሱም ላይ ለነበሩት መብራቶች ሰባት ቧንቧዎች ነበሩአቸው።'),
  ('dd831231-96fa-5643-ae04-3651fd7a2ff9', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 3, 3, 'ሁለት የወይራ ዛፎች፥ አንዱ በማሰሮው በስተ ቀኝ አንዱም በስተ ግራው ሆነው፥ በአጠገቡ ነበሩ አልሁ።'),
  ('c304a929-ed2c-5268-a254-8ac9f89dd047', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 4, 4, 'ከእኔ ጋር ይነጋገር ለነበረውም መልአክ መልሼ፦ ጌታዬ ሆይ፥ እነዚህ ምንድር ናቸው? አልሁት።'),
  ('d85bb683-8804-59fe-a934-d5ee644316b7', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 5, 5, 'ከእኔ ጋር ይነጋገር የነበረውም መልአክ መልሶ፦ እነዚህ ምን እንደ ሆኑ አታውቅምን? አለኝ። እኔም፦ ጌታዬ ሆይ፥ አላውቅም አልሁ።'),
  ('44cdc639-aeca-5857-a594-bcd75f095d59', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 6, 6, 'መልሶም፦ ለዘሩባቤል የተባለው የእግዚአብሔር ቃል ይህ ነው፦ በመንፈሴ እንጂ በኃይልና በብርታት አይደለም፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('80fb5484-5cf6-5e61-a316-5540a62181a0', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 7, 7, 'ታላቅ ተራራ ሆይ፥ አንተ ምንድር ነህ? በዘሩባቤል ፊት ደልዳላ ሜዳ ትሆናለህ፣ ሰዎችም፦ ሞገስ፥ ሞገስ ይሁንለት ብለው እየጮኹ እርሱ መደምደሚያውን ድንጋይ ያወጣል ብሎ ተናገረኝ።'),
  ('12ed92af-bd19-52c8-a3b2-01fbe256b3e9', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 8, 8, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('41c20d87-50b5-55df-a9b3-d8d0325d17c8', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 9, 9, 'የዘሩባቤል እጆች ይህን ቤት መሠረቱ፥ የእርሱም እጆች ይፈጽሙታል፣ የሠራዊት ጌታ እግዚአብሔርም ወደ እናንተ እንደ ላከኝ ታውቃላችሁ።'),
  ('8705041c-9352-550d-ab04-4aec77c05333', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 10, 10, 'የጥቂቱን ነገር ቀን የናቀ ማን ነው? እነዚህ ሰባቱ ደስ ብሎአቸው በዘሩባቤል እጅ ቱንቢውን ያያሉ፣ እነዚህም በምድር ሁሉ የሚዘዋወሩ የእግዚአብሔር ዓይኖች ናቸው።'),
  ('6a26ef42-b71a-549a-a20d-c0ecdb592191', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 11, 11, 'እኔም መልሼ፦ በመቅረዙ በስተ ቀኝና በስተ ግራ ያሉ እነዚህ ሁለት የወይራ ዛፎች ምንድር ናቸው? አልሁት።'),
  ('9266fc29-d253-5dae-a230-d7d2756e0089', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 12, 12, 'ሁለተኛም መልሼ፦ በሁለቱ የወርቅ ቧንቧዎች አጠገብ ሆነው የወርቁን ዘይት የሚያፈስሱ እነዚህ ሁለት የወይራ ቅርንጫፎች ምንድር ናቸው? አልሁት።'),
  ('e24621b0-9880-584c-a469-c29f32d456e9', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 13, 13, 'እርሱም መልሶ፦ እነዚህ ምን እንደ ሆኑ አታውቅምን? አለኝ። እኔም ፦ ጌታ ሆይ፥ አላውቅም አልሁት።'),
  ('5b22f8d4-6f4b-5977-ac12-c44643ad23f9', 'b0456070-6b3e-5eca-ab32-e0588cce2ac0', 'ac922da5-85d5-5760-a192-e006950f7696', 14, 14, 'እርሱም፦ በምድር ሁሉ ጌታ አጠገብ የቆሙት ሁለቱ የተቀቡት እነዚህ ናቸው አለኝ።'),
  ('f31362ae-7f59-5ea0-a4e0-f06ac9cb1b48', '9c1be51f-8ee1-5aa5-a8e0-5daf8ba4678f', 'ab21b6f9-062d-5177-a656-5829e4a1ac6b', 1, 1, 'ተመልሼም ዓይኖቼን አነሣሁ፥ እነሆም፥ አንድ በራሪ የመጽሐፍ ጥቅልል አየሁ።'),
  ('c4562083-5c24-5307-acd3-3fc733feb34c', '9c1be51f-8ee1-5aa5-a8e0-5daf8ba4678f', 'ab21b6f9-062d-5177-a656-5829e4a1ac6b', 2, 2, 'እርሱም፦ የምታየው ምንድር ነው? አለኝ። እኔም፦ በራሪ የመጽሐፍ ጥቅልል አያለሁ፣ ርዝመቱ ሀያ ክንድ ወርዱም አሥር ክንድ ነው አልሁ።'),
  ('65997553-1b6b-5820-a157-d61052704a4e', '9c1be51f-8ee1-5aa5-a8e0-5daf8ba4678f', 'ab21b6f9-062d-5177-a656-5829e4a1ac6b', 3, 3, 'እንዲህም አለኝ፦ ይህ በምድር ፊት ሁሉ ላይ የሚወጣው እርግማን ነው፣ የሚሰርቅ ሁሉ በእርሱ ላይ በዚህ በኩል እንደ ተጻፈው ሁሉ ይጠፋል፥ በሐሰት የሚምልም ሁሉ በእርሱ ላይ በዚያ በኩል እንደ ተጻፈው ሁሉ ይጠፋል።'),
  ('49f16c89-4297-5bd6-a4f4-dc9bc08991a7', '9c1be51f-8ee1-5aa5-a8e0-5daf8ba4678f', 'ab21b6f9-062d-5177-a656-5829e4a1ac6b', 4, 4, 'እኔ አስወጣዋለሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር፥ ወደ ሚሰርቀውም ቤት፥ በሐሰትም በስሜ ወደሚምለው ቤት ይገባል፣ በቤቱም ውስጥ ይኖራል፥ እርሱንም፥ እንጨቱንና ድንጋዩን፥ ይበላል።'),
  ('b8aff8c8-ff1a-5d6b-a9b0-2ac39fdf83bc', '9c1be51f-8ee1-5aa5-a8e0-5daf8ba4678f', 'ab21b6f9-062d-5177-a656-5829e4a1ac6b', 5, 5, 'ከእኔም ጋር ይነጋገር የነበረው መልአክ ወጥቶ፦ ዓይኖችህን አንሣ፥ ይህችንም የምትወጣው ምን እንደ ሆነች እይ አለኝ።'),
  ('9b9db436-0fd1-5be9-ae31-1c313ed4b988', '9c1be51f-8ee1-5aa5-a8e0-5daf8ba4678f', 'ab21b6f9-062d-5177-a656-5829e4a1ac6b', 6, 6, 'እኔም፦ ምንድር ናት? አልሁ። እርሱም፦ ይህች የምትወጣው የኢፍ መስፈሪያ ናት አለኝ። ደግሞም፦ በምድር ሁሉ ላይ ያለ በደላቸው ይህ ነው አለ።'),
  ('8624e0a3-76a9-58c7-a979-c725d31e80ac', '9c1be51f-8ee1-5aa5-a8e0-5daf8ba4678f', 'ab21b6f9-062d-5177-a656-5829e4a1ac6b', 7, 7, 'እነሆም፥ የእርሳሱን መክሊት አነሡት፣ እነሆም፥ በኢፍ መስፈሪያው ውስጥ አንዲት ሴት ተቀምጣ ነበር።'),
  ('4d8b2188-6d9d-5a3f-a6d6-e352fed0af61', '9c1be51f-8ee1-5aa5-a8e0-5daf8ba4678f', 'ab21b6f9-062d-5177-a656-5829e4a1ac6b', 8, 8, 'እርሱም፦ ይህች ክፋት ናት አለኝ፣ በኢፍ መስፈሪያው ውስጥ ጣላት፥ የእርሳሱንም ጠገራ በመስፈሪያ አፍ ላይ ጣለ።'),
  ('4e1eed5f-b6c9-509d-a5d4-f10b15d9618d', '9c1be51f-8ee1-5aa5-a8e0-5daf8ba4678f', 'ab21b6f9-062d-5177-a656-5829e4a1ac6b', 9, 9, 'ዓይኖቼንም አንሥቼ አየሁ፥ እነሆም፥ ሁለት ሴቶች ወጡ፥ ነፋስም በክንፎቻቸው ነበረ፣ ክንፎቻቸውም እንደ ሽመላ ክንፎች ነበሩ፣ የኢፍ መስፈሪያውንም በምድርና በሰማይ መካከል አነሡት።'),
  ('8e39a07b-8a5b-5af8-a353-51bf8ddef677', '9c1be51f-8ee1-5aa5-a8e0-5daf8ba4678f', 'ab21b6f9-062d-5177-a656-5829e4a1ac6b', 10, 10, 'ከእኔም ጋር ይነጋገር የነበረውን መልአክ፦ እነዚህ የኢፍ መስፈሪያውን ወዴት ይወስዱታል? አልሁት።'),
  ('5e0fd14d-12af-5893-aaf0-8f1b8b2bebf2', '9c1be51f-8ee1-5aa5-a8e0-5daf8ba4678f', 'ab21b6f9-062d-5177-a656-5829e4a1ac6b', 11, 11, 'እርሱም፦ በሰናዖር ምድር ቤት ይሠሩለት ዘንድ ይወስዱታል፣ በተዘጋጀም ጊዜ በዚያ በስፍራው ይኖራል አለኝ።'),
  ('8df910c0-1822-55ba-a823-a440e81a0057', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 1, 1, 'ተመልሼም ዓይኖቼን አነሣሁ፥ እነሆም፥ አራት ሰረገሎች ከሁለት ተራራ መካከል ሲወጡ አየሁ፣ ተራሮቹም የናስ ተራሮች ነበሩ።'),
  ('c00c5d77-fa96-5c51-af76-9e428505cc1f', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 2, 2, 'በፊተኛው ሰረገላ መጋላ ፈረሶች፥ በሁለተኛውም ሰረገላ ዱሪ ፈረሶች ነበሩ፥'),
  ('ac6315d4-2682-5f7f-acf0-38c76de337f5', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 3, 3, 'በሦስተኛውም ሰረገላ አምባላይ ፈረሶች፥ በአራተኛውም ሰረገላ ቅጥልጣል ፈረሶች ነበሩ።'),
  ('1c7c58ce-1be4-51dc-a0f9-f7aa41ec9495', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 4, 4, 'ከእኔ ጋር ይነጋገር ለነበረውም መልአክ መልሼ፦ ጌታዬ ሆይ፥ እነዚህ ምንድር ናቸው? አልሁት።'),
  ('a9c772c7-bde2-5f86-a61f-71a152d9d2bc', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 5, 5, 'መልአኩም መልሶ፦ እነዚህ በምድር ሁሉ ጌታ ፊት ከቆሙበት ስፍራ የሚወጡ አራቱ የሰማይ ነፋስት ናቸው።'),
  ('d4ec6bdd-deb4-530e-acee-8ed0057d5cc7', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 6, 6, 'ዱሪ ፈረሶች ያሉበት ወደ ሰሜን ይወጣል፣ አምባላዮቹም ከእነርሱ በኋላ ይወጣሉ፥ ቅጥልጣሎቹም ወደ ደቡብ ይወጣሉ አለኝ።'),
  ('d185c357-2df6-52db-abb2-c6a22e1b14c6', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 7, 7, 'መጋላዎቹም ደግሞ ወጡ በምድርም ይመላለሱ ዘንድ ለመሄድ ይፈልጉ ነበር፣ እርሱም፦ ሂዱ፥ በምድር ላይ ተመላለሱ አለ። እነርሱም በምድር ላይ ተመላለሱ።'),
  ('9b76b028-41ff-5d30-a728-b2e95769dacd', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 8, 8, 'ጮኾም፦ እነሆ፥ ወደ ሰሜን ምድር የሚወጡት እነርሱ መንፈሴን በሰሜን ምድር ላይ አሳርፈዋል ብሎ ተናገረኝ።'),
  ('0d8c54ff-b9e4-5e43-a131-65b947042ca9', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 9, 9, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('9959281f-0f75-503d-a470-5e9c3e342ea6', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 10, 10, 'ከባቢሎን ከመጡት ምርኮኞች ከሔልዳይና ከጦብያ ከዮዳኤም ውሰድ፣ በዚያም ቀን መጥተህ ወደ ሶፎንያስ ልጅ ወደ ኢዮስያስ ቤት ግባ።'),
  ('4d6bb09e-1df8-5e2d-a203-b4adc948e791', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 11, 11, 'ብርንና ወርቅን ከእነርሱ ውሰድ፥ አክሊሎችንም ሥራ፣ በታላቁም ካህን በኢዮሴዴቅ ልጅ በኢያሱ ራስ ላይ ድፋቸው፥ እንዲህም በለው፦'),
  ('452afbde-2c9b-50e4-abf4-518e4081c92c', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 12, 12, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ፥ ስሙ ቍጥቋጥ የሚባል ሰው በስፍራው ይበቅላል፥ የእግዚአብሔርንም መቅደስ ይሠራል።'),
  ('d3160ce8-4d06-576b-a629-a5b9914afe50', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 13, 13, 'እርሱ የእግዚአብሔርን መቅደስ ይሠራል፥ ክብርንም ይሸከማል፥ በዙፋኑም ላይ ተቀምጦ ይነግሣል፣ በዙፋኑም ላይ ካህን ይሆናል፥ የሰላምም ምክር በሁለቱ መካከል ይሆናል።'),
  ('2f61fe9f-79f1-51c3-a3aa-9167c5838a8b', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 14, 14, 'አክሊሎችም ለሔሌምና ለጦብያ ለዮዳኤም ለሶፎንያስም ልጅ ለሔን በእግዚአብሔር መቅደስ ውስጥ ለመታሰቢያ ይሆናሉ።'),
  ('4dec9983-154b-54da-a801-b59fa24bb583', '982a1f38-2c79-5631-a6e3-2ed2873cc831', '38bee0c0-1745-5737-a732-52b6366e4ae2', 15, 15, 'በሩቅም ያሉት መጥተው የእግዚአብሔርን መቅደስ ይሠራሉ፣ የሠራዊት ጌታ እግዚአብሔርም ወደ እናንተ እንደ ላከኝ ታውቃላችሁ። የአምላካችሁንም የእግዚአብሔርን ቃል አጥብቃችሁ ብትሰሙ ይህ ይሆናል።'),
  ('33b1578a-4497-56e1-a2a0-9e426409dddc', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 1, 1, 'በንጉሡም በዳርዮስ በአራተኛው ዓመት ካሴሉ በሚባል በዘጠነኛው ወር በአራተኛው ቀን የእግዚአብሔር ቃል ወደ ዘካርያስ መጣ።'),
  ('13943e24-699a-529b-a6ad-fd0d3cc5c97f', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 2, 2, 'የቤቴልም ሰዎች ሳራሳርንና ሬጌሜሌክን ሰዎቻቸውንም በእግዚአብሔር ፊት ይለምኑ ዘንድ፥'),
  ('24b2c691-e026-52b2-a79a-a6d87ce16c07', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 3, 3, 'ለሠራዊት ጌታ ለእግዚአብሔር ቤት ካህናት ለነቢያትም፦ ባለፉት ዓመታት እንዳደረግሁት በአምስተኛው ወር መለየትና ማልቀስ ይገባኛልን? ብለው ይናገሩ ዘንድ ልኮአቸው ነበር።'),
  ('eda90342-8f3a-59f9-ae97-5387e8c59a70', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 4, 4, 'የሠራዊትም ጌታ የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('b64ca9ba-3b24-5fbe-a9f7-c27db0554ce1', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 5, 5, 'ለምድሩ ሕዝብ ሁሉ ለካህናትም እንዲህ ብለህ ተናገራቸው፦ በዚህ በሰባው ዓመት በአምስተኛውና በሰባተኛው ወር በጾማችሁና ባለቀሳችሁ ጊዜ፥ በውኑ ለእኔ ጾም ጾማችሁልኝ?'),
  ('0d6f13ec-bb0a-53c8-abd6-1b34d92ef73c', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 6, 6, 'በምትበሉበትና በምትጠጡበትስ ጊዜ፥ ለራሳችሁ የምትበሉና የምትጠጡ አይደላችሁምን?'),
  ('ab526e7d-3c15-5c4c-a8e0-4e9fbe79bdcb', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 7, 7, 'ኢየሩሳሌምና በዙሪያዋ ያሉ ከተሞች ገና ሰዎች ባሉባቸው ጊዜ፥ በምቾትም ተቀምጠው ሳሉ፥ ደቡቡና ቈላውም ሰዎች ባሉባቸው ጊዜ፥ እግዚአብሔር በቀደሙት ነቢያት እጅ የተናገረውን ቃል መስማት አይገባችሁምን?'),
  ('9299ab63-c2dd-50ec-aa2b-400ce06faa6e', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 8, 8, 'የእግዚአብሔርም ቃል ወደ ዘካርያስ እንዲህ ሲል መጣ፦'),
  ('7bb56c0c-dacb-529a-a821-1bb9d7ca3474', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 9, 9, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ብሎ ተናግሮአል፦ እውነተኛውን ፍርድ ፍረዱ፣ ቸርነትንና ምሕረትን ሁላችሁ ለወንድሞቻችሁ አድርጉ፣ መበለቲቱንና ደሀ አደጉን፥'),
  ('bab9b5c8-d98d-5518-a6d1-72da8a75a4bb', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 10, 10, 'መጻተኛውንና ችግረኛውን አትበድሉ፣ ከእናንተም ማንም በወንድሙ ላይ ክፉውን ነገር በልቡ አያስብ።'),
  ('d4cef763-28a4-5dda-abfd-7a09a818b408', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 11, 11, 'እነርሱ ግን ደንደሳቸውን አዞሩ እንጂ መስማትን እምቢ አሉ፣ እንዳይሰሙም ጆሮአቸውን አደነቈሩ።'),
  ('6e2075d7-a34c-5e0d-abaf-4dde70fb27cb', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 12, 12, 'የሠራዊትም ጌታ እግዚአብሔር በቀደሙት ነቢያት እጅ በመንፈሱ የላከውን ሕጉንና ቃሉን እንዳይሰሙ ልባቸውን እንደ አልማዝ አጠነከሩ፣ ስለዚህ ከሠራዊት ጌታ ከእግዚአብሔር ዘንድ ታላቅ ቍጣ መጣ።'),
  ('6182ab8c-5712-5be7-aedc-ae1aad540f9c', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 13, 13, 'እኔ በጠራሁ ጊዜ እነርሱ እንዳልሰሙኝ፥ እንዲሁ እነርሱ በሚጠሩበት ጊዜ እኔ አልሰማም፥ ይላል የሠራዊት ጌታ እግዚአብሔር፣'),
  ('da6e68a0-31e3-5931-a735-722081ca8769', '3096e73c-3373-5009-ac29-11a1be7dd3f9', '6a3e52d3-6c07-51ef-a4d1-432c55cddaeb', 14, 14, 'ወደ ማያውቁአቸውም አሕዛብ ሁሉ በዐውሎ ነፋስ በተንኋቸው። እንዲሁ ከእነርሱ በኋላ ምድሪቱ ባድማ ሆናለች፥ የሚተላለፍባትና የሚመላለስባትም አልነበረም፣ ያማረችውንም ምድር ባድማ አደረጉአት።'),
  ('8cea8355-194e-58e9-a80f-cda416c92453', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 1, 1, 'የሠራዊትም ጌታ የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('d2a84cc0-8c2f-5c64-a916-410a22bde1ae', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 2, 2, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ስለ ጽዮን ታላቅ ቅንዓት ቀንቻለሁ፥ በታላቅም ቍጣ ስለ እርስዋ ቀንቻለሁ።'),
  ('433b2fe3-9a8f-5185-ae0e-2587e8dad841', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 3, 3, 'እግዚአብሔር እንዲህ ይላል፦ ወደ ጽዮን ተመልሻለሁ፥ በኢየሩሳሌምም መካከል እኖራለሁ፣ ኢየሩሳሌምም የእውነት ከተማ ትባላለች፣ የሠራዊትም ጌታ የእግዚአብሔር ተራራ የተቀደሰ ተራራ ይባላል።'),
  ('fd295f7f-fa5e-53c9-ad0f-0a78139b184a', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 4, 4, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ዳግመኛ ሽማግሌዎችና ባልቴቶች በኢየሩሳሌም አደባባይ ይቀመጣሉ፣ ሰውም ሁሉ ከዕድሜው ብዛት የተነሣ ምርኩዝ በእጁ ይይዛል።'),
  ('4de3f9d6-9ba9-5c15-ad8f-640703dd55ad', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 5, 5, 'የከተማይቱም አደባባዮች በእነዚያ በሚጫወቱ ወንዶችና ሴቶች ልጆች ይሞላሉ።'),
  ('12e2bbf7-4e5c-5d72-a774-e840c4b2236d', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 6, 6, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ በዚህ ወራት በዚህ ሕዝብ ቅሬታ ዓይን ዘንድ ድንቅ ቢሆን፥ በውኑ በእኔ ዓይን ዘንድ ደግሞ ድንቅ ይሆናልን? ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('0758985a-0499-5dc0-a1d7-2475e82a58d3', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 7, 7, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ፥ ሕዝቤን ከምሥራቅ ምድርና ከምዕራብ ምድር አድነዋለሁ፣'),
  ('d73f2f53-e7ac-587c-a0a2-c8073ac16243', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 8, 8, 'አመጣቸዋለሁም፥ በኢየሩሳሌምም ውስጥ ይኖራሉ፣ እነርሱም ሕዝብ ይሆኑኛል፥ እኔም በእውነትና በጽድቅ አምላክ እሆናቸዋለሁ።'),
  ('b3d39007-84b5-593b-a159-f606e5644da7', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 9, 9, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ መቅደሱ ይሠራ ዘንድ የሠራዊት ጌታ የእግዚአብሔር ቤት ከተመሠረተበት ቀን ጀምሮ ከነቢያት አፍ ይህን ቃል በዚህ ዘመን የሰማችሁ እናንተ ሆይ፥ እጃችሁን አበርቱ።'),
  ('88f431a4-ad1b-5dcf-a52f-99d4edf1f5c6', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 10, 10, 'ከዚያ ወራት አስቀድሞ ለሰውና ለእንስሳ ዋጋ አልነበረምና፣ እኔም ሰውን ሁሉ በወንድሙ ላይ አስነሥቼ ነበርና ከአስጨናቂው የተነሣ ለሚገባውና ለሚወጣው ሰላም አልነበረም።'),
  ('1e150e33-abe3-5a25-ac52-0c5a27efe013', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 11, 11, 'አሁን ግን እንደ ቀደመው ዘመን በዚህ ሕዝብ ቅሬታ ላይ አልሆንም፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('a9b42b7c-9840-54cc-acd1-cc4841aff532', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 12, 12, 'ነገር ግን ሰላምን እዘራለሁ፣ ወይኑ ፍሬውን ይሰጣል፥ ምድርም አዝመራዋን ታወጣለች፥ ሰማያትም ጠላቸውን ይሰጣሉ፣ ለዚህም ሕዝብ ቅሬታ ይህን ነገር ሁሉ አወርሳለሁ።'),
  ('07a88a12-674a-5ee6-ac4f-f66a273eda9d', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 13, 13, 'የይሁዳ ቤትና የእስራኤል ቤት ሆይ፥ በአሕዛብ ዘንድ እርግማን እንደ ነበራችሁ፥ እንዲሁ አድናችኋለሁ፥ በረከትም ትሆናላችሁ፣ አትፍሩ፥ እጃችሁንም አበርቱ።'),
  ('3cb2fe98-f08a-5c1e-aaca-811ebde48f17', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 14, 14, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላልና፦ አባቶቻችሁ እጅግ ባስቈጡኝ ጊዜ ክፉ ለማድረግ እንዳሰብሁ፥ እንዳልተጸጸትሁም፥ ይላል የሠራዊት ጌታ እግዚአብሔር፥'),
  ('6fe528ba-cb78-5f46-a290-6dd5eaa18ed9', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 15, 15, 'እንዲሁ ዳግመኛ ለኢየሩሳሌምና ለይሁዳ ቤት በዚህ ወራት በጎነትን አደርግ ዘንድ አስቤአለሁ፣ አትፍሩ።'),
  ('2da28c60-ec24-58fd-aae0-c6bbf7d75df8', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 16, 16, 'የምትሠሩት ነገር ይህ ነው፣ እያንዳንዳችሁ ከባልንጀራችሁ ጋር እውነትን ተነጋገሩ፣ በበር አደባባያችሁም የእውነትንና የሰላምን ፍርድ ፍረዱ፣'),
  ('6ecf1253-e219-532c-ad0b-1da596c5230b', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 17, 17, 'ሁላችሁም በባልንጀራችሁ ላይ ክፉን ነገር በልባችሁ አታስቡ፣ የሐሰትንም መሐላ አትውደዱ፣ ይህን ነገር ሁሉ እጠላለሁና፥ ይላል እግዚአብሔር።'),
  ('70ac811d-3b01-5d19-a2e3-e5c813080f4c', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 18, 18, 'የሠራዊት ጌታ የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('e0948add-c812-5539-ac95-bc8493560027', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 19, 19, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ የአራተኛው ወር ጾም የአምስተኛውም የሰባተኛውም የአሥረኛውም ወር ጾም ለይሁዳ ቤት ደስታና ተድላ የሐሤትም በዓላት ይሆናል፣ ስለዚህም እውነትንና ሰላምን ውደዱ።'),
  ('86e6312d-d7ea-5d9d-a112-8b91a6b30f38', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 20, 20, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ በብዙ ከተሞች የሚቀመጡ አሕዛብ ገና ይመጣሉ፣'),
  ('eb4d0dc2-ca7a-5dc6-ad88-515ced5c881d', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 21, 21, 'በአንዲትም ከተማ የሚኖሩ ሰዎች፦ እግዚአብሔርን እንለምን ዘንድ፥ የሠራዊትንም ጌታ እግዚአብሔርን እንፈልግ ዘንድ ኑ እንሂድ፣ እኔም እሄዳለሁ እያሉ ወደ ሌላ ከተማ ይሄዳሉ።'),
  ('47371ec3-1392-5acc-a1b4-d13129dab51c', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 22, 22, 'ብዙ ወገኖችና ኃይለኞች አሕዛብ በኢየሩሳሌም የሠራዊትን ጌታ እግዚአብሔርን ይፈልጉ ዘንድ፥ እግዚአብሔርንም ይለምኑ ዘንድ ይመጣሉ።'),
  ('7797b0db-a074-5367-a089-31a2c4c32bdb', '7d08c674-7b56-56e7-a344-fdade24b3241', 'e41f4420-d1a7-511b-ad53-2d99814ba1b1', 23, 23, 'የሠራዊትም ጌታ እግዚአብሔር እንዲህ ይላል፦ በዚያ ዘመን ከአሕዛብ ቋንቋ ሁሉ አሥር ሰዎች የአንዱን አይሁዳዊ ሰው ልብስ ዘርፍ ይዘው፦ እግዚአብሔር ከእናንተ ጋር እንዳለ ሰምተናልና ከእናንተ ጋር እንሂድ ይላሉ።'),
  ('fa5d5230-c584-5093-a1fe-2c851d2fb47b', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 1, 1, 'የእግዚአብሔር ቃል ሸክም በሴድራክ ምድር ላይ ነው፥ በደማስቆም ላይ ያርፋል፣ የእግዚአብሔር ዓይን ወደ ሰውና ወደ እስራኤል ነገድ ሁሉ ዘንድ ነው፣'),
  ('0b9e5c51-e527-56e8-afc3-e45e73f0d47d', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 2, 2, 'ደግሞም በዳርቻዋ ባለችው በሐማት ላይ፥ እጅግ ጠቢበኞች በሆኑ በጢሮስና በሲዶና ላይ ነው።'),
  ('b3c6ed11-3ceb-5872-aadb-f0ff4995a32f', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 3, 3, 'ጢሮስም ምሽግን ለራስዋ ሠርታለች፥ ብሩንም እንደ አፈር ጥሩውንም ወርቅ እንደ መንገድ ጭቃ አከማችታለች።'),
  ('2b27b1a4-4200-57e4-aacb-35de0911f45f', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 4, 4, 'እነሆ፥ ጌታ ይገፍፋታል፥ በባሕርም ላይ ያለውን ብርታትዋን ይመታል፣ እርስዋም በእሳት ትበላለች።'),
  ('b34e60d8-e03f-599c-ac4a-b19c8e800873', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 5, 5, 'አስቀሎና አይታ ትፈራለች፣ ጋዛ ደግሞ አይታ እጅግ ትታመማለች፣ አቃሮንም እንዲሁ፥ ተስፋዋ ይቈረጣልና፣ ንጉሡም ከጋዛ ይጠፋል፥ በአስቀሎናም የሚቀመጥ አይገኝም።'),
  ('ac213560-8dbd-5d1c-a6ea-e1230f683490', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 6, 6, 'የተደባለቀ ወገን በአዛጦን ይቀመጣል፥ የፍልስጥኤማውያንንም ትዕቢት አጠፋለሁ።'),
  ('12a17405-30ee-5c76-ac0f-309f27ad2ba2', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 7, 7, 'ደሙንም ከአፉ ውስጥ ርኩሱንም ነገር ከጥርሱ መካከል አስወግዳለሁ፣ እርሱም ደግሞ ለአምላካችን ቅሬታ ይሆናል፣ በይሁዳም እንደ አለቃ ይሆናል፥ አቃሮንም እንደ ኢያቡሳዊ ይሆናል።'),
  ('6dfa87e6-dab5-564b-a5f4-0ca253e45264', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 8, 8, 'እኔም ማንም እንዳይሄድና እንዳይመለስ እንደ ጠባቂ ጦር ሆኖ በቤቴ ዙሪያ ሰፈር አደርጋለሁ፣ አሁንም በዓይኔ አይቻለሁና ከዚህ በኋላ አስጨናቂ አያልፍባቸውም።'),
  ('7b7c8338-d9fc-53ec-a430-0c30f6e70600', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 9, 9, 'አንቺ የጽዮን ልጅ ሆይ፥ እጅግ ደስ ይበልሽ፣ አንቺ የኢየሩሳሌም ልጅ ሆይ፥ እልል በዪ፣ እነሆ፥ ንጉሥሽ ጻድቅና አዳኝ ነው፣ ትሑትም ሆኖ በአህያም፥ በአህያይቱ ግልገል በውርጫንይቱ ላይ ተቀምጦ ወደ አንቺ ይመጣል።'),
  ('d70d73cf-2ad9-5ab9-ab36-ea27ff89ec14', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 10, 10, 'ሰረገላውንም ከኤፍሬም ፈረሱንም ከኢየሩሳሌም አጠፋለሁ የሰልፉም ቀስት ይሰበራል፥ ለአሕዛብም ሰላምን ይናገራል፣ ግዛቱም ከባሕር እስከ ባሕር፥ ከወንዙም እስከ ምድር ዳርቻ ድርስ ይሆናል።'),
  ('770ad662-6064-54d7-a064-3e84092c21c5', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 11, 11, 'ለአንቺም ደግሞ ስለ ቃል ኪዳንሽ ደም፥ እስሮችሽን ውኃ ከሌለበት ጕድጓድ አውጥቻለሁ።'),
  ('740b7451-cd63-5172-aa14-1ffccd0530fd', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 12, 12, 'እናንተ በተስፋ የምትኖሩ እስሮች ሆይ፥ ወደ ጽኑ አምባ ተመለሱ፣ ሁለት እጥፍ አድርጌ እንድመልስልሽ ዛሬ እነግርሻለሁ።'),
  ('6902f513-ca20-5a74-a7a2-0ffee36e7c99', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 13, 13, 'ይሁዳን ለእኔ ገትሬአለሁ፣ ቀስቱን በኤፍሬም ሞልቼአለሁ፣ ጽዮን ሆይ፥ ልጆችሽን በግሪክ ልጆች ላይ አስነሣለሁ፥ አንቺንም እንደ ኃያል ሰው ሰይፍ አደርግሻለሁ።'),
  ('477949d6-294e-595d-ae46-d96fcb114021', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 14, 14, 'እግዚአብሔርም በእነርሱ ላይ ይገለጣል፥ ፍላጻውም እንደ መብረቅ ይወጣል፣ ጌታ እግዚአብሔርም መለከትን ይነፋል፥ በደቡብም ዐውሎ ነፋስ ይሄዳል።'),
  ('bdbcc686-60d0-5833-a1d9-02a32d7ace8f', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 15, 15, 'የሠራዊት ጌታ እግዚአብሔር ይጠብቃቸዋል፣ እነርሱም ይበሉአቸዋል፥ የወንጭፉንም ድንጋዮች ይረግጣሉ፣ እንደ ወይን ጠጅም ይጠጡአቸዋል፥ እንደ ጥዋዎችም እንደ መሠዊያም ማዕዘኖች የተሞሉ ይሆናሉ።'),
  ('152f2c71-b8b4-5a8c-a3e1-b0e4092d089b', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 16, 16, 'በዚያም ቀን አምላካቸው እግዚአብሔር እንደ ሕዝቡ መንጋ ያድናቸዋል፣ እነርሱም ለአክሊል እንደሚሆኑ እንደ ከበሩ ድንጋዮች ይሆናሉ፥ በምድሩም ላይ ይብለጨለጫሉ።'),
  ('36731e10-3e21-5f40-a507-47a598ba16ac', 'c8edbc37-b3d4-5e0e-abf8-7f773d40bf98', '373cbcb7-dd0b-583d-a7ab-6ea9b7a44398', 17, 17, 'በጎነቱ እንዴት ታላቅ ነው! ውበቱስ እንዴት ታላቅ ነው! እህል ጐበዛዝቱን፥ ጉሽ ጠጅም ቈነጃጅቱን ያለመልማል።'),
  ('7229e8ac-bea7-56c1-a5a7-e50a59c04406', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 1, 1, 'በኋለኛው ዝናብ ጊዜ ከእግዚአብሔር ዘንድ ዝናቡን ለምኑ፣ እግዚአብሔር መብረቅ ያደርጋል፣ እርሱም የበልግ ዝናብን ለእያንዳንዱም በሜዳ ውስጥ ሣርን ይሰጣል።'),
  ('1412b8fc-6fa8-5e6b-a732-652ad3977525', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 2, 2, 'ተራፊም ከንቱነትን ተናግረዋልና፥ ምዋርተኞችም ውሸትን አይተዋልና፣ ሕልምንም የሚያዩ በሐሰት ተናግረዋል፥ በከንቱም ያጽናናሉ፣ እረኛም የላቸውምና እንደ በጎች ተቅበዝብዘዋል ተጨንቀውማል።'),
  ('26c04ab7-cb67-5b5f-a972-fcae1a892b2d', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 3, 3, 'ቍጣዬ በእረኞች ላይ ነድዶአል፥ አውራ ፍየሎችንም እቀጣለሁ፣ የሠራዊት ጌታ እግዚአብሔርም የይሁዳን ቤት መንጋውን ጐብኝቶአል፥ በሰልፍም ውስጥ እንዳለ እንደ ክብሩ ፈረስ ያደርጋቸዋል።'),
  ('5b26c42f-1cc1-5ec4-a5bc-88cc3dc4a1c7', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 4, 4, 'ከእርሱ ዘንድ የማዕዘኑ ድንጋይ፥ ከእርሱም ዘንድ ችንካሩ፥ ከእርሱም ዘንድ የሰልፍ ቀስት፥ ከእርሱም ዘንድ አስገባሪው ሁሉ በአንድ ላይ ይመጣሉ።'),
  ('90e08b0d-1a1e-51e7-aae7-13eb60b94221', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 5, 5, 'በሰልፍም ጊዜ ጠላቶቻቸውን በመንገድ ጭቃ ውስጥ እንደሚረግጡ ኃያላን ይሆናሉ፣ እግዚአብሔርም ከእነርሱ ጋር ነውና ይዋጋሉ፥ ፈረሰኞችም ያፍራሉ።'),
  ('c81bb4ff-f12b-5c04-aa02-a3487343003b', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 6, 6, 'ወድጃቸዋለሁና የይሁዳን ቤት አበረታለሁ፥ የዮሴፍንም ቤት አድናለሁ፣ አደላድላቸዋለሁም፣ እመልሳቸዋለሁ፣ እኔም አምላካቸው እግዚአብሔር ነኝና፥ እኔም እሰማቸዋለሁና እንዳልጣልኋቸው ይሆናሉ።'),
  ('d9492178-f7c8-5ede-afb2-aee27704f34d', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 7, 7, 'የኤፍሬምም ሰዎች እንደ ኃያላን ይሆናሉ፥ ልባቸውም የወይን ጠጅ እንደ ጠጣ ሰው ደስ ይለዋል፣ ልጆቻቸውም አይተው ደስ ይላቸዋል፥ ልባቸውም በእግዚአብሔር ሐሤት ያደርጋል።'),
  ('c98131a0-4de7-5019-a1de-d5b879463cf1', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 8, 8, 'ተቤዥቼአቸዋለሁና በፉጨት ጠርቼ እሰበስባቸዋለሁ፣ ቀድሞም በዝተው እንደ ነበሩ ይበዛሉ።'),
  ('8438e160-2fd4-5fb9-a981-0f420df9c9af', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 9, 9, 'በአሕዛብም መካከል ብዘራቸው እንኳ በሩቅ አገር ሳሉ ያስቡኛል፥ ከልጆቻቸውም ጋር በሕይወት ይኖራሉ፥ ይመለሱማል።'),
  ('be2dfccc-6c16-5f7f-aa67-8d5b25e72854', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 10, 10, 'ከግብጽም ምድር እመልሳቸዋለሁ፥ ከአሦርም እሰበስባቸዋለሁ፣ ወደ ገለዓድና ወደ ሊባኖስ ምድር አመጣቸዋለሁ፥ የሚበቃም ቦታ አይገኝላቸውም።'),
  ('4c648337-be71-5c06-afee-31b2b026c124', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 11, 11, 'እርሱም በጭንቅ ባሕር ያልፋል፥ የባሕርንም ሞገድ ይመታል፥ የወንዙም ጥልቅ ሁሉ ይደርቃል፣ የአሦርም ትዕቢት ይዋረዳል፥ የግብጽም በትረ መንግሥት ይርቃል።'),
  ('2d7a79d8-808c-52cf-a775-08c852a798dd', '6dfc4ed7-12b1-5aab-a9ec-134d4f2977ef', '563f57b2-4b12-5b17-a37f-e5434625aa10', 12, 12, 'በአምላካቸው በእግዚአብሔር አበረታቸዋለሁ፥ በስሙም ይመካሉ፥ ይላል እግዚአብሔር።'),
  ('25db59dc-56d5-56a9-a2da-0a17f21c21e3', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 1, 1, 'ሊባኖስ ሆይ፥ ደጆችህን ክፈት፥ እሳትም ዝግባዎችህን ትብላ።'),
  ('ede2f3a6-e1d0-591c-a087-84297863343b', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 2, 2, 'የጥድ ዛፍ ሆይ፥ ዝግባ ወድቆአልና፥ ከበርቴዎችም ጠፍተዋልና ዋይ በል፣ እናንተም የባሳን ዛፎች ሆይ፥ ጽኑው ጫካ ተቈርጦአልና ዋይ በሉ።'),
  ('bc89b5b5-2db5-5376-a158-42d80f6d5a5a', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 3, 3, 'የእረኞች ክብር ተዋርዶአልና የዋይታቸው ድምፅ ተሰምቶአል፣ የዮርዳኖስ ትዕቢት ተዋርዶአልና የአንበሶች ግሣት ድምፅ ተሰምቶአል።'),
  ('262db0bd-2553-5eca-a0fe-e07600bf8a1b', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 4, 4, 'አምላኬ እግዚአብሔር እንዲህ ብሎአል፦ ለእርድ የሚሆኑትን በጎች ጠብቅ።'),
  ('7f76805a-5441-5af8-a9a2-7bc196a5e56c', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 5, 5, 'የገዙአቸው ያርዱአቸዋል፥ ራሳቸውንም እንደ በደለኞች አድርገው አይቈጥሩም፣ የሸጡአቸውም፦ ባለ ጠጋ ሆነዋልና እግዚአብሔር ይመስገን ይላሉ፣ እረኞቻቸውም አይራሩላቸውም።'),
  ('a360c7fd-0771-5b3f-aeed-ddf6ddcfcaad', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 6, 6, 'ከእንግዲህ ወዲህ በምድር ላይ ለሚኖሩ አልራራም፥ ይላል እግዚአብሔር፣ እነሆም፥ ሰውን ሁሉ በባልንጀራውና በንጉሡ እጅ አሳልፌ እሰጣለሁ፣ ምድሪቱም ይመታሉ፥ ከእጃቸውም አላድናቸውም።'),
  ('13e0ad1a-8b16-59f0-a04b-b0ac8106023a', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 7, 7, 'እኔም ለእርድ የሚሆኑትን በጎች፥ የመንጋውን ችግረኞች ጠበቅሁ። ሁለት በትሮችንም ወሰድሁ፣ የአንዲቱን ስም ውበት የሁለተኛይቱንም ስም ማሰሪያ ብዬ ጠራሁ፣ መንጋውንም ጠበቅሁ።'),
  ('e2d06f62-4784-5683-a172-738a077775ba', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 8, 8, 'በአንድ ወርም ሦስቱን እረኞች አጠፋሁ፣ ነፍሴም ተሰቀቀቻቸው፥ ነፍሳቸውም ደግሞ እኔን ጠላች።'),
  ('7caf43a2-5c45-5efd-a2ce-e2f941ca5437', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 9, 9, 'እኔም፦ እናንተን አልጠብቅም፣ የሚሞተው ይሙት፥ የሚጠፋውም ይጥፋ፣ የቀረውም እያንዳንዱ የባልንጀራውን ሥጋ ይብላ አልሁ።'),
  ('b949574e-3791-52f0-aad4-4ef37380bd5b', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 10, 10, 'እኔም ከሕዝቦች ሁሉ ጋር የገባሁትን ቃል ኪዳኔን አፈርስ ዘንድ ውበት የተባለችውን በትሬን ወስጄ ቈረጥሁ።'),
  ('28c5e4a6-c2b7-5b2a-ab45-2a5cca176602', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 11, 11, 'በዚያም ቀን ተሰበረች፣ እንዲሁም እኔን የተመለከቱ የመንጋው ችግረኞች የእግዚአብሔር ቃል እንደ ነበረ አወቁ።'),
  ('b9cc859d-8b18-5b66-acf3-46df61c5dbb3', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 12, 12, 'እኔም፦ ደስ ብሎአችሁ እንደ ሆነ ዋጋዬን ስጡኝ፣ ያለዚያ ግን ተውት አልሁ። እነርሱም ለዋጋዬ ሠላሳ ብር መዘኑ።'),
  ('70553a9f-2dbc-551e-a615-509bb46b9bd6', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 13, 13, 'እግዚአብሔርም፦ የተስማሙበትን የከበረውን ዋጋዬን በግምጃ ቤቱ ውስጥ አኑረው አለኝ። እኔም ሠላሳውን ብር ወስጄ በእግዚአብሔር ቤት ባለው በግምጃ ቤቱ ውስጥ አኖርሁት።'),
  ('ccdef0e3-22e8-5c4b-a610-3930eba41d49', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 14, 14, 'በይሁዳና በእስራኤል መካከል ያለውንም ወንድማማችነት እሰብር ዘንድ ማሰሪያ የተባለቸውን ሁለተኛይቱን በትሬን ቈረጥሁ።'),
  ('9c1e1af1-b47d-5509-a539-9462a5f3990d', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 15, 15, 'እግዚአብሔርም እንዲህ አለኝ፦ ዳግመኛም የሰነፍን እረኛ ዕቃ ውሰድ።'),
  ('c94c7748-a55c-5a0b-aa1b-32f9a213630a', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 16, 16, 'እነሆ፥ በአገሩ ውስጥ እረኛ አስነሣለሁ፣ እርሱም የጠፋውን አያስብም፥ የባዘነውን አይፈልግም፥ የተሰበረውን አይጠግንም፣ የዳነውንም አይቀልብም፥ ነገር ግን የሰባውን ሥጋ ይበላል፥ ሰኰናውንም ይቀለጣጥማል።'),
  ('ac25e77a-290d-5421-ab30-6d50bebfb6f4', '29ccdcd6-6851-5e8b-a66e-29f0bb067c88', '36e0a36b-b023-5a27-ac88-933e53b671fc', 17, 17, 'መንጋውን ለሚተው ለምናምንቴ እረኛ ወዮለት! ሰይፍ በክንዱና በቀኝ ዓይኑ ላይ ይሆናል፣ ክንዱም አጥብቃ ትደርቃለች፥ ቀኝ ዓይኑም ፈጽማ ትጨልማለች።'),
  ('be25d4bf-1aa7-52f0-a381-00830c598a9c', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 1, 1, 'ስለ እስራኤል የተነገረ የእግዚአብሔር ቃል ሸክም ይህ ነው። ሰማያትን የዘረጋ፥ ምድርንም የመሠረተ፥ የሰውንም መንፈስ በውስጡ የሠራ እግዚአብሔር እንዲህ ይላል፦'),
  ('df02788a-c582-5150-a489-e273430e8732', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 2, 2, 'እነሆ፥ ኢየሩሳሌምን በዙሪያዋ ላሉት ለአሕዛብ ሁሉ የመንገድገድ ዋንጫ አደርጋታለሁ፣ ደግሞም ኢየሩሳሌም ስትከበብ በይሁዳ ላይ እንዲሁ ይሆናል።'),
  ('ce5baa01-0314-5ca7-a249-1ffe00a82d3f', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 3, 3, 'በዚያም ቀን ኢየሩሳሌምን ለአሕዛብ ሁሉ ከባድ ድንጋይ አደርጋታለሁ፣ የሚሸከሙአት ሁሉ እጅግ ይቈስላሉ፣ የምድርም አሕዛብ ሁሉ በላይዋ ላይ ይከማቻሉ።'),
  ('a2ee2256-217a-5432-a61c-77becc95ea82', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 4, 4, 'በዚያ ቀን፥ ይላል እግዚአብሔር፥ ፈረስን ሁሉ በድንጋጤ፥ ተቀማጭንም በእብድነት እመታለሁ፣ ዓይኖቼንም በይሁዳ ላይ እከፍታለሁ፥ የአሕዛብንም ፈረሶች ሁሉ በዕውርነት እመታለሁ።'),
  ('a11322b7-1290-5e03-a13f-7866b6ab0b66', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 5, 5, 'የይሁዳም አለቆች በልባቸው፦ በኢየሩሳሌም ለሚኖሩ በአምላካቸው በሠራዊት ጌታ በእግዚአብሔር ብርታት አለ ይላሉ።'),
  ('5e0568e7-f593-5394-acdb-1d98f0a07f42', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 6, 6, 'በዚያ ቀን የይሁዳን አለቆች በእንጨት መካከል እንዳለ ትንታግ፥ በነዶችም መካከል እንዳለ እንደ ፋና ነበልባል አደርጋቸዋለሁ፣ በቀኝና በግራ በዙሪያ ያሉትን አሕዛብ ሁሉ ይበላሉ፣ ከዚያም ወዲያ ኢየሩሳሌም በስፍራዋ በኢየሩሳሌም ትኖራለች።'),
  ('b88568bd-902d-5d47-af82-60e40941feff', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 7, 7, 'እግዚአብሔርም የዳዊት ቤት ክብርና የኢየሩሳሌም ሰዎች ክብር በይሁዳ ክብር ላይ እንዳይታበይ የይሁዳን ድንኳኖች አስቀድሞ ያድናል።'),
  ('36277ddf-d79f-58ac-a606-59d0c4740ae3', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 8, 8, 'በዚያ ቀን እግዚአብሔር በኢየሩሳሌም ለሚኖሩት ይመክትላቸዋል፣ በዚያም ቀን ከእነርሱ መካከል ደካማው እንደ ዳዊት ይሆናል፣ የዳዊትም ቤት በፊታቸው እንደ እግዚአብሔር መልአክ እንደ አምላክ ይሆናል።'),
  ('ebfa9dfa-43c0-5eb2-a59d-0020007f13ff', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 9, 9, 'በዚያም ቀን በኢየሩሳሌም ላይ የሚመጡትን አሕዛብ ሁሉ ለማጥፋት እጋደላለሁ።'),
  ('37289ea0-2b3f-5141-acbc-cf3461f3f413', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 10, 10, 'በዳዊትም ቤት ላይ፥ በኢየሩሳሌምም በሚኖሩት ላይ፥ የሞገስንና የልመናን መንፈስ አፈስሳለሁ፣ ወደ እርሱም ወደ ወጉት ይመለከታሉ፣ ሰውም ለአንድያ ልጁ እንደሚያለቅስ ያለቅሱለታል፥ ሰውም ለበኵር ልጁ እንደሚያዝን በመራራ ኅዘን ያዝኑለታል።'),
  ('f0b00866-0c0b-59ac-a477-8b04ff7fc130', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 11, 11, 'በዚያ ቀን በመጊዶን ሜዳ እንደ ነበረው እንደ ሐዳድሪሞን ልቅሶ ታላቅ ልቅሶ በኢየሩሳሌም ይሆናል።'),
  ('995d6b75-cdee-5619-a13c-a5dae1a55e78', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 12, 12, 'ምድሪቱም ታለቅሳለች፣ እያንዳንዱ ወገን ለብቻው፥ የዳዊት ቤት ወገን ለብቻው፥ ሴቶቻቸውም ለብቻቸው፣ የናታን ቤት ወገን ለብቻው፥ ሴቶቻቸውም ለብቻቸው፣'),
  ('52b666ff-7a55-56af-a0f1-904fd6671244', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 13, 13, 'የሌዊ ቤት ወገን ለብቻው፥ ሴቶቻቸውም ለብቻቸው፣ የሰሜኢ ወገን ለብቻው፥ ሴቶቻቸውም ለብቻቸው፣'),
  ('a4d9fc68-200b-569c-a2a7-255c4f7daeae', '5aa58657-b726-59e7-a186-9a78084a8ed2', 'b9247c88-9ee8-519c-ae6a-a270589a3334', 14, 14, 'የቀሩት ወገኖች ሁሉ እያንዳንዱ ወገን ለብቻው፥ ሴቶቻቸውም ለብቻቸው ያለቅሳሉ።'),
  ('a35e6476-63dc-5017-a0c4-47f6d272a3d0', 'f6b4750e-04c5-5f4d-a02b-b277619be4ca', 'a899cb79-b67a-5c4d-a6d9-22468341634c', 1, 1, 'በዚያ ቀን ለዳዊት ቤትና በኢየሩሳሌም ለሚኖሩ ከኃጢአትና ከርኵሰት የሚያነጻ ምንጭ ይከፈታል።'),
  ('5b0957c7-b055-51b4-a70f-91b8e8e176e7', 'f6b4750e-04c5-5f4d-a02b-b277619be4ca', 'a899cb79-b67a-5c4d-a6d9-22468341634c', 2, 2, 'በዚያ ቀን፥ ይላል የሠራዊት ጌታ እግዚአብሔር፥ የጣዖታትን ስም ከምድር አጠፋለሁ፥ ከዚያም በኋላ አይታሰቡም፣ ደግሞም ሐሰተኞችን ነቢያትና ርኩስ መንፈስን ከምድር ላይ አስወግዳለሁ።'),
  ('4de4f83a-cd80-5791-a648-1e5d2b4384ae', 'f6b4750e-04c5-5f4d-a02b-b277619be4ca', 'a899cb79-b67a-5c4d-a6d9-22468341634c', 3, 3, 'ማንም ደግሞ ትንቢት ቢናገር የወለዱት አባቱና እናቱ፦ አንተ በእግዚአብሔር ስም ሐሰትን ተናግረሃልና በሕይወት አትኖርም ይሉታል፣ ትንቢትንም ሲናገር የወለዱት አባቱና እናቱ ይወጉታል።'),
  ('7577b4c5-a20e-574b-a239-c69f7b1001d0', 'f6b4750e-04c5-5f4d-a02b-b277619be4ca', 'a899cb79-b67a-5c4d-a6d9-22468341634c', 4, 4, 'በዚያም ቀን ነቢያቱ ሁሉ ትንቢትን ሲናገሩ እያንዳንዱ ስለ ራእዩ ያፍራል፣ ያታልሉም ዘንድ የማቅ ልብስ አይለብሱም።'),
  ('039b4f1d-f7f8-532b-a557-d64538113ec0', 'f6b4750e-04c5-5f4d-a02b-b277619be4ca', 'a899cb79-b67a-5c4d-a6d9-22468341634c', 5, 5, 'እርሱ ግን፦ ከታናሽነቴ ጀምሮ ባሪያ ሆኜ ነበርሁና ገበሬ ሰው ነኝ እንጂ ነቢይ አይደለሁም ይላል።'),
  ('379e3feb-1f48-5b54-a8bd-afcef08520f7', 'f6b4750e-04c5-5f4d-a02b-b277619be4ca', 'a899cb79-b67a-5c4d-a6d9-22468341634c', 6, 6, 'ሰውም፦ ይህ በእጅህ መካከል ያለ ቁስል ምንድር ነው? ይለዋል። እርሱም፦ በወዳጆቼ ቤት የቈሰልሁት ቍስል ነው ይላል።'),
  ('0b7bc55a-b97f-577f-a75c-2e9761d5f48d', 'f6b4750e-04c5-5f4d-a02b-b277619be4ca', 'a899cb79-b67a-5c4d-a6d9-22468341634c', 7, 7, 'ሰይፍ ሆይ፥ ባልንጀራዬ በሆነው ሰው በእረኛዬ ላይ ንቃ፥ ይላል የሠራዊት ጌታ እግዚአብሔር፣ እረኛውን ምታ፥ በጎቹም ይበተናሉ፣ እጄንም በታናናሾች ላይ እመልሳለሁ።'),
  ('7f08c507-b813-5301-a25e-07e28b3d67e9', 'f6b4750e-04c5-5f4d-a02b-b277619be4ca', 'a899cb79-b67a-5c4d-a6d9-22468341634c', 8, 8, 'በምድርም ሁሉ ላይ ሁለት ክፍል ተቈርጠው ይሞታሉ፥ ይላል እግዚአብሔር፣ ሦስተኛውም ክፍል በእርስዋ ውስጥ ይቀራል።'),
  ('fa3eec05-6468-573e-a7d7-53ee32b89a3c', 'f6b4750e-04c5-5f4d-a02b-b277619be4ca', 'a899cb79-b67a-5c4d-a6d9-22468341634c', 9, 9, 'ሦስተኛውንም ክፍል ወደ እሳት አገባለሁ፥ ብርም እንደሚነጥር አነጥራቸዋለሁ፥ ወርቅም እንደሚፈተን እፈትናቸዋለሁ፣ እነርሱም ስሜን ይጠራሉ፥ እኔም እሰማቸዋለሁ፣ እኔም፦ ይህ ሕዝቤ ነው እላለሁ፣ እርሱም፦ እግዚአብሔር አምላኬ ነው ይላል።'),
  ('8a556b2f-7486-529b-a9a4-9e0bdcb15ab1', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 1, 1, 'እነሆ፥ የእግዚአብሔር ቀን ይመጣል፥ ብዝበዛሽንም በውስጥሽ ይካፈላሉ።'),
  ('bd14121e-ce38-567b-aad0-9fbfc764e5d6', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 2, 2, 'አሕዛብንም ሁሉ በኢየሩሳሌም ላይ ለሰልፍ እሰበስባለሁ፣ ከተማይቱም ትያዛለች፥ ቤቶችም ይበዘበዛሉ፥ ሴቶችም ይነወራሉ፣ የከተማይቱም እኵሌታ ለምርኮ ይወጣል፥ የቀረው ሕዝብ ግን ከከተማ አይጠፋም።'),
  ('dffb046b-e567-56a6-ad66-3401372b7e3d', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 3, 3, 'እግዚአብሔርም ይወጣል፥ በሰልፍም ቀን እንደ ተዋጋ ከእነዚያ አሕዛብ ጋር ይዋጋል።'),
  ('c8afe965-d4c3-520d-a454-cdb261064a06', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 4, 4, 'በዚያም ቀን እግሮቹ በኢየሩሳሌም ትይዩ በምሥራቅ በኩል ባለው በደብረ ዘይት ላይ ይቆማሉ፣ ደብረ ዘይትም በመካከል ወደ ምሥራቅና ወደ ምዕራብ ይሰነጠቃል፥ እጅግም ታላቅ ሸለቆ ይሆናል፣ የተራራውም እኵሌታ ወደ ሰሜን፥ እኵሌታውም ወደ ደቡብ ይርቃል።'),
  ('65aaed3c-9bb7-5951-a873-3437b26dc7b0', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 5, 5, 'የተራሮችም ሸለቆ እስከ አጸል ይደርሳልና በተራሮች ሸለቆ ትሸሻላችሁ፣ በይሁዳም ንጉሥ በዖዝያን ዘመን ከሆነው ከምድር መናወጥ ፊት እንደ ሸሻችሁ ትሸሻላችሁ፣ አምላኬ እግዚአብሔርም ከቅዱሳኑ ሁሉ ጋር ይመጣል።'),
  ('1ddc5b51-6ae6-5861-a53d-70dd0a65ffec', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 6, 6, 'በዚያም ቀን በረዶና ውርጭ እንጂ ብርሃን አይሆንም።'),
  ('abf1e3e3-6f8d-5989-a7ac-bda626d0d974', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 7, 7, 'አንድ ቀንም ይሆናል፥ እርሱም በእግዚአብሔር ዘንድ የታወቀ ይሆናል፣ ቀንም አይሆንም፥ ሌሊትም አይሆንም፣ ሲመሽም ብርሃን ይሆናል።'),
  ('ad9c5bbf-9ec7-536e-a508-1961911b7696', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 8, 8, 'በዚያም ቀን የሕይወት ውኃ ከኢየሩሳሌም ይወጣል፣ እኵሌታው ወደ ምሥራቁ ባሕር፥ እኵሌታውም ወደ ምዕራቡ ባሕር ይሄዳል፣ ይህ በበጋና በክረምት ይሆናል።'),
  ('841d41a5-6bed-5234-af4c-3291627253a3', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 9, 9, 'እግዚአብሔርም በምድር ሁሉ ላይ ይነግሣል፣ በዚያ ቀን እግዚአብሔር አንድ፥ ስሙም አንድ ይሆናል።'),
  ('fc928954-6fc1-582b-aee0-dec5e2ee33dd', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 10, 10, 'ምድር ሁሉ ከጌባ ጀምሮ በኢየሩሳሌምም ደቡብ በኩል እስካለችው እስከ ሬሞን ድረስ ተለውጣ እንደ ዓረባ ትሆናለች፣ እርስዋም ከፍ ከፍ ትላለች፥ ከብንያምም በር ጀምሮ እስከ ፊተኛው በር ስፍራ እስከ ማዕዘኑ በር ድረስ፥ ከሐናንኤልም ግንብ ጀምሮ እስከ ንጉሡ መጥመቂያ ድረስ በስፍራዋ ትኖራለች።'),
  ('5f3629b3-d671-53bc-a526-9bed001ce98f', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 11, 11, 'ሰዎችም ይኖሩባታል፥ ከዚያም ወዲያ እርግማን አይሆንም፣ ኢየሩሳሌምም ተዘልላ ትኖራለች።'),
  ('42583a3b-4696-50d5-a1b1-12105d9e4f07', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 12, 12, 'እግዚአብሔርም ከኢየሩሳሌም ጋር የተዋጉትን አሕዛብ ሁሉ የሚቀሥፍበት ቸነፈር ይህ ነው፣ በእግራቸው ሲቆሙ ሥጋቸው ይበሰብሳል፥ ዓይኖቻቸውም በዓይነስባቸው ውስጥ ይበሰብሳሉ፥ ምላሳቸውም በአፋቸው ውስጥ ይበሰብሳል።'),
  ('dbbd4a18-e914-579b-ad6b-28ee0ab2219b', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 13, 13, 'በዚያም ቀን ከእግዚአብሔር ዘንድ ታላቅ ሽብር በእነርሱ ላይ ይሆናል፣ እያንዳንዱም የባልንጀራውን እጅ ይይዛል፥ እጁም በባልንጀራው እጅ ላይ ይነሣል።'),
  ('a93331c0-cc67-5647-ac58-5cab4510ca1d', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 14, 14, 'ይሁዳም ደግሞ በኢየሩሳሌም ውስጥ ሆኖ ይዋጋል፣ በዙሪያም ያሉት የአሕዛብ ሁሉ ሀብት እጅግ ብዙ ወርቅና ብር ልብስም ይሰበሰባል።'),
  ('86d42353-f994-539b-a75c-8a73530e8a7f', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 15, 15, 'በፈረስና በበቅሎ፥ በግመልና በአህያ፥ በዚያም ሰፈር ባለ እንስሳ ሁሉ ላይ የሆነ ቸነፈር እንደዚያ ያለ ቸነፈር ይሆናል።'),
  ('b5cfc141-b219-5af3-a0e9-4fe696b7312a', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 16, 16, 'በኢየሩሳሌም ላይ ከመጡት ከአሕዛብ ሁሉ የቀሩት ሁሉ ለንጉሡ ለሠራዊት ጌታ ለእግዚአብሔር ይሰግዱ ዘንድ፥ የዳስ በዓልንም ያከብሩ ዘንድ በየዓመቱ ይወጣሉ።'),
  ('274ff2fe-45a6-5fb3-ab80-0cb999d495c4', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 17, 17, 'ከምድርም ወገኖች ሁሉ ለንጉሡ ለሠራዊት ጌታ ለእግዚአብሔር ይሰግዱ ዘንድ ወደ ኢየሩሳሌም ለማይወጡ ለእነርሱ ዝናብ አይዘንብላቸውም።'),
  ('1422d0a0-dcac-509f-ac9b-fd45078cbfa2', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 18, 18, 'የግብጽም ወገን ባይወጣ ወደዚያም ባይመጣ፥ እግዚአብሔር የዳስ በዓልን ያከብሩ ዘንድ የማይወጡትን አሕዛብ የሚቀሥፍበት ቸነፈር በእርሱ ላይ ይሆናል።'),
  ('11ab0afb-6374-5bb5-a8e6-159478a40e6f', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 19, 19, 'የግብጽ ቅጣት፥ የዳስ በዓልንም ያከብሩ ዘንድ የማይወጡት የአሕዛብ ሁሉ ቅጣት እንደዚህ ይሆናል።'),
  ('b0c079df-337f-55f8-aaa8-bbdbc14c0e0c', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 20, 20, 'በዚያ ቀን በፈረሶች ሻኵራ ላይ፦ ለእግዚአብሔር የተቀደሰ ተብሎ ይጻፋል፣ በእግዚአብሔርም ቤት ያሉ ምንቸቶች በመሠዊያው ፊት እንዳሉ ዳካዎች ይሆናሉ።'),
  ('10315571-4470-5db4-a840-0296b5069fa4', '59fcf9d7-f088-51e8-affe-9f0cae62cf08', '28725d78-21d2-57e3-a85e-f41167b04c26', 21, 21, 'በኢየሩሳሌምና በይሁዳ ያሉ ምንቸቶችም ሁሉ ለሠራዊት ጌታ ለእግዚአብሔር የተቀደሱ ይሆናሉ፣ የሚሠውትም ሰዎች ሁሉ ይመጣሉ ከእነዚያም ወስደው ይቀቅሉባቸዋል፣ በዚያም ቀን በሠራዊት ጌታ በእግዚአብሔር ቤት ከነዓናዊው ከእንግዲህ ወዲያ አይገኝም።'),
  ('056f9383-d376-5864-aeec-880c1ef09362', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 1, 1, 'በሚልክያስ እጅ ለእስራኤል የሆነ የእግዚአብሔር ቃል ሸክም ይህ ነው።'),
  ('94f58a52-e215-52b2-adac-b6cf7a93a032', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 2, 2, 'ወድጃችኋለሁ፥ ይላል እግዚአብሔር፣ እናንተ ግን፦ በምን ወደድኸን? ብላችኋል። ዔሳው የያዕቆብ ወንድም አልነበረምን? ይላል እግዚአብሔር ያዕቆብንም ወደድሁ፥ ዔሳውንም ጠላሁ።'),
  ('f4b47b4a-fa55-5c21-a8b5-ffa95e41ecd5', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 3, 3, 'ተራሮቹንም በረሃ አደረግኋቸው፥ ርስቱንም ለምድረ በዳ ቀበሮች አሳልፌ ሰጠኋቸው።'),
  ('73c849fe-6ad2-5fe3-ad88-941c5cf11395', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 4, 4, 'ኤዶምያስ፦ እኛ ፈርሰናል፥ ነገር ግን የፈረሰውን መልሰን እንሠራለን ቢል፥ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነርሱ ይሠራሉ፥ እኔ ግን አፈርሳለሁ፣ በሰዎችም ዘንድ፦ የበደል ዳርቻና እግዚአብሔር ለዘላለም የተቈጣው ሕዝብ ይባላል።'),
  ('1e8c4ea2-3e70-53b8-ab76-df5af42fd8d7', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 5, 5, 'ዓይኖቻችሁም ያያሉ፥ እናንተም፦ እግዚአብሔር ከእስራኤል ዳርቻ ወዲያ ታላቅ ይሁን ትላላችሁ።'),
  ('3ac0f308-1b9f-5231-a4ea-1508e85cabc2', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 6, 6, 'እናንተ ስሜን የምታቃልሉ ካህናት ሆይ፥ ልጅ አባቱን፥ ባሪያም ጌታውን ያከብራል፣ እኔስ አባት ከሆንሁ ክብሬ ወዴት አለ? ጌታስ ከሆንሁ መፈራቴ ወዴት አለ? ይላል የሠራዊት ጌታ እግዚአብሔር። እናንተም፦ ስምህን ያቃለልን በምንድር ነው? ብላችኋል።'),
  ('289ffcf2-babf-5502-ad97-7cfdbfbdce25', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 7, 7, 'በመሠዊያዬ ላይ ርኩስ እንጀራ ታቀርባላችሁ። እናንተም፦ ያረከስንህ በምንድር ነው? ብላችኋል። የእግዚአብሔር ገበታ የተነቀፈ ነው በማለታችሁ ነው።'),
  ('e6004540-10ff-5289-acfa-092caa29f466', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 8, 8, 'ዕውር መሥዋዕትንም ስታቀርቡ ይህ ክፉ አይደለምን? አንካሳውንና የታመመውን ስታቀርቡ ይህ ክፉ አይደለምን? ያንን ለአለቃህ አቅርብ፣ በውኑ በአንተ ደስ ይለዋልን? ወይስ ፊትህን ይቀበላልን? ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('f1e5d1a0-f011-53bf-aeef-31bd7784c670', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 9, 9, 'አሁንም ጸጋን ይሰጠን ዘንድ እግዚአብሔርን ለምኑ፣ ይህ ከእጃችሁ የተሰጠ ሲሆን ከቶ ፊታችሁን ይቀበላልን? ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('00d35bae-86d4-5da7-a8a5-26e4bd03fe22', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 10, 10, 'በመሠዊያዬ ላይ እሳትን በከንቱ እንዳታቃጥሉ ከእናንተ ዘንድ ደጅ የሚዘጋ ሰው ምነው በተገኘ! በእናንተ ደስ አይለኝም፥ ቍርባንንም ከእጃችሁ አልቀበልም፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('56d48426-ad25-5a18-a909-7e7c2466cf3b', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 11, 11, 'ከፀሐይ መውጫ ጀምሮ እስከ መግቢያዋ ድረስ ስሜ በአሕዛብ ዘንድ ታላቅ ይሆናልና፣ በየስፍራውም ለስሜ ዕጣን ያጥናሉ፥ ንጹሕም ቍርባን ያቀርባሉ፣ ስሜ በአሕዛብ ዘንድ ታላቅ ይሆናልና፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('1a5ec76b-4de5-5f59-a4ef-f6f673911d42', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 12, 12, 'እናንተ ግን፦ የእግዚአብሔር ገበታ ርኩስ ነው፣ ፍሬውና መብሉም የተናቀ ነው በማለታችሁ አስነቀፋችሁት።'),
  ('9d801413-ad4f-522f-a93e-517de8a130f2', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 13, 13, 'እናንተ፦ እነሆ፥ ይህ ድካም ነው ብላችሁ ጢቅ አላችሁበት፥ ይላል የሠራዊት ጌታ እግዚአብሔር፣ በቅሚያ የያዛችሁትንም አንካሳውንም የታመመውንም አቅርባችኋል፣ እንዲሁ ቍርባንን ታመጣላችሁ፣ በውኑ ከእጃችሁ ይህን ልቀበለውን? ይላል እግዚአብሔር።'),
  ('92882292-e17c-57c7-a8cc-c3207852ca3f', 'a5462ea5-e2b9-57ee-a539-3e829a43d31c', '65dbfbb6-802e-5c9d-a28f-985cc2811770', 14, 14, 'እኔ ታላቅ ንጉሥ ነኝና፥ ይላል የሠራዊት ጌታ እግዚአብሔር፥ ስሜም በአሕዛብ ዘንድ የተፈራ ነውና በመንጋው ውስጥ ተባት እያለው ለጌታ ተስሎ ነውረኛውን የሚሠዋ ሸንጋይ ሰው ርጉም ይሁን።'),
  ('327217b3-cf8a-5787-ae11-1414540321c2', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 1, 1, 'አሁንም እናንተ ካህናት ሆይ፥ ይህ ትእዛዝ ለእናንተ ነው።'),
  ('e476728f-19e5-508e-a99e-2bd73411c5e8', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 2, 2, 'ለስሜ ክብር ትሰጡ ዘንድ ባትሰሙ፥ በልባችሁም ባታደርጉት፥ ይላል የሠራዊት ጌታ እግዚአብሔር፥ እርግማን እሰድዳባችኋለሁ፥ በረከታችሁንም እረግማታለሁ፣ አሁንም በልባችሁ አላደረጋችሁትምና እኔ ረግሜአታለሁ።'),
  ('78b231e9-7863-51fa-a11d-ad051cda05de', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 3, 3, 'እነሆ፥ ክንዳችሁን እገሥጻለሁ፥ የመሥዋዕታችሁንም ፋንድያ በፊታችሁ ላይ እበትናለሁ፣ ከእርሱም ጋር በአንድነት ትወሰዳላችሁ።'),
  ('1ba33fe9-f794-5d2f-a79b-b5a17cdeb646', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 4, 4, 'ቃል ኪዳኔ ከሌዊ ጋር ይሆን ዘንድ ይህን ትእዛዝ እንደ ሰደድሁላችሁ ታውቃላችሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('4dff34ba-d6c5-59d7-a9bd-e69ad56aed1b', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 5, 5, 'ቃል ኪዳኔ ከእርሱ ጋር የሕይወትና የሰላም ቃል ኪዳን ነበረ፣ ይፈራ ዘንድም እነርሱን ሰጠሁት፣ እርሱም ፈራኝ፥ ከስሜም የተነሣ ደነገጠ።'),
  ('9f5cfa1e-7c28-512d-a2b9-e22a621485d2', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 6, 6, 'የእውነት ሕግ በአፉ ውስጥ ነበረች፥ በከንፈሩም ውስጥ በደል አልተገኘበትም፣ ከእኔም ጋር በሰላምና በቅንነት ሄደ፥ ብዙ ሰዎችንም ከኃጢአት መለሰ።'),
  ('059cab12-ee81-5d03-a0bc-3fe707e0276b', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 7, 7, 'ካህኑ የሠራዊት ጌታ የእግዚአብሔር መልእክተኛ ነውና ከንፈሮቹ እውቀትን ይጠብቁ ዘንድ ይገባቸዋል፥ ሰዎችም ሕግን ከአፉ ይፈልጉ ዘንድ ይገባቸዋል።'),
  ('1e9a6a84-9921-53e7-a201-0b5373a07bae', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 8, 8, 'እናንተ ግን ከመንገዱ ፈቀቅ ብላችኋል፣ በሕግም ብዙ ሰዎችን አሰናክላችኋል፣ የሌዊንም ቃል ኪዳን አስነውራችኋል፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('27ded29b-489e-516b-a778-b28143f96f8f', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 9, 9, 'ስለዚህ መንገዴን እንዳልጠበቃችሁ፥ በሕግም ለሰው ፊት እንዳዳላችሁ መጠን፥ እኔ ደግሞ በሕዝብ ሁሉ ፊት የተናቃችሁና የተዋረዳችሁ አድርጌአችኋለሁ።'),
  ('bc364cce-6c5b-59f8-a3dd-7ed4abb26693', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 10, 10, 'ለሁላችን አንድ አባት ያለን አይደለምን? አንድ አምላክስ የፈጠረን አይደለምን? የአባቶቻችንን ቃል ኪዳን ለማስነቀፍ እኛ እያንዳዳችን ወንድማችንን ስለ ምን አታለልን?'),
  ('700a8a3a-d875-5c5d-a046-ad6f8d15f5c1', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 11, 11, 'እግዚአብሔር የወደደውን መቅደስ ይሁዳ አርክሶአልና፥ የእንግዳውንም አምላክ ልጅ ሚስት አድርጎ አግብቶአልና ይሁዳ አታልሎአል፥ በእስራኤልና በኢየሩሳሌም ውስጥ ርኵሰት ተሠርቶአል።'),
  ('66e388a1-4306-5701-ad64-49d4888e2463', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 12, 12, 'ይህን ከሚያደርግ ሰው፥ እግዚአብሔር የሚጠራውንና የሚመልሰውን ለሠራዊትም ጌታ ለእግዚአብሔር ቍርባን የሚያቀርበውን ከያዕቆብ ድንኳን ያጠፋል።'),
  ('4a0517e7-e7bb-5388-af5a-d702b5367d0e', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 13, 13, 'ይህንም ደግሞ አድርጋችኋል፣ እግዚአብሔር ቍርባኑን ዳግመኛ እንዳይመለከት፥ ከእጃችሁም በደስታ እንዳይቀበለው መሠዊያውን በእንባና በልቅሶ በኅዘንም ትከድናላችሁ።'),
  ('7e9551c4-cf2e-57a7-abc1-eeca2c578c61', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 14, 14, 'እናንተም፦ ስለ ምንድር ነው? ብላችኋል። ሚስትህ ባልንጀራህና የቃል ኪዳንህ ሚስት ሆና ሳለች እርስዋን አታልለሃታልና እግዚአብሔር በአንተና በልጅነት ሚስትህ መካከል ምስክር ስለ ሆነ ነው።'),
  ('75ddbf95-0c44-5e53-a711-8f84e050f3ad', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 15, 15, 'እግዚአብሔር የሕይወትን መንፈስ አንድ አድርጎ ጠብቆልን የለምን? እርሱም የሚፈልገው ምንድር ነው? ዘር አይደለምን? ስለዚህ መንፈሳችሁን ጠብቁ፥ ማንም የልጅነት ሚስቱን አያታልል።'),
  ('287ecc1a-ddae-5b01-aa28-75b401f30792', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 16, 16, 'መፋታትን እጠላለሁ፥ ይላል የእስራኤል አምላክ እግዚአብሔር፥ ልብሱንም በግፍ ሥራ የሚከድነውን ሰው እጠላለሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር፣ ስለዚህ እንዳታታልሉ መንፈሳችሁን ጠብቁ።'),
  ('a72972da-7d5c-5ea0-a648-b1e7a8841d0c', '89656a99-e328-5886-a388-47d79e83ac40', '54da7a7e-6b0b-5994-a554-635d8db076a1', 17, 17, 'እግዚአብሔርን በቃላችሁ አታክታችኋል። እናንተም፦ ያታከትነው በምንድር ነው? ብላችኋል። ክፉን የሚያደርግ ሁሉ በእግዚአብሔር ዘንድ መልካም ነው፥ እርሱም በእነርሱ ደስ ይለዋል፣ ወይስ፦ የፍርድ አምላክ ወዴት አለ? በማለታችሁ ነው።'),
  ('94c62966-9fb3-5fe8-ad83-4f9e4599823c', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 1, 1, 'እነሆ፥ መልእክተኛዬን እልካለሁ፥ መንገድንም በፊቴ ያስተካክላል፣ እናንተም የምትፈልጉት ጌታ በድንገት ወደ መቅደሱ ይመጣል፣ የምትወዱትም የቃል ኪዳን መልእክተኛ፥ እነሆ፥ ይመጣል፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('3794d4d1-92aa-5403-a446-cf2616b37043', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 2, 2, 'ነገር ግን እርሱ እንደ አንጥረኛ እሳትና እንደ አጣቢ ሳሙና ነውና የሚመጣበትን ቀን መታገሥ የሚችል ማን ነው? እርሱስ በተገለጠ ጊዜ የሚቆም ማን ነው?'),
  ('a08582fd-5548-5959-ae65-330f57836d23', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 3, 3, 'እርሱም ብርን እንደሚያነጥርና እንደሚያጠራ ሰው ይቀመጣል፥ የሌዊንም ልጆች ያጠራል፥ እንደ ወርቅና እንደ ብርም ያነጥራቸዋል፣ እነርሱም ለእግዚአብሔር በጽድቅ ቍርባንን የሚያቀርቡ ይሆናሉ።'),
  ('ece41aba-1dab-5dd2-a7dc-85e39f891e73', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 4, 4, 'እግዚአብሔርም እንደ ዱሮው ዘመንና እንደ ቀደሙት ዓመታት በይሁዳና በኢየሩሳሌም ቍርባን ደስ ይለዋል።'),
  ('7fa7a3cb-158f-551a-ad69-f5e441b01cb6', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 5, 5, 'ለፍርድ ወደ እናንተ እቀርባለሁ፣ በመተተኞችና በአመንዝሮች፥ በሐሰትም በሚምሉ፥ የምንደኛውን ደመመዝ በሚከለክሉ፥ መበለቲቱንና ድሀ አደጉን በሚያስጨንቁ፥ የመጻተኛውንም ፍርድ በሚያጣምሙ፥ እኔንም በማይፈሩ ላይ ፈጣን ምስክር እሆንባቸዋለሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('423deb19-31d0-5e4e-ab0c-c94d4cb5d1dd', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 6, 6, 'እኔ እግዚአብሔር አልለወጥም፣ እናንተ የያዕቆብ ልጆች ሆይ፥ ስለዚህ የጠፋችሁ አይደላችሁም።'),
  ('e642668a-3ec8-5209-ac4d-c987c3c5c381', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 7, 7, 'ከአባቶቻችሁ ዘመን ጀምሮ ከሥርዓቴ ፈቀቅ ብላችኋል፥ እርስዋንም አልጠበቃችሁም። ወደ እኔ ተመለሱ፥ እኔም ወደ እናንተ እመለሳለሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር። እናንተ ግን፦ የምንመለሰው በምንድር ነው? ብላችኋል።'),
  ('4683a969-3141-56db-afd2-4520ed0d538b', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 8, 8, 'ሰው እግዚአብሔርን ይሰርቃልን? እናንተ ግን እኔን ሰርቃችኋል። እናንተም፦ የሰረቅንህ በምንድር ነው? ብላችኋል። በአሥራትና በበኵራት ነው።'),
  ('5f2df09b-79d5-5193-ad32-fee899f69e9f', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 9, 9, 'እናንተ፥ ይህ ሕዝብ ሁሉ፥ እኔን ሰርቃችኋልና በእርግማን ርጉሞች ናችሁ።'),
  ('1318620c-274f-558b-a624-21a1cde803b4', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 10, 10, 'በቤቴ ውስጥ መብል እንዲሆን አሥራቱን ሁሉ ወደ ጎተራ አግቡ፣ የሰማይንም መስኮት ባልከፍትላችሁ፥ በረከትንም አትረፍርፌ ባላፈስስላችሁ በዚህ ፈትኑኝ፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('9f81c28d-ca73-5695-afcf-2d5f6d175c09', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 11, 11, 'ስለ እናንተ ነቀዙን እገሥጻለሁ፥ የምድራችሁንም ፍሬ አያጠፋም፣ በእርሻችሁም ያለው ወይን ፍሬውን አያረግፍም፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('1f38a8e0-1394-5cf7-a143-6436d0433ed5', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 12, 12, 'የተድላ ምድር ትሆናላችሁና አሕዛብ ሁሉ ብፁዓን ብለው ይጠሩአችኋል፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('a3ac4729-a7c9-5558-aa69-1837afe8b861', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 13, 13, 'ቃላችሁ በእኔ ላይ ድፍረት ሆኖአል፥ ይላል እግዚአብሔር። እናንተ ግን፦ በአንተ ላይ ደፍረን የተናገርነው በምንድር ነው? ብላችኋል።'),
  ('67342acc-fe3d-51b5-a34f-21f3bb4db65b', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 14, 14, 'እናንተም፦ እግዚአብሔርን ማገልገል ከንቱ ነው፣ ትእዛዙንስ በመጠበቅ፥ በሠራዊት ጌታ በእግዚአብሔር ፊት ኀዘንተኞች ሆነን በመሄድ ምን ይረባናል?'),
  ('5b898ada-397a-52ed-a135-f6cff1406628', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 15, 15, 'አሁንም የሚታበዩትን ሰዎች ብፁዓን ብለን እንጠራቸዋለን፣ ክፉንም የሚሠሩ ጸንተዋል እግዚአብሔርንም ይፈታተናሉ፥ ያመልጣሉም ብላችኋል።'),
  ('1018c3a8-f995-5b60-af06-97d626af850f', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 16, 16, 'የዚያን ጊዜ እግዚአብሔርን የሚፈሩ እርስ በእርሳቸው ተነጋገሩ፣ እግዚአብሔርም አደመጠ፥ ሰማም፥ እግዚአብሔርንም ለሚፈሩ ስሙንም ለሚያስቡ የመታሰቢያ መጽሐፍ በፊቱ ተጻፈ።'),
  ('74f81abd-1ec6-58cb-a615-2e38bfe206ad', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 17, 17, 'እኔ በምሠራበት ቀን እነርሱ የእኔ ገንዘብ ይሆናሉ፥ ይላል የሠራዊት ጌታ እግዚአብሔር፣ ሰውም የሚያገለግለውን ልጁን እንደሚምር፥ እንዲሁ እምራቸዋለሁ።'),
  ('8f5ad920-fd5c-5405-a4db-1f0faedc9658', '6b0f5580-cdea-5e43-a7d8-32fd41e1ef76', '56792b12-49ab-5c08-a567-9d8e9ec43437', 18, 18, 'ተመልሳችሁም በጻድቁና በኃጢአተኛው መካከል፥ ለእግዚአብሔር በሚገዛውና በማይገዛው መካከል ትለያላችሁ።'),
  ('53cf230f-d01c-570b-a024-6a4259cfcc01', 'e3e107ab-f654-5008-acf4-7060e79a4559', '76fca2f6-af9e-57bb-ab80-0e5ffcf07307', 1, 1, 'እነሆ፥ እንደ ምድጃ እሳት የሚነድድ ቀን ይመጣል፣ ትዕቢተኞችና ኃጢአትን የሚሠሩ ሁሉ ገለባ ይሆናሉ፣ የሚመጣውም ቀን ያቃጥላቸዋል፥ ሥርንና ቅርንጫፍንም አይተውላቸውም፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('0a754433-381d-56cf-a928-9085e97e1bf6', 'e3e107ab-f654-5008-acf4-7060e79a4559', '76fca2f6-af9e-57bb-ab80-0e5ffcf07307', 2, 2, 'ነገር ግን ስሜን ለምትፈሩት ለእናንተ የጽድቅ ፀሐይ ትወጣላችኋለች፥ ፈውስም በክንፎችዋ ውስጥ ይሆናል፣ እናንተም ትወጣላችሁ፥ እንደ ሰባም እምቦሳ ትፈነጫላችሁ።'),
  ('a3828d77-c9c7-5531-a0cf-46151efbe926', 'e3e107ab-f654-5008-acf4-7060e79a4559', '76fca2f6-af9e-57bb-ab80-0e5ffcf07307', 3, 3, 'በምሠራበት ቀን በደለኞች ከእግራችሁ ጫማ በታች አመድ ይሆናሉና እናንተ ትረግጡአቸዋላችሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('4cf7802a-ebe8-5f4a-a1a3-10d0a16a6374', 'e3e107ab-f654-5008-acf4-7060e79a4559', '76fca2f6-af9e-57bb-ab80-0e5ffcf07307', 4, 4, 'ለእስራኤል ሁሉ ሥርዓትንና ፍርድን አድርጌ በኮሬብ ያዘዝሁትን የባሪያዬን የሙሴን ሕግ አስቡ።'),
  ('c19b7f32-e951-5b9c-acdd-ff0a1d9a7c0a', 'e3e107ab-f654-5008-acf4-7060e79a4559', '76fca2f6-af9e-57bb-ab80-0e5ffcf07307', 5, 5, 'እነሆ፥ ታላቁና የሚያስፈራው የእግዚአብሔር ቀን ሳይመጣ ነቢዩን ኤልያስን እልክላችኋለሁ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('fa1cee46-ba57-5cfb-a053-5404ad9f569c', 'e3e107ab-f654-5008-acf4-7060e79a4559', '76fca2f6-af9e-57bb-ab80-0e5ffcf07307', 6, 6, 'መጥቼም ምድርን በእርግማን እንዳልመታ እርሱ የአባቶችን ልብ ወደ ልጆች፥ የልጆችንም ልብ ወደ አባቶች ይመልሳል።'),
  ('025d4aed-a240-5a35-af94-b38ec40416e0', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 1, 1, 'የዳዊት ልጅ የአብርሃም ልጅ የኢየሱስ ክርስቶስ ትውልድ መጽሐፍ።'),
  ('4e349341-7c0a-57f9-a652-b08a24ea620a', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 2, 2, 'አብርሃም ይስሐቅን ወለደ፤ ይስሐቅም ያዕቆብን ወለደ፤ ያዕቆብም ይሁዳንና ወንድሞቹን ወለደ፤'),
  ('c8c6888a-3064-5bd8-af44-cb978d7e7d44', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 3, 3, 'ይሁዳም ከትዕማር ፋሬስንና ዛራን ወለደ፤ ፋሬስም ኤስሮምን ወለደ፤'),
  ('a47eede8-3288-5c59-ace4-adba3c7a64c2', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 4, 4, 'ኤስሮምም አራምን ወለደ፤ አራምም አሚናዳብን ወለደ፤ አሚናዳብም ነአሶንን ወለደ፤ ነአሶንም ሰልሞንን ወለደ፤'),
  ('6982073c-ef22-51ee-a361-7245b4dbde7d', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 5, 5, 'ሰልሞንም ከራኬብ ቦኤዝን ወለደ፤ ቦኤዝም ከሩት ኢዮቤድን ወለደ፤ ኢዮቤድም እሴይን ወለደ፤'),
  ('e7516d85-1632-5b0e-a3d2-358a4d2a8993', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 6, 6, 'እሴይም ንጉሥ ዳዊትን ወለደ፤ ንጉሥ ዳዊትም ከኦርዮ ሚስት ሰሎሞንን ወለደ።'),
  ('ce676052-424c-5b2c-a3c6-304fdf694d04', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 7, 7, 'ሰሎሞንም ሮብዓምን ወለደ፤ ሮብዓምም አብያን ወለደ፤ አብያም አሣፍን ወለደ፤'),
  ('57ecf345-6967-5e3e-a189-dc5362e8fea9', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 8, 8, 'አሣፍም ኢዮሣፍጥን ወለደ፤ ኢዮሣፍጥም ኢዮራምን ወለደ፤ ኢዮራምም ዖዝያንን ወለደ፤'),
  ('a0094522-c3d2-5ae7-a147-6085bc2171d8', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 9, 9, 'ዖዝያንም ኢዮአታምን ወለደ፤ ኢዮአታምም አካዝን ወለደ፤'),
  ('88791c33-10c7-5c2e-aef1-950d6ae8c7fa', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 10, 10, 'አካዝም ሕዝቅያስን ወለደ፤ ሕዝቅያስም ምናሴን ወለደ፤ ምናሴም አሞፅን ወለደ፤'),
  ('12d83a51-a614-55c3-ab0d-d25df01b0d6e', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 11, 11, 'አሞፅም ኢዮስያስን ወለደ፤ ኢዮስያስም በባቢሎን ምርኮ ጊዜ ኢኮንያንንና ወንድሞቹን ወለደ።'),
  ('b2bb3be6-6741-5b9d-a84d-c727355eb16e', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 12, 12, 'ከባቢሎንም ምርኮ በኋላ ኢኮንያን ሰላትያልን ወለደ፤ ሰላትያልም ዘሩባቤልን ወለደ፤'),
  ('2484a150-5241-556c-a57b-f6749b9b2871', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 13, 13, 'ዘሩባቤልም አብዩድን ወለደ፤ አብዩድም ኤልያቄምን ወለደ፤ ኤልያቄምም አዛርን ወለደ፤'),
  ('2d161ea9-3dfe-5da8-aa34-db57dfb2a5a7', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 14, 14, 'አዛርም ሳዶቅን ወለደ፤ ሳዶቅም አኪምን ወለደ፤ አኪምም ኤልዩድን ወለደ፤'),
  ('118ca169-4666-5d78-a463-c9860a176bce', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 15, 15, 'ኤልዩድም አልዓዛርን ወለደ፤ አልዓዛርም ማታንን ወለደ፤ ማታንም ያዕቆብን ወለደ፤'),
  ('84eebc38-9123-5f96-aa5d-7215205b9672', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 16, 16, 'ያዕቆብም ክርስቶስ የተባለውን ኢየሱስን የወለደች የማርያምን እጮኛ ዮሴፍን ወለደ።'),
  ('1f7a35e1-7864-5893-a7d8-099af422357e', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '342b87ba-633d-5cbf-a59b-767149b7cb53', 17, 17, 'እንግዲህ ትውልድ ሁሉ ከአብርሃም እስከ ዳዊት አሥራ አራት ትውልድ፥ ከዳዊትም እስከ ባቢሎን ምርኮ አሥራ አራት ትውልድ፥ ከባቢሎንም ምርኮ እስከ ክርስቶስ አሥራ አራት ትውልድ ነው።'),
  ('1bf2a32f-b069-5b29-a91a-ce361d372629', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '212bbde2-86f3-5c51-a94c-95c79a0d7e76', 1, 18, 'የኢየሱስ ክርስቶስም ልደት እንዲህ ነበረ። እናቱ ማርያም ለዮሴፍ በታጨች ጊዜ ሳይገናኙ ከመንፈስ ቅዱስ ፀንሳ ተገኘች።'),
  ('358e46a3-6f5c-56af-aff3-c65bbebdb963', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '212bbde2-86f3-5c51-a94c-95c79a0d7e76', 2, 19, 'እጮኛዋ ዮሴፍም ጻድቅ ሆኖ ሊገልጣት ስላልወደደ በስውር ሊተዋት አሰበ።'),
  ('c200e8d4-a7bc-5b78-a06c-d6fdfb90740c', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '212bbde2-86f3-5c51-a94c-95c79a0d7e76', 3, 20, 'እርሱ ግን ይህን ሲያስብ፥ እነሆ የጌታ መልአክ በሕልም ታየው፤ እንዲህም አለ “የዳዊት ልጅ ዮሴፍ ሆይ! ከእርስዋ የተፀነሰው ከመንፈስ ቅዱስ ነውና እጮኛህን ማርያምን ለመውሰድ አትፍራ።'),
  ('657c04e4-b91d-5eff-af79-2846deeb3df2', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '212bbde2-86f3-5c51-a94c-95c79a0d7e76', 4, 21, 'ልጅም ትወልዳለች፤ እርሱ ሕዝቡን ከኀጢአታቸው ያድናቸዋልና ስሙን ኢየሱስ ትለዋለህ።”'),
  ('f0cdbd43-aa6e-520f-a064-1d7a3a4a1cfc', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '212bbde2-86f3-5c51-a94c-95c79a0d7e76', 5, 22, 'በነቢይ ከጌታ ዘንድ፥'),
  ('dfdcf0a1-8e24-5be4-a4f2-7152aa2be791', '4ea96372-64d4-5e86-a7af-b520ff7bb027', '212bbde2-86f3-5c51-a94c-95c79a0d7e76', 6, 23, '“እነሆ፥ ድንግል ትፀንሳለች፤ ልጅም ትወልዳለች፤'),
  ('449e879d-b853-5e9f-adb9-7df93817d391', '16137722-c420-5a2d-a7a0-e60e7e987334', '2b39e1ae-f3a5-5a41-a647-461df7493b08', 1, 1, 'ኢየሱስም በይሁዳ ቤተ ልሔም በንጉሡ በሄሮድስ ዘመን በተወለደ ጊዜ፥ እነሆ፥ ሰብአ ሰገል “የተወለደው የአይሁድ ንጉሥ ወዴት ነው? ኮከቡን በምሥራቅ አይተን ልንሰግድለት መጥተናልና” እያሉ ከምሥራቅ ወደ ኢየሩሳሌም መጡ።'),
  ('b82300ce-0113-55b2-a6c1-4eb64368fd40', '16137722-c420-5a2d-a7a0-e60e7e987334', '2b39e1ae-f3a5-5a41-a647-461df7493b08', 2, 3, 'ንጉሡ ሄሮድስም ሰምቶ ደነገጠ፤ ኢየሩሳሌምም ሁሉ ከእርሱ ጋር፤'),
  ('2f2489c5-9e05-516c-a953-3756f55e36e7', '16137722-c420-5a2d-a7a0-e60e7e987334', '2b39e1ae-f3a5-5a41-a647-461df7493b08', 3, 4, 'የካህናትንም አለቆች የሕዝቡንም ጻፎች ሁሉ ሰብስቦ ክርስቶስ ወዴት እንዲወለድ ጠየቃቸው።'),
  ('386e6970-5d76-5091-a397-88153b58abc5', '16137722-c420-5a2d-a7a0-e60e7e987334', '2b39e1ae-f3a5-5a41-a647-461df7493b08', 4, 5, 'እነርሱም'),
  ('b5aecc27-2f2c-5126-a993-b41d8e0ba21a', '16137722-c420-5a2d-a7a0-e60e7e987334', '2b39e1ae-f3a5-5a41-a647-461df7493b08', 5, 7, 'ከዚህ በኋላ ሄሮድስ ሰብአ ሰገልን በስውር ጠርቶ ኮከቡ የታየበትን ዘመን ከእነርሱ በጥንቃቄ ተረዳ።'),
  ('a883b88c-30b1-51d3-a9c1-13a46b0f0eb0', '16137722-c420-5a2d-a7a0-e60e7e987334', '2b39e1ae-f3a5-5a41-a647-461df7493b08', 6, 8, 'ወደ ቤተ ልሔምም እነርሱን ሰድዶ “ሂዱ፤ ስለ ሕፃኑ በጥንቃቄ መርምሩ፤ ባገኛችሁትም ጊዜ እኔ ደግሞ መጥቼ እንድሰግድለት ንገሩኝ” አላቸው።'),
  ('3a03e572-000c-54c6-abfc-d8289e84b5b5', '16137722-c420-5a2d-a7a0-e60e7e987334', '2b39e1ae-f3a5-5a41-a647-461df7493b08', 7, 9, 'እነርሱም ንጉሡን ሰምተው ሄዱ፤ እነሆም፥ በምሥራቅ ያዩት ኮከብ ሕፃኑ ባለበት ላይ መጥቶ እስኪቆም ድረስ ይመራቸው ነበር።'),
  ('dc08fa01-5764-5953-a583-2d52e0958ac8', '16137722-c420-5a2d-a7a0-e60e7e987334', '2b39e1ae-f3a5-5a41-a647-461df7493b08', 8, 10, 'ኮከቡንም ባዩ ጊዜ በታላቅ ደስታ እጅግ ደስ አላቸው።'),
  ('7dff39c9-3937-5be9-a149-6940f17f36f2', '16137722-c420-5a2d-a7a0-e60e7e987334', '2b39e1ae-f3a5-5a41-a647-461df7493b08', 9, 11, 'ወደ ቤትም ገብተው ሕፃኑን ከእናቱ ከማርያም ጋር አዩት፤ ወድቀውም ሰገዱለት፤ ሣጥኖቻቸውንም ከፍተው እጅ መንሻ ወርቅና ዕጣን ከርቤም አቀረቡለት።'),
  ('46a1e40f-1cf0-5ca2-a94f-ebe98afa9fbc', '16137722-c420-5a2d-a7a0-e60e7e987334', '2b39e1ae-f3a5-5a41-a647-461df7493b08', 10, 12, 'ወደ ሄሮድስም እንዳይመለሱ በሕልም ተረድተው በሌላ መንገድ ወደ አገራቸው ሄዱ።'),
  ('b6343a6e-0756-5cc2-a9cb-fa18dcb2cc86', '16137722-c420-5a2d-a7a0-e60e7e987334', '4c598d96-c802-50ce-a873-ab87e20f97c1', 1, 13, 'እነርሱም ከሄዱ በኋላ እነሆ፥ የጌታ መልአክ በሕልም ለዮሴፍ ታይቶ “ሄሮድስ ሕፃኑን ሊገድለው ይፈልገዋልና ተነሣ፤ ሕፃኑንና እናቱንም ይዘህ ወደ ግብፅ ሽሽ፤ እስክነግርህም ድረስ በዚያ ተቀመጥ” አለው።'),
  ('52465c38-4795-54a6-a275-5ca07f5f677e', '16137722-c420-5a2d-a7a0-e60e7e987334', '4c598d96-c802-50ce-a873-ab87e20f97c1', 2, 14, 'እርሱም ተነሥቶ ሕፃኑንና እናቱን በሌሊት ያዘና ከጌታ ዘንድ በነቢይ “ልጄን ከግብጽ ጠራሁት” የተባለው እንዲፈጸም ወደ ግብጽ ሄደ፤ ሄሮድስም እስኪሞት ድረስ በዚያ ኖረ።'),
  ('c636350c-14d8-56e5-a089-e91a5dc18637', '16137722-c420-5a2d-a7a0-e60e7e987334', '43b9b779-5903-5b65-a1e1-6c8741c15aa1', 1, 16, 'ከዚህ በኋላ ሄሮድስ ሰብአ ሰገል እንደ ተሣለቁበት ባየ ጊዜ እጅግ ተቆጣና ልኮ ከሰብአ ሰገል እንደ ተረዳው ዘመን በቤተ ልሔምና በአውራጃዋ የነበሩትን፥ ሁለት ዓመት የሆናቸውን ከዚያም የሚያንሱትን ሕፃናት ሁሉ አስገደለ።'),
  ('fafb3ba5-963f-5fa2-a384-022d1809cd69', '16137722-c420-5a2d-a7a0-e60e7e987334', '43b9b779-5903-5b65-a1e1-6c8741c15aa1', 2, 17, 'ያን ጊዜ እንዲህ ሲል በነቢዩ በኤርምያስ የተነገረው ተፈጸመ፤'),
  ('8a1e7e4d-c99f-537a-ae4b-74a4c6fa7d59', '16137722-c420-5a2d-a7a0-e60e7e987334', '43b9b779-5903-5b65-a1e1-6c8741c15aa1', 3, 18, '“ድምፅ በራማ ተሰማ፤ ልቅሶና ብዙ ዋይታ፤'),
  ('1e7ad0d5-ba2b-5c05-a2fa-12199d84e017', '16137722-c420-5a2d-a7a0-e60e7e987334', '19e6dc9a-f256-5476-ae77-aea1a6fc1615', 1, 19, 'ሄሮድስም ከሞተ በኋላ፥ እነሆ፥ የጌታ መልአክ በግብጽ ለዮሴፍ በሕልም ታይቶ'),
  ('a8aa3e63-8c1c-5ba2-a2c3-f11569c18b9c', '16137722-c420-5a2d-a7a0-e60e7e987334', '19e6dc9a-f256-5476-ae77-aea1a6fc1615', 2, 20, '“የሕፃኑን ነፍስ የፈለጉት ሞተዋልና ተነሣ፤ ሕፃኑን እናቱንም ይዘህ ወደ እስራኤል አገር ሂድ” አለ።'),
  ('2caedbd5-0412-58d6-a808-fb419a5b4686', '16137722-c420-5a2d-a7a0-e60e7e987334', '19e6dc9a-f256-5476-ae77-aea1a6fc1615', 3, 21, 'እርሱም ተነሥቶ ሕፃኑንና እናቱን ያዘና ወደ እስራኤል አገር ገባ።'),
  ('146f2078-cda7-59ec-a5b5-1029c6ed078e', '16137722-c420-5a2d-a7a0-e60e7e987334', '19e6dc9a-f256-5476-ae77-aea1a6fc1615', 4, 22, 'በአባቱም በሄሮድስ ፈንታ አርኬላዎስ በይሁዳ እንደ ነገሠ በሰማ ጊዜ፥ ወደዚያ መሄድን ፈራ፤ በሕልምም ተረድቶ ወደ ገሊላ አገር ሄደ፤'),
  ('b7223716-7feb-52bc-ad1c-197ab3cb1d13', '16137722-c420-5a2d-a7a0-e60e7e987334', '19e6dc9a-f256-5476-ae77-aea1a6fc1615', 5, 23, 'በነቢያት “ናዝራዊ ይባላል” የተባለው ይፈጸም ዘንድ፥ ናዝሬት ወደምትባል ከተማ መጥቶ ኖረ።'),
  ('73f8e70d-8345-5c52-a8bc-ae23ebdf2dcd', '3f600272-c910-527a-a2f6-c80106dfa035', 'a5f88526-86fd-57b9-a094-3770869da53e', 1, 1, 'በዚያም ወራት መጥምቁ ዮሐንስ “መንግሥተ ሰማያት ቀርባለችና ንስሐ ግቡ” ብሎ በይሁዳ ምድረ በዳ እየሰበከ መጣ።'),
  ('3fd3a143-afc4-5e92-a7a5-e95ccca366bc', '3f600272-c910-527a-a2f6-c80106dfa035', 'a5f88526-86fd-57b9-a094-3770869da53e', 2, 3, 'በነቢዩ በኢሳይያስ'),
  ('86fafe47-a305-5031-adf3-935835a06335', '3f600272-c910-527a-a2f6-c80106dfa035', 'a5f88526-86fd-57b9-a094-3770869da53e', 3, 7, 'ዳሩ ግን ከፈሪሳውያንና ከሰዱቃውያን ብዙዎች ወደ ጥምቀቱ ሲመጡ ባየ ጊዜ፥ እንዲህ አላቸው “እናንተ የእፉኝት ልጆች፥ ከሚመጣው ቍጣ እንድትሸሹ ማን አመለከታችሁ?'),
  ('a4a6b8d5-1699-58c2-a6af-1a75892dbf3e', '3f600272-c910-527a-a2f6-c80106dfa035', 'a5f88526-86fd-57b9-a094-3770869da53e', 4, 8, 'እንግዲህ ለንስሐ የሚገባ ፍሬ አድርጉ፤'),
  ('a48c0613-d605-5d0d-a9bc-8eba33aba076', '3f600272-c910-527a-a2f6-c80106dfa035', 'a5f88526-86fd-57b9-a094-3770869da53e', 5, 9, 'በልባችሁም ‘አብርሃም አባት አለን’ እንደምትሉ አይምሰላችሁ፤ እላችኋለሁና ከነዚህ ድንጋዮች ለአብርሃም ልጆች ሊያስነሣለት እግዚአብሔር ይችላል።'),
  ('5e4f92c6-2039-57ce-ac92-7a91c4d191d9', '3f600272-c910-527a-a2f6-c80106dfa035', 'a5f88526-86fd-57b9-a094-3770869da53e', 6, 10, 'አሁንስ ምሳር በዛፎች ሥር ተቀምጦአል፤ እንግዲህ መልካም ፍሬ የማያደርግ ዛፍ ሁሉ ይቍኦረጣል ወደ እሳትም ይጣላል።'),
  ('e80ded92-01b9-548f-ac8f-3dacc332ab90', '3f600272-c910-527a-a2f6-c80106dfa035', 'a5f88526-86fd-57b9-a094-3770869da53e', 7, 11, 'እኔስ “ለንስሐ በውሃ አጠምቃችኋለሁ፤ ጫማውን እሸከም ዘንድ የማይገባኝ ከእኔ በኋላ የሚመጣው ግን ከእኔ ይልቅ ይበረታል፤ እርሱ በመንፈስ ቅዱስ በእሳትም ያጠምቃችኋል፤'),
  ('713d88a8-16f4-5233-a85d-e6f0aeee83f4', '3f600272-c910-527a-a2f6-c80106dfa035', 'a5f88526-86fd-57b9-a094-3770869da53e', 8, 12, 'መንሹም በእጁ ነው፤ አውድማውንም ፈጽሞ ያጠራል፤ ስንዴውንም በጎተራው ይከታል፤ ገለባውን ግን በማይጠፋ እሳት ያቃጥለዋል።”'),
  ('5fc148e9-1864-50c7-ae3e-896a1f2e45f3', '3f600272-c910-527a-a2f6-c80106dfa035', '32e69cd4-73ef-5f49-adc9-c3b2e7fd48ea', 1, 13, 'ያን ጊዜ ኢየሱስ በዮሐንስ ሊጠመቅ ከገሊላ ወደ ዮርዳኖስ መጣ።'),
  ('29f0d63a-2f68-53d8-ae5c-e495d79c5d53', '3f600272-c910-527a-a2f6-c80106dfa035', '32e69cd4-73ef-5f49-adc9-c3b2e7fd48ea', 2, 14, 'ዮሐንስ ግን “እኔ በአንተ ልጠመቅ ያስፈልገኛል፤ አንተም ወደ እኔ ትመጣለህን?” ብሎ ይከለክለው ነበር።'),
  ('880232f6-df64-5e28-a166-fd977869a217', '3f600272-c910-527a-a2f6-c80106dfa035', '32e69cd4-73ef-5f49-adc9-c3b2e7fd48ea', 3, 15, 'ኢየሱስም መልሶ “አሁንስ ፍቀድልኝ፤ እንዲህ ጽድቅን ሁሉ መፈጸም ይገባናልና” አለው። ያን ጊዜ ፈቀደለት።'),
  ('96a303b5-3552-58fa-ac29-549ac6f75182', '3f600272-c910-527a-a2f6-c80106dfa035', '32e69cd4-73ef-5f49-adc9-c3b2e7fd48ea', 4, 16, 'ኢየሱስም ከተጠመቀ በኋላ ወዲያው ከውኀ ወጣ፤ እነሆም፥ ሰማያት ተከፈቱ፤ የእግዚአብሔርም መንፈስ እንደ ርግብ ሲወርድ በእርሱ ላይም ሲመጣ አየ፤'),
  ('7ecb9acb-1544-57bf-a0fa-11e4fd91fb27', '3f600272-c910-527a-a2f6-c80106dfa035', '32e69cd4-73ef-5f49-adc9-c3b2e7fd48ea', 5, 17, 'እነሆም፥ ድምፅ ከሰማያት መጥቶ “በእርሱ ደስ የሚለኝ የምወደው ልጄ ይህ ነው” አለ።'),
  ('85a5638e-bbe8-588a-a9db-0fa1afa7db2b', '53220e5f-50d7-5217-af4d-8e6301c92db0', '772eb7fd-daaf-5e7f-a8ae-83f5d8cf66af', 1, 1, 'ከዚያ ወዲያ ኢየሱስ ከዲያብሎስ ይፈተን ዘንድ መንፈስ ወደ ምድረ በዳ ወሰደው።'),
  ('4bea9ee5-f712-5198-aaaf-556708dea030', '53220e5f-50d7-5217-af4d-8e6301c92db0', '772eb7fd-daaf-5e7f-a8ae-83f5d8cf66af', 2, 2, 'አርባ ቀንና አርባ ሌሊትም ከጦመ በኋላ ተራበ።'),
  ('b9f7a483-48f5-5d78-a4b6-f749737d5e1e', '53220e5f-50d7-5217-af4d-8e6301c92db0', '772eb7fd-daaf-5e7f-a8ae-83f5d8cf66af', 3, 3, 'ፈታኝም ቀርቦ “የእግዚአብሔር ልጅ ከሆንህ፥ እነዚህ ድንጋዮች እንጀራ እንዲሆኑ በል!” አለው።'),
  ('24c462c9-2951-57dc-adc0-a8354a4efba8', '53220e5f-50d7-5217-af4d-8e6301c92db0', '772eb7fd-daaf-5e7f-a8ae-83f5d8cf66af', 4, 4, 'እርሱም መልሶ “ ‘ሰው ከእግዚአብሔር አፍ በሚወጣ ቃል ሁሉ እንጂ በእንጀራ ብቻ አይኖርም’ ተብሎ ተጽፎአል” አለው።'),
  ('17e6c72a-7ffc-5f5a-ab49-b2b27b81c618', '53220e5f-50d7-5217-af4d-8e6301c92db0', '772eb7fd-daaf-5e7f-a8ae-83f5d8cf66af', 5, 5, 'ከዚህ በኋላ ዲያቢሎስ ወደ ቅድስት ከተማ ወሰደውና እርሱን በመቅደስ ጫፍ ላይ አቁሞ'),
  ('93992b26-da86-50ba-abd0-59152bf558e8', '53220e5f-50d7-5217-af4d-8e6301c92db0', '772eb7fd-daaf-5e7f-a8ae-83f5d8cf66af', 6, 6, '“ ‘መላእክቱን ስለ አንተ ያዝልሃል፤'),
  ('d1176859-38d3-5176-a439-6a68dd5859f6', '53220e5f-50d7-5217-af4d-8e6301c92db0', '97a4195c-e986-521e-a454-156bf3385cfd', 1, 12, 'ኢየሱስም ዮሐንስ አልፎ እንደ ተሰጠ በሰማ ጊዜ ወደ ገሊላ ፈቀቅ ብሎ ሄደ።'),
  ('66ee1998-9380-5de2-a7d5-4537402597fd', '53220e5f-50d7-5217-af4d-8e6301c92db0', '97a4195c-e986-521e-a454-156bf3385cfd', 2, 13, 'ናዝሬትንም ትቶ በዛብሎንና በንፍታሌም አገር በባሕር አጠገብ ወደ አለችው ወደ ቅፍርናሆም መጥቶ ኖረ።'),
  ('04f75e13-72d2-5cea-a592-cfc0c48d6c79', '53220e5f-50d7-5217-af4d-8e6301c92db0', '97a4195c-e986-521e-a454-156bf3385cfd', 3, 14, 'በነቢዩም በኢሳይያስ እንዲህ የተባለው ይፈጸም ዘንድ ይህ ሆነ፤'),
  ('371c46d4-5e60-5d12-ae23-2c2e23312ae7', '53220e5f-50d7-5217-af4d-8e6301c92db0', '97a4195c-e986-521e-a454-156bf3385cfd', 4, 15, 'ምድርና የንፍታሌም ምድር፥'),
  ('d12a9fd4-c791-5477-a42c-efae2eb5c939', '53220e5f-50d7-5217-af4d-8e6301c92db0', '97a4195c-e986-521e-a454-156bf3385cfd', 5, 16, 'ቀመጠው ሕዝብ ታላቅ ብርሃን አየ፤'),
  ('41a3777a-e41c-5858-a08d-bca55850fbed', '53220e5f-50d7-5217-af4d-8e6301c92db0', 'a1092919-9c5c-589d-a387-d428c0e4af9b', 1, 18, 'በገሊላ ባሕር አጠገብ ሲመላለስም ሁለት ወንድማማች ጴጥሮስ የሚሉትን ስምዖንን ወንድሙንም እንድርያስን መረባቸውን ወደ ባሕር ሲጥሉ አየ፤ ዓሣ አጥማጆች ነበሩና።'),
  ('9a1fb751-af65-5f90-a534-4e5b759dc409', '53220e5f-50d7-5217-af4d-8e6301c92db0', 'a1092919-9c5c-589d-a387-d428c0e4af9b', 2, 19, 'እርሱም “በኋላዬ ኑ፤ ሰዎችንም አጥማጆች እንድትሆኑ አደርጋችኋለሁ” አላቸው።'),
  ('c791a53e-52a1-5910-aeb5-4ca0a9e59656', '53220e5f-50d7-5217-af4d-8e6301c92db0', 'a1092919-9c5c-589d-a387-d428c0e4af9b', 3, 20, 'ወዲያውም መረባቸውን ትተው ተከተሉት።'),
  ('b47fe7d7-51f2-5eb6-a93e-9fd6c0cc0af9', '53220e5f-50d7-5217-af4d-8e6301c92db0', 'a1092919-9c5c-589d-a387-d428c0e4af9b', 4, 21, 'ከዚያም እልፍ ብሎ ሌሎችን ሁለት ወንድማማች የዘብዴዎስን ልጅ ያዕቆብን ወንድሙንም ዮሐንስን ከአባታቸው ከዘብዴዎስ ጋር በታንኳ መረባቸውን ሲያበጁ አየ፤ ጠራቸውም።'),
  ('e5a4790d-3af5-55e6-afd8-ca238e7b17cf', '53220e5f-50d7-5217-af4d-8e6301c92db0', 'a1092919-9c5c-589d-a387-d428c0e4af9b', 5, 22, 'እነርሱም ወዲያው ታንኳይቱንና አባታቸውን ትተው ተከተሉት።'),
  ('9d5c853a-023c-520c-a82b-8999670b8280', '53220e5f-50d7-5217-af4d-8e6301c92db0', 'f61d502a-29ba-5c8b-a894-de398a2b9146', 1, 23, 'ኢየሱስም በምኩራቦቻቸው እያስተማረ የመንግሥትንም ወንጌል እየሰበከ በሕዝብም ያለውን ደዌና ሕማም ሁሉ እየፈወሰ በገሊላ ሁሉ ይዞር ነበር።'),
  ('de29df40-c33c-537d-acbb-beda201bfd55', '53220e5f-50d7-5217-af4d-8e6301c92db0', 'f61d502a-29ba-5c8b-a894-de398a2b9146', 2, 24, 'ዝናውም ወደ ሶርያ ሁሉ ወጣ፤ በልዩ ልዩ ደዌና ሥቃይም ተይዘው የታመሙትን ሁሉ አጋንንትም ያደሩባቸውን በጨረቃም የሚነሣባቸውን ሽባዎችንም ወደ እርሱ አመጡ፤ ፈወሳቸውም።'),
  ('2cf3edce-918d-5e17-aa8b-0e527b6b109a', '53220e5f-50d7-5217-af4d-8e6301c92db0', 'f61d502a-29ba-5c8b-a894-de398a2b9146', 3, 25, 'ከገሊላም ከዐሥሩ ከተማም ከኢየሩሳሌምም ከይሁዳም ከዮርዳኖስም ማዶ ብዙ ሕዝብ ተከተሉት።'),
  ('88fe381f-1e9f-5808-a13d-1d5fddcfda95', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 1, 1, 'ሕዝቡንም አይቶ ወደ ተራራ ወጣ፤ በተቀመጠም ጊዜ ደቀ መዛሙርቱ ወደ እርሱ ቀረቡ፤'),
  ('34a012fd-71ea-5606-a644-d278d8cfacf2', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 2, 2, 'አፉንም ከፍቶ አስተማራቸው እንዲህም አለ፦'),
  ('0ef9b577-006f-5699-aabe-df11c1bac052', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 3, 3, '“ንፈስ ድሆች የሆኑ ብፁዓን ናቸው፤መንግሥተ ሰማያት የእነርሱ ናትና።'),
  ('77121659-e339-539b-a7f9-b51c341cc1ec', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 4, 4, 'የሚያዝኑ ብፁዓን ናቸው፤መፅናናትን ያገኛሉና።'),
  ('59c80943-e81e-515f-a612-cd0489dc60a7', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 5, 5, 'የዋሆች ብፁዓን ናቸው፤ምድርን ይወርሳሉና።'),
  ('481cb3ea-5c7f-5daa-af08-bac9e6b0ee4a', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 6, 6, 'ጽድቅን የሚራቡና የሚጠሙ ብፁዓን ናቸው፤ይጠግባሉና።'),
  ('3c4b0c62-a3be-53c3-aef8-b995496486d0', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 7, 7, 'የሚምሩ ብፁዓን ናቸው፤ይማራሉና።'),
  ('acc10ae3-eb9e-5826-a880-ef4aecbe8f6c', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 8, 8, 'ልበ ንጹሖች ብፁዓን ናቸው፤እግዚአብሔርን ያዩታልና።'),
  ('82ef8c51-92c4-5348-a676-2592e374187a', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 9, 9, 'የሚያስተራርቁ ብፁዓን ናቸው፤የእግዚአብሔር ልጆች ይባላሉና።'),
  ('ef2921c2-6b76-5dab-a836-ca851a4db24e', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 10, 10, 'ስለ ጽድቅ የሚሰደዱ ብፁዓን ናቸው፤መንግሥተ ሰማያት የእነርሱ ናትና።'),
  ('b397117a-5c22-5726-a8a3-52a48ba1ba9f', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 11, 11, '“ቅፉአችሁና ሲያሳድዱአችሁ በእኔም ምክንያት ክፉውን ሁሉ በውሸት ሲናገሩባችሁ ብፁዓን ናችሁ።'),
  ('c200cc60-9f62-5d3c-a9bc-9506d82d5264', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '9998d374-f1ed-5378-a2c4-736af663dee9', 12, 12, 'ዋጋችሁ በሰማያት ታላቅ ነውና ደስ ይበላችሁ፤ሐሴትም አድርጉ፤ ከእናንተ በፊት የነበሩትን ነቢያትን እንዲሁ አሳድደዋቸዋልና።”'),
  ('5c5bdfa4-d52e-55a0-a589-0aaa92b1960f', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '10ed7d41-1cb2-5f24-a813-e0f78eccb1ed', 1, 13, 'እናንተ “ድር ጨው ናችሁ፤ ጨው አልጫ ቢሆን ግን በምን ይጣፍጣል? ወደ ውጭ ተጥሎ በሰው ከመረገጥ በቀር ወደ ፊት ለምንም አይጠቅምም።'),
  ('62ec59fc-da52-50ce-adfd-9781820f5d3e', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '10ed7d41-1cb2-5f24-a813-e0f78eccb1ed', 2, 14, '“ንተ የዓለም ብርሃን ናችሁ። በተራራ ላይ ያለች ከተማ ልትሰወር አይቻላትም።'),
  ('b62f1057-2882-5751-ade7-5b6a1922cbd7', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '10ed7d41-1cb2-5f24-a813-e0f78eccb1ed', 3, 15, 'መብራትንም አብርተው ከዕንቅብ በታች አይደለም እንጂ በመቅረዙ ላይ ያኖሩታል፤በቤት ላሉት ሁሉም ያበራል።'),
  ('5643cc8e-0dde-516f-a1e8-5c471c40c56c', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '10ed7d41-1cb2-5f24-a813-e0f78eccb1ed', 4, 16, 'መልካሙን ሥራችሁን አይተው በሰማያት ያለውን አባታችሁን እንዲያከብሩ ብርሃናችሁ እንዲሁ በሰው ፊት ይብራ።'),
  ('d300bdf6-f691-5dee-aa90-b1d0ce9f97e2', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'eae7563b-e970-5ca0-ac98-856460ed4eed', 1, 17, '“ሕግንና ነቢያትን ለመሻር የመጣሁ አይምሰላችሁ፤ ልፈጽም እንጂ ለመሻር አልመጣሁም።'),
  ('510a3721-c2cb-54be-a97c-020c93270254', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'eae7563b-e970-5ca0-ac98-856460ed4eed', 2, 18, 'እውነት እላችኋለሁ፤ሰማይና ምድር እስኪያልፍ ድረስ፥ ከሕግ አንዲት የውጣ ወይም አንዲት ነጥብ ከቶ አታልፍም፤ሁሉ እስኪፈጸም ድረስ።'),
  ('f75e7eb9-a378-5a69-ac0c-9a231b666dce', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'eae7563b-e970-5ca0-ac98-856460ed4eed', 3, 19, 'እንግዲህ ከነዚህ ከሁሉ ካነሱት ትእዛዛት አንዲቱን የሚሽር ለሰውም እንዲሁ የሚያስተምር ማንም ሰው በመንግሥተ ሰማያት ከሁሉ ታናሽ ይባላል፤ የሚያደርግ ግን የሚያስተምርም ማንም ቢሆን እርሱ በመንግሥተ ሰማያት ታላቅ ይባላል።'),
  ('35df65f6-1834-5ddd-a1bf-16f01e035df3', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'eae7563b-e970-5ca0-ac98-856460ed4eed', 4, 20, 'እላችኋለሁና ጽድቃችሁ ከጻፎችና ከፈሪሳውያን ጽድቅ ካልበለጠ፥ ወደ መንግሥተ ሰማያት ከቶ አትገቡም።'),
  ('7166d2b2-2483-502a-a56b-4053f80a0897', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '7c3c7365-8ae1-59b9-a98d-fe836c23a7a8', 1, 21, '“ለቀደሙት ‘አትግደል’ እንደተባለ ሰምታችኋል፤ የገደለም ሁሉ ፍርድ ይገባዋል።'),
  ('7a45b4a9-09de-5c01-aa5d-161070def60a', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '7c3c7365-8ae1-59b9-a98d-fe836c23a7a8', 2, 22, 'እኔ ግን እላችኋለሁ፤በወንድሙ ላይ የሚቆጣ ሁሉ ፍርድ ይገባዋል፤ ወንድሙንም ጨርቃም የሚለው ሁሉ የሸንጎ ፍርድ ይገባዋል፤ ደንቆሮ የሚለውም ሁሉ የገሃነመ እሳት ፍርድ ይገባዋል።'),
  ('571b142f-e0b1-593b-a64c-74d58335a5a5', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '7c3c7365-8ae1-59b9-a98d-fe836c23a7a8', 3, 23, 'እንግዲህ መባህን በመሠዊያው ላይ ብታቀርብ፥ በዚያም ወንድምህ አንዳች በአንተ ላይ እንዳለው ብታስብ፥'),
  ('e9c09b26-9f40-5e95-a3da-772f98f4d6e3', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '7c3c7365-8ae1-59b9-a98d-fe836c23a7a8', 4, 24, 'በዚያ በመሠዊያው ፊት መባህን ትተህ ሂድ፤አስቀድመህም ከወንድምህ ጋር ታረቅ፤በኋላም መጥተህ መባህን አቅርብ።'),
  ('5ed35217-9574-5950-a779-9290525d7f77', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '7c3c7365-8ae1-59b9-a98d-fe836c23a7a8', 5, 25, 'አብረኸው በመንገድ ሳለህ ከባላጋራህ ጋር ፈጥነህ ተስማማ፤ ባላጋራ ለዳኛ እንዳይሰጥህ ዳኛም ለሎሌው፤ወደ ወህኒም ትጣላለህ፤'),
  ('d5385262-3c90-590a-a2f5-a344d664b020', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '7c3c7365-8ae1-59b9-a98d-fe836c23a7a8', 6, 26, 'እውነት እልሃለሁ፥ የመጨረሻዋን ሳንቲም እስክትከፍል ድረስ ከቶ ከዚያ አትወጣም።'),
  ('8ba37206-0300-5f0f-a6f4-e12b42f5d6ef', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '913fef40-2457-5c19-a637-ae45511529f0', 1, 27, '“ ‘አታመንዝር’ ዝንደተባለ ሰምታችኋል።'),
  ('38bf5ad4-8b91-5f59-ab76-e27a246813da', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '913fef40-2457-5c19-a637-ae45511529f0', 2, 28, 'እኔ ግን እላችኋለሁ፤ ወደ ሴት ያየ ሁሉ የተመኛትም ያን ጊዜ በልቡ ከእርስዋ ጋር አመንዝሮአል።'),
  ('84a978ab-1af3-5073-aab8-e3d44fbe94ef', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '913fef40-2457-5c19-a637-ae45511529f0', 3, 29, 'ቀኝ ዐይንህም ብታሰናክልህ አውጥተህ ከአንተ ጣላት፤ ሙሉ ሰውነትህ በገሃነም ከሚጣል ይልቅ ከአካላትህ አንድ ቢጠፋ ይሻልሃልና።'),
  ('f7b58794-9e18-5860-a915-ab74827caa63', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '913fef40-2457-5c19-a637-ae45511529f0', 4, 30, 'ቀኝ እጅህም ብታሰናክልህ ቆርጠህ ከአንተ ጣላት፤ ሙሉ ሰውነትህ በገሃነም ከሚጣል ይልቅ ከአካላትህ አንድ ቢጠፋ ይሻላልና።'),
  ('108f13c4-3524-53dc-a24e-f61b59072cdb', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'a7fa09fc-2486-5bdb-a7c9-b4ae54558a01', 1, 31, '“ ‘ሚስቱን የሚፈታት ሁሉ የፍችዋን ጽሕፈት ይስጣት’ ተባለ።'),
  ('e293382e-4539-5172-a767-07ac2e58aa9f', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'a7fa09fc-2486-5bdb-a7c9-b4ae54558a01', 2, 32, 'እኔ ግን እላችኋለሁ፥ ያለ ዝሙት ምክንያት ሚስቱን የሚፈታ ሁሉ አመንዝራ ያደርጋታል፤ የተፈታችውንም የሚያገባ ሁሉ ያመነዝራል።'),
  ('10308cbd-e292-5c10-a279-c92f0ef021d4', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'e0b145a1-7991-5cb6-a53d-6d12683a8e61', 1, 33, '“ደግሞ ለቀደሙት ‘በውሸት አትማል ነገር ግን መሐላዎችህን ለጌታ ስጥ’ እንደተባለ ሰምታችኋል።'),
  ('6179866d-2bda-5be5-ae3f-c2e0e204edec', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'e0b145a1-7991-5cb6-a53d-6d12683a8e61', 2, 34, 'እኔ ግን እላችኋለሁ፤ ከቶ አትማሉ፤ በሰማይ አይሆንም የእግዚአብሔር ዙፋን ነውና፤'),
  ('a5df6f65-c2d1-5852-a0c4-ef8cceee9a31', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'e0b145a1-7991-5cb6-a53d-6d12683a8e61', 3, 35, 'በምድርም አይሆንም የእግሩ መረገጫ ናትና፤ በኢየሩሳሌምም አይሆንም የታላቁ ንጉሥ ከተማ ናትና፤'),
  ('3926148f-690a-5f2d-a0f0-d5f8ea2dbe3d', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'e0b145a1-7991-5cb6-a53d-6d12683a8e61', 4, 36, 'በራስህም አትማል፤ አንዲቱን ጠጉር ነጭ ወይም ጥቁር ልታደርግ አትችልምና።'),
  ('34157757-e25b-57c9-ae0c-369376086c3b', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'e0b145a1-7991-5cb6-a53d-6d12683a8e61', 5, 37, 'ነገር ግን ቃላችሁ አዎን አዎን ወይም አይደለም አይደለም ይሁን፤ ከነዚህም የወጣ ከክፉው ነው።'),
  ('b117b433-6519-5c71-a700-8ae38fe69e71', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '83bbfcf4-29dd-5982-a85c-8d6d31694973', 1, 38, '“ ‘ዐይን ስለ ዐይን ጥርስም ስለ ጥርስ’ እንደ ተባለ ሰምታችኋል።'),
  ('a7cb4e11-1d81-568c-ac02-d6b8bc6a5013', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '83bbfcf4-29dd-5982-a85c-8d6d31694973', 2, 39, 'እኔ ግን እላችኋለሁ፤ ክፉውን አትቃወሙ፤ ዳሩ ግን ቀኝ ጉንጭህን በጥፊ ለሚመታህ ሁሉ ሁለተኛውን ደግሞ አዙርለት፤'),
  ('4862ce30-c0f1-554c-a2c5-545eb1e00956', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '83bbfcf4-29dd-5982-a85c-8d6d31694973', 3, 40, 'እንዲከስህም እጀ ጠባብህንም እንዲወስድ ለሚወድ መጎናጸፊያህን ደግሞ ተውለት፤'),
  ('7ae957b6-b34d-5926-a77f-6e573005e8b3', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '83bbfcf4-29dd-5982-a85c-8d6d31694973', 4, 41, 'ማንም ሰው አንድ ምዕራፍ ትሄድ ዘንድ ቢያስገድድህ ሁለተኛውን ከእርሱ ጋር ሂድ።'),
  ('fef29492-baa7-54ad-a5db-0b979bfeed69', 'ec18803a-b701-5dd7-a734-08a90190dcb6', '83bbfcf4-29dd-5982-a85c-8d6d31694973', 5, 42, 'ለሚለምንህ ስጥ፤ ከአንተም ይበደር ዘንድ ከሚወደው ፈቀቅ አትበል።'),
  ('c5f48aeb-ea18-568a-ab8a-7e638865ab85', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'eb434e7b-160d-5b4e-a3c6-fbd360e5b87b', 1, 43, '“ ‘ባልንጀራህን ውደድ ጠላትህንም ጥላ’ እንደ ተባለ ሰምታችኋል።'),
  ('6980d349-e4bb-5829-aef9-746f6be1be09', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'eb434e7b-160d-5b4e-a3c6-fbd360e5b87b', 2, 44, 'እኔ ግን እላችኋለሁ፤ በሰማያት ላለ አባታችሁ ልጆች ትሆኑ ዘንድ ጠላቶቻችሁን ውደዱ፤ የሚረግሙአችሁንም መርቁ፤ ለሚጠሉአችሁም መልካም አድርጉ፤ ስለሚያሳድዱአችሁም ጸልዩ፤ እርሱ በክፎዎችና በበጎዎች ላይ ፀሐይን ያወጣልና፤ በጻድቃንና በኃጢአተኞችም ላይ ዝናቡን ያዘንባልና።'),
  ('9d4c4fe3-0e80-58d0-a933-ca771f41e346', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'eb434e7b-160d-5b4e-a3c6-fbd360e5b87b', 3, 46, 'የሚወዱአችሁን ብትወዱ ምን ዋጋ አላችሁ? ቀራጮችስ ያንኑ ያደርጉ የለምን?'),
  ('cb6816e0-36e4-59a9-af56-a8b50f313fd6', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'eb434e7b-160d-5b4e-a3c6-fbd360e5b87b', 4, 47, 'ወንድሞቻችሁንም ብቻ እጅ ብትነሡ ምን ብልጫ ታደርጋላችሁ? አሕዛብስ ያንኑ ያደርጉ የለምን?'),
  ('59397f31-c48c-5c96-adeb-810e43a14e69', 'ec18803a-b701-5dd7-a734-08a90190dcb6', 'eb434e7b-160d-5b4e-a3c6-fbd360e5b87b', 5, 48, 'እንግዲህ የሰማዩ አባታችሁ ፍጹም እንደ ሆነ እናንተም ፍጹማን ሁኑ።'),
  ('5a18252b-9861-5b71-ac6d-83f5094f09f1', '9c0b67a5-8f57-504d-add2-b15689f08219', '753d0295-b86e-5fdb-acee-eac447a4ffa4', 1, 1, '“ለሰዎች ትታዩ ዘንድ ምጽዋታችሁን በፊታቸው እንዳታደርጉ ተጠንቀቁ፤ ያለዚያ በሰማያት ባለው አባታችሁ ዘንድ ዋጋ የላችሁም።'),
  ('e746ab82-7569-58ce-a3a8-03af6bd169e5', '9c0b67a5-8f57-504d-add2-b15689f08219', '753d0295-b86e-5fdb-acee-eac447a4ffa4', 2, 2, '“እንግዲህ ምጽዋት ስታደርግ፥ ግብዞች በሰው ዘንድ ሊከበሩ በምኩራብ በመንገድም እንደሚያደርጉ በፊትህ መለከት አታስነፋ፤ እውነት እላችኋለሁ፤ ዋጋቸውን ተቀብለዋል።'),
  ('0fb404fe-4a46-57ca-ac8d-ad8d0aac59d1', '9c0b67a5-8f57-504d-add2-b15689f08219', '753d0295-b86e-5fdb-acee-eac447a4ffa4', 3, 3, 'አንተ ግን ምጽዋት ስታደርግ ምጽዋትህ በስውር እንዲሆን ቀኝህ የምትሠራውን ግራህ አትወቅ፤ በስውር የሚያይ አባትህም በግልጥ ይከፍልሃል።'),
  ('84675aa7-b389-52e7-adba-5dc2a52639c6', '9c0b67a5-8f57-504d-add2-b15689f08219', '588398c9-c89f-5464-a500-8a37e515ebf3', 1, 5, '“ስትጸልዩም እንደ ግብዞች አትሁኑ፤ ለሰው ይታዩ ዘንድ በምኩራብና በመንገድ ማዕዘን ቆመው መጸለይን ይወዳሉና፤ እውነት እላችኋለሁ፤ ዋጋቸውን ተቀብለዋል።'),
  ('62477379-4665-564a-a0aa-981d04103ee8', '9c0b67a5-8f57-504d-add2-b15689f08219', '588398c9-c89f-5464-a500-8a37e515ebf3', 2, 6, 'አንተ ግን ስትጸልይ፥ ወደ እልፍኝህ ግባ፤ መዝጊያህንም ዘግተህ በስውር ላለው አባትህ ጸልይ፤ በስውር የሚያይ አባትህም በግልጥ ይከፍልሃል።'),
  ('2f294a45-ea47-551a-ac88-ce57301c55f8', '9c0b67a5-8f57-504d-add2-b15689f08219', '588398c9-c89f-5464-a500-8a37e515ebf3', 3, 7, '“አሕዛብም በመናገራቸው ብዛት እንዲሰሙ ይመስላቸዋልና ስትጸልዩ እንደ እነርሱ በከንቱ አትድገሙ።'),
  ('f79e4af5-68c9-50a8-a8fd-c79d76b86ec0', '9c0b67a5-8f57-504d-add2-b15689f08219', '588398c9-c89f-5464-a500-8a37e515ebf3', 4, 8, 'ስለዚህ አትምሰሉአቸው፤ ሳትለምኑት አባታችሁ የሚያስፈልጋችሁን ያውቃልና።'),
  ('edff0005-7f36-581f-a2af-90d3b144ebef', '9c0b67a5-8f57-504d-add2-b15689f08219', '588398c9-c89f-5464-a500-8a37e515ebf3', 5, 9, 'እንግዲህ እናንተስ እንዲህ ጸልዩ ‘በሰማያት የምትኖር አባታችን ሆይ!'),
  ('93a39a49-5829-5133-a9ea-fd67b99d00ea', '9c0b67a5-8f57-504d-add2-b15689f08219', '588398c9-c89f-5464-a500-8a37e515ebf3', 6, 10, 'ስምህ ይቀደስ፤ መንግሥትህ ትምጣ፤ ፈቃድህ በሰማይ እንደ ሆነች እንዲሁ በምድር ትሁን፤'),
  ('17e502a6-096e-5550-a34d-49142cf7d6bb', '9c0b67a5-8f57-504d-add2-b15689f08219', '588398c9-c89f-5464-a500-8a37e515ebf3', 7, 11, 'የዕለት እንጀራችንን ዛሬ ስጠን፤'),
  ('434e4f16-98ab-596a-ac1b-38597a0cb344', '9c0b67a5-8f57-504d-add2-b15689f08219', '588398c9-c89f-5464-a500-8a37e515ebf3', 8, 12, 'እኛም ደግሞ የበደሉንን ይቅር እንደምንል በደላችንን ይቅር በለን፤'),
  ('2e7872d9-6688-598b-a9fc-7ccf618ecb38', '9c0b67a5-8f57-504d-add2-b15689f08219', '588398c9-c89f-5464-a500-8a37e515ebf3', 9, 13, 'ከክፉም አድነን እንጂ ወደ ፈተና አታግባን፤ መንግሥት ያንተ ናትና ኃይልም ክብርም ለዘለዓለሙ፤ አሜን።’'),
  ('e14bd0fe-7107-5466-a407-0de020d68b8a', '9c0b67a5-8f57-504d-add2-b15689f08219', '588398c9-c89f-5464-a500-8a37e515ebf3', 10, 14, 'ለሰዎች ኀጢአታቸውን ይቅር ብትሉ፥ የሰማዩ አባታችሁ እናንተን ደግሞ ይቅር ይላችኋልና፤'),
  ('0587b0e3-60ac-5122-aaaa-dde61fa0d156', '9c0b67a5-8f57-504d-add2-b15689f08219', '588398c9-c89f-5464-a500-8a37e515ebf3', 11, 15, 'ለሰዎች ግን ኀጢአታቸውን ይቅር ባትሉ፥ አባታችሁም ኀጢአታችሁን ይቅር አይላችሁም።'),
  ('f437b0ad-a179-5ae7-a286-364922da3790', '9c0b67a5-8f57-504d-add2-b15689f08219', 'b4c08492-6cd1-50e3-abe3-9eadefc2e0fd', 1, 16, '“ስትጦሙም፥ እንደ ግብዞች አትጠውልጉ፤ ለሰዎች እንደ ጦመኛ ሊታዩ ፊታቸውን ያጠፋሉና፤ እውነት እላችኋለሁ፤ ዋጋቸውን ተቀብለዋል።'),
  ('4dedf303-1e46-5778-a2aa-41cdf4fc0200', '9c0b67a5-8f57-504d-add2-b15689f08219', 'b4c08492-6cd1-50e3-abe3-9eadefc2e0fd', 2, 17, 'አንተ ግን ስትጦም፥ በስውር ላለው አባትህ እንጂ እንደ ጦመኛ ለሰዎች እንዳትታይ ራስህን ተቀባ፤ ፊትህንም ታጠብ፤ በስውር የሚያይ አባትህም በግልጥ ይከፍልሃል።'),
  ('7590640d-915a-568e-a074-dfa1f2a19178', '9c0b67a5-8f57-504d-add2-b15689f08219', '16a2015a-0cd2-521a-a0f4-8dd391c37c97', 1, 19, '“ብልና ዝገት በሚያጠፉት ሌቦችም ቆፍረው በሚሠርቁት ዘንድ ለእናንተ በምድር ላይ መዝገብ አትሰብስቡ፤'),
  ('b45f11b1-7029-50d3-ae6e-a736b579102c', '9c0b67a5-8f57-504d-add2-b15689f08219', '16a2015a-0cd2-521a-a0f4-8dd391c37c97', 2, 20, 'ነገር ግን ብልም ዝገትም በማያጠፉት ሌቦችም ቆፍረው በማይሠርቁት ዘንድ ለእናንተ በሰማይ መዝገብ ሰብስቡ፤'),
  ('1edb0dda-5adc-555a-a1ad-703746ddc5f2', '9c0b67a5-8f57-504d-add2-b15689f08219', '16a2015a-0cd2-521a-a0f4-8dd391c37c97', 3, 21, 'መዝገብህ ባለበት ልብህ ደግሞ በዚያ ይሆናልና።'),
  ('4c110f79-a964-59cb-a5c8-026b92c73be4', '9c0b67a5-8f57-504d-add2-b15689f08219', 'd4f4a92b-237e-5600-a023-ff7d6a7b9abf', 1, 22, '“የሰውነት መብራት ዐይን ናት። ዐይንህ እንግዲህ ጤናማ ብትሆን፥ ሰውነትህ ሁሉ ብሩህ ይሆናል፤'),
  ('1f1a7863-33ec-5f1a-a539-c9b10b050add', '9c0b67a5-8f57-504d-add2-b15689f08219', 'd4f4a92b-237e-5600-a023-ff7d6a7b9abf', 2, 23, 'ዐይንህ ግን ታማሚ ብትሆን፥ ሰውነትህ ሁሉ የጨለመ ይሆናል። እንግዲህ በአንተ ያለው ብርሃን ጨለማ ከሆነ፥ ጨለማውስ እንዴት ይበረታ!'),
  ('9507551f-3cac-51bf-a974-ecd0a40ac0ce', '9c0b67a5-8f57-504d-add2-b15689f08219', '8b7a9b6f-96d5-5d1d-a1ae-86dc144d270e', 1, 24, '“ለሁለት ጌቶች መገዛት የሚቻለው ማንም የለም፤ ወይም አንዱን ይጠላል ሁለተኛውንም ይወዳል፤ ወይም ወደ አንዱ ይጠጋል ሁለተኛውንም ይንቃል፤ ለእግዚአብሔርና ለገንዘብ መገዛት አትችሉም።'),
  ('40293259-907b-571a-a511-92530e349964', '9c0b67a5-8f57-504d-add2-b15689f08219', 'a4599be0-39c8-5251-aeb0-1ba256a6fbde', 1, 25, '“ስለዚህ እላችኋለሁ፤ ስለ ነፍሳችሁ በምትበሉትና በምትጠጡት፥ ወይም ስለ ሰውነታችሁ በምትለብሱት አትጨነቁ፤ ነፍስ ከመብል ሰውነትም ከልብስ አይበልጥምን?'),
  ('a8355142-1db3-59ba-a6bd-c60d6b0a5946', '9c0b67a5-8f57-504d-add2-b15689f08219', 'a4599be0-39c8-5251-aeb0-1ba256a6fbde', 2, 26, 'ወደ ሰማይ ወፎች ተመልከቱ፤ አይዘሩም አያጭዱምም በጎተራም አይከቱም፤ የሰማዩ አባታችሁም ይመግባቸዋል፤ እናንተ ከእነርሱ እጅግ አትበልጡምን?'),
  ('a9216e7e-2228-5509-acb7-51fdb7653466', '9c0b67a5-8f57-504d-add2-b15689f08219', 'a4599be0-39c8-5251-aeb0-1ba256a6fbde', 3, 27, 'ከእናንተ ተጨንቆ በቁመቱ ላይ አንድ ክንድ መጨመር የሚችል ማን ነው?'),
  ('8405b723-56fc-5fb2-a7c7-1a5cc298c99b', '9c0b67a5-8f57-504d-add2-b15689f08219', 'a4599be0-39c8-5251-aeb0-1ba256a6fbde', 4, 28, 'ስለ ልብስስ ስለ ምን ትጨነቃላችሁ? የሜዳ አበቦች እንዴት እንዲያድጉ ልብ አድርጋችሁ ተመልከቱ፤'),
  ('fa5fbd78-00fd-5952-aed2-3f37d9df37a9', '9c0b67a5-8f57-504d-add2-b15689f08219', 'a4599be0-39c8-5251-aeb0-1ba256a6fbde', 5, 29, 'አይደክሙም አይፈትሉምም፤ ነገር ግን እላችኋለሁ፤ ሰሎሞንስ እንኳ በክብሩ ሁሉ ከነዚህ እንደ አንዱ አልለበሰም።'),
  ('aecb4c54-bab6-5b07-a1d7-1e19a63a81e6', '9c0b67a5-8f57-504d-add2-b15689f08219', 'a4599be0-39c8-5251-aeb0-1ba256a6fbde', 6, 30, 'እግዚአብሔር ግን ዛሬ ያለውን ነገም ወደ እቶን የሚጣለውን የሜዳን ሣር እንዲህ የሚያለብሰው ከሆነ፥ እናንተ እምነት የጎደላችሁ፥ እናንተንማ ይልቁን እንዴት?'),
  ('827cded0-61ea-598e-ae3b-bf1d802e9620', '9c0b67a5-8f57-504d-add2-b15689f08219', 'a4599be0-39c8-5251-aeb0-1ba256a6fbde', 7, 31, 'እንግዲህ ‘ምን እንበላለን? ምንስ እንጠጣለን? ምንስ እንለብሳለን?’ ብላችሁ አትጨነቁ፤'),
  ('3668593a-2c53-5cae-ace1-4a963a205247', '9c0b67a5-8f57-504d-add2-b15689f08219', 'a4599be0-39c8-5251-aeb0-1ba256a6fbde', 8, 32, 'ይህንስ ሁሉ አሕዛብ ይፈልጋሉ፤ ይህ ሁሉ እንዲያስፈልጋችሁ የሰማዩ አባታችሁ ያውቃልና።'),
  ('67b9558c-b01d-53ef-abd1-58eca5411de7', '9c0b67a5-8f57-504d-add2-b15689f08219', 'a4599be0-39c8-5251-aeb0-1ba256a6fbde', 9, 33, 'ነገር ግን አስቀድማችሁ የእግዚአብሔርን መንግሥት ጽድቁንም ፈልጉ፥ ይህም ሁሉ ይጨመርላችኋል።'),
  ('30a6701e-54fd-59ab-ac54-5d8b1da50718', '9c0b67a5-8f57-504d-add2-b15689f08219', 'a4599be0-39c8-5251-aeb0-1ba256a6fbde', 10, 34, '“ነገ ለራሱ ይጨነቃልና ለነገ አትጨነቁ፤ ለቀኑ ክፋቱ ይበቃዋል።'),
  ('daea23a3-6f2a-5884-a7ce-56b34faa30c7', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '65b11df7-70d1-5a3e-a247-d15f35bf6896', 1, 1, '“እንዳይፈረድባችሁ አትፍረዱ፤ በምትፈርዱበት ፍርድ ይፈረድባችኋልና፤ በምትሰፍሩበትም መስፈሪያ ይሰፈርባችኋል።'),
  ('3321fcde-df5d-5065-adfa-b3406976f338', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '65b11df7-70d1-5a3e-a247-d15f35bf6896', 2, 3, 'በወንድምህም ዐይን ያለውን ጉድፍ ስለምን ታያለህ፤ በዐይንህ ግን ያለውን ምሰሶ ስለ ምን አትመለከትም?'),
  ('57f87ce4-4d51-5303-a352-acf49481bd0e', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '65b11df7-70d1-5a3e-a247-d15f35bf6896', 3, 4, 'ወይም ወንድምህን ‘ከዐይንህ ጕድፍ ላውጣ ፍቀድልኝ’ እንዴትስ ትለዋለህ? እነሆም፥ በዐይንህ ምሰሶ አለ።'),
  ('c254f921-a926-5ab9-a495-0ee78a23d586', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '65b11df7-70d1-5a3e-a247-d15f35bf6896', 4, 5, 'አንተ ግብዝ፤ አስቀድመህ ከዐይንህ ምሰሶውን አውጣ፤ ከዚያም በኋላ ከወንድምህ ዐይን ጕድፉን ታወጣ ዘንድ አጥርተህ ታያለህ።'),
  ('aaf10dbd-82bb-595a-a57c-dc948d4c0273', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '65b11df7-70d1-5a3e-a247-d15f35bf6896', 5, 6, 'በእግራቸው እንዳይረግጡት ተመልሰውም እንዳይነክሱአችሁ፥ የተቀደሰውን ለውሾች አትስጡ፤ ዕንቁዎቻችሁንም በእሪያዎች ፊት አትጣሉ።'),
  ('993b5489-eeef-515d-a52b-9c7a633178eb', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '65b11df7-70d1-5a3e-a247-d15f35bf6896', 6, 7, '“ለምኑ፤ ይሰጣችሁማል፤ ፈልጉ፤ ታገኙማላችሁ፤ መዝጊያን አንኳኩ፤ ይከፈትላችሁማል።'),
  ('32f49a57-0d30-5e02-a010-171d460ba6a1', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '65b11df7-70d1-5a3e-a247-d15f35bf6896', 7, 8, 'የሚለምነው ሁሉ ይቀበላልና፤ የሚፈልገውም ያገኛል፤ መዝጊያንም ለሚያንኳኳ ይከፈትለታል።'),
  ('4ca36dd0-22dd-5661-a517-311ac9ebb75f', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '65b11df7-70d1-5a3e-a247-d15f35bf6896', 8, 9, 'ወይስ ልጁ እንጀራ ቢለምነው ድንጋይን የሚሰጠው ከእናንተ ማን ሰው ነው?'),
  ('9751bb9a-0eb1-5a62-a010-e6a407583e6c', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '65b11df7-70d1-5a3e-a247-d15f35bf6896', 9, 10, 'ዓሣስ ቢለምነው እባብን ይሰጠዋልን?'),
  ('1aaf4319-9531-5e4f-a2d1-9b27e014c6c0', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '65b11df7-70d1-5a3e-a247-d15f35bf6896', 10, 11, 'እንኪያስ እናንተ ክፉዎች ስትሆኑ ለልጆቻችሁ መልካም ስጦታ መስጠትን ካወቃችሁ በሰማያት ያለው አባታችሁ ለሚለምኑት እንዴት አብልጦ መልካም ነገርን ይሰጣቸው!'),
  ('f1c54fcd-c050-5039-a866-fa689075bb19', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '65b11df7-70d1-5a3e-a247-d15f35bf6896', 11, 12, 'እንግዲህ ሰዎች ሊያደርጉላችሁ የምትወዱትን ሁሉ እናንተ ደግሞ እንዲሁ አድርጉላቸው፤ ሕግም ነቢያትም ይህ ነውና።'),
  ('01ca50f1-a64a-5cb1-a836-ce54ffe406ee', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', 'b9941350-b41b-5069-abe9-3aaa6e8dbd02', 1, 13, '“በጠበበው ደጅ ግቡ፤ ወደ ጥፋት የሚወስደው ደጅ ሰፊ መንገዱም ትልቅ ነውና፤ ወደ እርሱም የሚገቡ ብዙዎች ናቸው፤'),
  ('52cd078b-75a9-5a34-a6fc-23d53ddd09b4', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', 'b9941350-b41b-5069-abe9-3aaa6e8dbd02', 2, 14, 'ወደ ሕይወት የሚወስደው ደጅ የጠበበ፥ መንገዱም የቀጠነ ነውና፤ የሚያገኙትም ጥቂቶች ናቸው።'),
  ('975d77db-48d8-5aef-a97f-e403d9c0a3db', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '351f6f98-d114-536b-ae87-5d648ef2e09e', 1, 15, '“የበግ ለምድ ለብሰው ከሚመጡባችሁ በውስጣቸው ግን ነጣቂዎች ተኵላዎች ከሆኑ ከሐሰተኞች ነቢያት ተጠንቀቁ።'),
  ('66c69855-5502-5c6e-aaf5-6e7e98ee6142', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '351f6f98-d114-536b-ae87-5d648ef2e09e', 2, 16, 'ከፍሬያቸው ታውቋቸዋላችሁ። ከእሾህ ወይን ከኩርንችትስ በለስ ይለቀማልን?'),
  ('09031bba-6fe8-5e2e-a687-0cf72e590cf8', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '351f6f98-d114-536b-ae87-5d648ef2e09e', 3, 17, 'እንዲሁ መልካም ዛፍ ሁሉ መልካም ፍሬ ያደርጋል፤ ክፉም ዛፍ ክፉ ፍሬ ያደርጋል።'),
  ('f6762a4e-4d01-5987-ab00-a99b0c473954', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '351f6f98-d114-536b-ae87-5d648ef2e09e', 4, 18, 'መልካም ዛፍ ክፉ ፍሬ ማፍራት፥ ወይም ክፉ ዛፍ መልካም ፍሬ ማፍራት አይቻለውም።'),
  ('3dbe8382-29ad-525c-aa83-35e030c0d1ae', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '351f6f98-d114-536b-ae87-5d648ef2e09e', 5, 19, 'መልካም ፍሬ የማያፈራ ዛፍ ሁሉ ይቆረጣል፤ ወደ እሳትም ይጣላል።'),
  ('22773790-a25b-5183-a0de-3146f007076b', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '351f6f98-d114-536b-ae87-5d648ef2e09e', 6, 20, 'ስለዚህም ከፍሬያቸው ታውቋቸዋላችሁ።'),
  ('2f59aa7f-06f7-5e67-a9c5-90c3c8f72f91', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '351f6f98-d114-536b-ae87-5d648ef2e09e', 7, 21, 'በሰማያት ያለውን የአባቴን ፈቃድ የሚያደርግ እንጂ ‘ጌታ ሆይ! ጌታ ሆይ!’ የሚለኝ ሁሉ መንግሥተ ሰማያት የሚገባ አይደለም።'),
  ('7b8e3060-12a4-52d1-a6b3-4c13b92108ee', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '351f6f98-d114-536b-ae87-5d648ef2e09e', 8, 22, 'በዚያ ቀን ብዙዎች ‘ጌታ ሆይ! ጌታ ሆይ! በስምህ ትንቢት አልተናገርንምን? በስምህስ አጋንንትን አላወጣንምን? በስምህስ ብዙ ተአምራትን አላደረግንምን?’ ይሉኛል።'),
  ('818362c9-fdaa-5df3-a860-2efaebbc7748', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', '351f6f98-d114-536b-ae87-5d648ef2e09e', 9, 23, 'የዚያን ጊዜም ‘ከቶ አላወቅኋችሁም፤ እናንተ አመፀኞች፥ ከእኔ ራቁ’ ብዬ እመሰክርባቸዋለሁ።'),
  ('fc3a3df6-b2f1-5101-a6cf-a5fde2864306', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', 'd463069a-eb32-5012-a922-7188241ad687', 1, 24, '“ስለዚህ ይህን ቃሌን ሰምቶ የሚያደርገው ሁሉ ቤቱን በዐለት ላይ የሠራ ልባም ሰውን ይመስላል።'),
  ('3be8cae7-c88f-5a12-aa7a-e5e420e8206d', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', 'd463069a-eb32-5012-a922-7188241ad687', 2, 25, 'ዝናብም ወረደ ጎርፍም መጣ ነፋስም ነፈሰ ያንም ቤት ገፋው፤ በዐለት ላይም ስለ ተመሠረተ አልወደቀም።'),
  ('690d3fef-12b5-5cb7-a1f5-1bdfc88c282f', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', 'd463069a-eb32-5012-a922-7188241ad687', 3, 26, 'ይህንም ቃሌን ሰምቶ የማያደርገው ሰው ሁሉ ቤቱን በአሸዋ ላይ የሠራ ሰነፍ ሰውን ይመስላል።'),
  ('36544ac0-3031-5be9-a003-6fd2e4defdad', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', 'd463069a-eb32-5012-a922-7188241ad687', 4, 27, 'ዝናብም ወረደ ጎርፍም መጣ ነፋስም ነፈሰ ያንም ቤት መታው፤ ወደቀም፤ አወዳደቁም ታላቅ ሆነ።”'),
  ('b59ce091-8f42-5640-afb9-57e217747777', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', 'd463069a-eb32-5012-a922-7188241ad687', 5, 28, 'ኢየሱስም ይህን ነገር በጨረሰ ጊዜ ሕዝቡ በትምህርቱ ተገረሙ፤ እንደ ጻፎቻቸው ሳይሆን፥'),
  ('9a617263-428c-5270-a317-8dfa3f87563b', 'e2eb5ba2-8eaa-5037-a73a-7447d4e79beb', 'd463069a-eb32-5012-a922-7188241ad687', 6, 29, 'እንደ ባለ ሥልጣን ያስተምራቸው ነበርና።'),
  ('3b591e8d-bc43-512c-af83-4f9559829c71', 'c97bc561-dae4-5847-ae96-149d08697553', '3ca0e176-78ce-5f7c-a795-818561fe3891', 1, 1, 'ከተራራም በወረደ ጊዜ ብዙ ሕዝብ ተከተሉት።'),
  ('bdf21151-99c1-5a3d-ae15-9e1f0a37733e', 'c97bc561-dae4-5847-ae96-149d08697553', '3ca0e176-78ce-5f7c-a795-818561fe3891', 2, 2, 'እነሆም፥ ለምጻም ቀርቦ “ጌታ ሆይ! ብትወድስ ልታነጻኝ ትችላለህ” እያለ ሰገደለት።'),
  ('cbfe5b99-9a2c-5e18-aa37-cab4e49b9642', 'c97bc561-dae4-5847-ae96-149d08697553', '3ca0e176-78ce-5f7c-a795-818561fe3891', 3, 3, 'እጁንም ዘርግቶ ዳሰሰውና “እወዳለሁ፤ ንጻ” አለው። ወዲያውም ለምጹ ነጻ።'),
  ('779a61a4-4ba1-5969-ab22-0831cabf9574', 'c97bc561-dae4-5847-ae96-149d08697553', '3ca0e176-78ce-5f7c-a795-818561fe3891', 4, 4, 'ኢየሱስም “ለማንም እንዳትናገር ተጠንቀቅ፤ ነገር ግን ሄደህ ራስህን ለካህን አሳይ፤ ለእነርሱም ምስክር እንዲሆን ሙሴ ያዘዘውን መባ አቅርብ” አለው።'),
  ('85e8f4ff-5441-5a4a-ab21-1b44a1974926', 'c97bc561-dae4-5847-ae96-149d08697553', '67ce7c7c-cda0-5a15-a93d-1d4010cc119a', 1, 5, 'ወደ ቅፍርናሆምም በገባ ጊዜ የመቶ አለቃ ወደ እርሱ ቀርቦ'),
  ('5e58524b-9503-5268-a4da-d48c8ddb6162', 'c97bc561-dae4-5847-ae96-149d08697553', '67ce7c7c-cda0-5a15-a93d-1d4010cc119a', 2, 6, '“ጌታ ሆይ!ብላቴናዬ ሽባ ሆኖ እጅግ እየተሣቀየ በቤት ተኝቶአል” ብሎ ለመነው።'),
  ('f19bbaa1-7ad5-554b-a756-56602110ea2d', 'c97bc561-dae4-5847-ae96-149d08697553', '67ce7c7c-cda0-5a15-a93d-1d4010cc119a', 3, 7, 'ኢየሱስም “እኔ መጥቼ እፈውሰዋለሁ” አለው።'),
  ('bb5187a2-7841-5aa6-af31-a760980af95b', 'c97bc561-dae4-5847-ae96-149d08697553', '67ce7c7c-cda0-5a15-a93d-1d4010cc119a', 4, 8, 'የመቶ አለቃውም መልሶ “ጌታ ሆይ! በቤቴ ጣራ በታች ልትገባ አይገባኝም፤ ነገር ግን ቃል ብቻ ተናገር፤ ብላቴናዬም ይፈወሳል።'),
  ('5c58deb2-431f-5bb6-ab7e-e7d9ddc4280a', 'c97bc561-dae4-5847-ae96-149d08697553', '67ce7c7c-cda0-5a15-a93d-1d4010cc119a', 5, 9, 'እኔ ደግሞ ለሌሎች ተገዥ ነኝና፤ ከእኔም በታች ጭፍራ አለኝ፤ አንዱንም ‘ሂድ’ ብለው ይሄዳል፤ ሌላውንም ‘ና’ ብለው ይመጣል፤ ባሪያዬንም ‘ይህን አድርግ’ ብለው ያደርጋል” አለው።'),
  ('5b8bdcbf-ada9-5dc6-a8ce-2ebca7c192ee', 'c97bc561-dae4-5847-ae96-149d08697553', '67ce7c7c-cda0-5a15-a93d-1d4010cc119a', 6, 10, 'ኢየሱስም ሰምቶ ተደነቀና ለተከተሉት እንዲህ አለ “እውነት እላችኋለሁ፤ በእስራኤል እንኳ እንዲህ ያለ ትልቅ እምነት አላገኘሁም።'),
  ('659230b2-c1d4-5250-a03d-a1a927003862', 'c97bc561-dae4-5847-ae96-149d08697553', '67ce7c7c-cda0-5a15-a93d-1d4010cc119a', 7, 11, 'እላችኋለሁም፥ ብዙዎች ከምሥራቅና ከምዕራብ ይመጣሉ፤ ከአብርሃምና ከይስሐቅ ከያዕቆብም ጋር በመንግሥተ ሰማያት ይቀመጣሉ፤'),
  ('c1a1374b-611f-57b5-a985-8bc5c9bfc13e', 'c97bc561-dae4-5847-ae96-149d08697553', '67ce7c7c-cda0-5a15-a93d-1d4010cc119a', 8, 12, 'የመንግሥት ልጆች ግን በውጭ ወደ አለው ጨለማ ይጣላሉ፤ በዚያ ልቅሶና ጥርስ ማፋጨት ይሆናል።”'),
  ('b59cbdd7-a303-5873-a6f8-63d858f46934', 'c97bc561-dae4-5847-ae96-149d08697553', '67ce7c7c-cda0-5a15-a93d-1d4010cc119a', 9, 13, 'ኢየሱስም ለመቶ አለቃ “ሂድና እንዳመንህ ይሁንልህ፤” አለው። ብላቴናውም በዚያች ሰዓት ተፈወሰ።'),
  ('0617545a-0809-5409-a7aa-0b06365c84e5', 'c97bc561-dae4-5847-ae96-149d08697553', 'e0cba2a3-79a5-56b0-ac3f-6c3072e5cbe6', 1, 14, 'ኢየሱስም ወደ ጴጥሮስ ቤት ገብቶ አማቱን በንዳድ ታማ ተኝታ አያት፤'),
  ('071551f4-baf5-55b0-afa1-c616934de344', 'c97bc561-dae4-5847-ae96-149d08697553', 'e0cba2a3-79a5-56b0-ac3f-6c3072e5cbe6', 2, 15, 'እጅዋንም ዳሰሰ፤ ንዳዱም ለቀቃት፤ ተነሥታም አገለገለቻቸው።'),
  ('c13cc50a-bfe3-59e0-a39f-f9763bdfef52', 'c97bc561-dae4-5847-ae96-149d08697553', 'e0cba2a3-79a5-56b0-ac3f-6c3072e5cbe6', 3, 16, 'በመሸም ጊዜ አጋንንት ያደረባቸውን ብዙዎችን ወደ እርሱ አመጡ፤ በነቢዩ በኢሳይያስ “እርሱ ድካማችንን ተቀበለ ደዌያችንንም ተሸከመ፤” የተባለው ይፈጸም ዘንድ መናፍስትን በቃኣሉ አወጣ፤ የታመሙትንም ሁሉ ፈወሰ።'),
  ('722bed88-c9f8-5ca9-a72d-9578492a4d63', 'c97bc561-dae4-5847-ae96-149d08697553', '15f7b2a1-f3a0-5cda-aab3-1a664420aaef', 1, 18, 'ኢየሱስም ብዙ ሰዎች ሲከቡት አይቶ ወደ ማዶ እንዲሻገሩ አዘዘ።'),
  ('bf230999-9586-5887-acf4-e89ac843ee4b', 'c97bc561-dae4-5847-ae96-149d08697553', '15f7b2a1-f3a0-5cda-aab3-1a664420aaef', 2, 19, 'አንድ ጸሐፊም ቀርቦ “መምህር ሆይ! ወደምትሄድበት ሁሉ እከተልሃለሁ፤” አለው።'),
  ('c0ef158c-d13b-5eb2-ad16-a5caeb888660', 'c97bc561-dae4-5847-ae96-149d08697553', '15f7b2a1-f3a0-5cda-aab3-1a664420aaef', 3, 20, 'ኢየሱስም “ለቀበሮዎች ጉድጓድ ለሰማይም ወፎች መሳፈሪያ አላቸው፤ ለሰው ልጅ ግን ራሱን የሚያስጠጋበት የለውም፤” አለው።'),
  ('85dab60a-bb9b-567a-af0c-a8b95d0bf3c8', 'c97bc561-dae4-5847-ae96-149d08697553', '15f7b2a1-f3a0-5cda-aab3-1a664420aaef', 4, 21, 'ከደቀ መዛሙርቱም ሌላው “ጌታ ሆይ! አስቀድሜ እንድሄድ አባቴን እንድቀብር ፍቀድልኝ፤” አለው።'),
  ('3ab4266d-02c3-570d-a516-c7053f64b760', 'c97bc561-dae4-5847-ae96-149d08697553', '15f7b2a1-f3a0-5cda-aab3-1a664420aaef', 5, 22, 'ኢየሱስ “ተከተለኝ፤ ሙታናቸውንም እንዲቀብሩ ሙታንን ተዋቸው፤” አለው።'),
  ('fac80868-8011-5cfd-aa0e-aea8dfdd1d5e', 'c97bc561-dae4-5847-ae96-149d08697553', '05c249ad-0001-5386-a078-7140664ff551', 1, 23, 'ወደ ታንኳም ሲገባ ደቀ መዛሙርቱ ተከተሉት።'),
  ('dd9dd56a-b17b-5664-a387-0322432f4636', 'c97bc561-dae4-5847-ae96-149d08697553', '05c249ad-0001-5386-a078-7140664ff551', 2, 24, 'እነሆም ማዕበሉ ታንኳይቱን እስኪደፍናት ድረስ በባሕር ታላቅ መናወጥ ሆነ፤ እርሱ ግን ተኝቶ ነበር።'),
  ('3f1c959c-40c6-5274-a192-68ee9fdc25a0', 'c97bc561-dae4-5847-ae96-149d08697553', '05c249ad-0001-5386-a078-7140664ff551', 3, 25, 'ደቀ መዛሙርቱም ቀርበው “ጌታ ሆይ! አድነን፤ ጠፋን፤” እያሉ አስነሡት።'),
  ('6df68aea-18aa-5b4d-a4c8-57cc5443f985', 'c97bc561-dae4-5847-ae96-149d08697553', '05c249ad-0001-5386-a078-7140664ff551', 4, 26, 'እርሱም “እናንተ እምነት የጎደላችሁ! ስለ ምን ትፈራላችሁ?” አላቸው፤ ከዚህ በኋላ ተነሥቶ ነፋሱንና ባሕሩን ገሠጸ፤ ታላቅ ጸጥታም ሆነ።'),
  ('59996ce5-b132-55f8-adc0-e34974f02c34', 'c97bc561-dae4-5847-ae96-149d08697553', '05c249ad-0001-5386-a078-7140664ff551', 5, 27, 'ሰዎቹም “ነፋሳትና ባሕርስ ስንኳ የሚታዘዙለት፥ ይህ እንዴት ያለ ሰው ነው?” እያሉ ተደነቁ።'),
  ('bcd1f8e0-706d-5953-a8fa-a4a8b59af5f1', 'c97bc561-dae4-5847-ae96-149d08697553', '33d681f1-5772-5c79-ace1-d1e90e6204d3', 1, 28, 'ወደ ማዶም ወደ ጌርጋሴኖን አገር በመጣ ጊዜ፥ አጋንንት ያደሩባቸው ሁለት ሰዎች ከመቃብር ወጥተው ተገናኙት፤ እነርሱም ሰው በዚያ መንገድ ማለፍ እስኪሳነው ድረስ እጅግ ክፉዎች ነበሩ።'),
  ('5dba4755-3224-5567-a209-583369766221', 'c97bc561-dae4-5847-ae96-149d08697553', '33d681f1-5772-5c79-ace1-d1e90e6204d3', 2, 29, 'እነሆም “ኢየሱስ ሆይ! የእግዚአብሔር ልጅ! ከአንተ ጋር ምን አለን? ጊዜው ሳይደርስ ልታሠቃየን ወደዚህ መጣህን?” እያሉ ጮኹ።'),
  ('cc789919-0c41-5d4f-a3d4-e1b9ef049cff', 'c97bc561-dae4-5847-ae96-149d08697553', '33d681f1-5772-5c79-ace1-d1e90e6204d3', 3, 30, 'ከእነርሱም ርቆ የብዙ እሪያ መንጋ ይሰማራ ነበር።'),
  ('5bac7b01-9db8-5ceb-afda-30cf0160bf0a', 'c97bc561-dae4-5847-ae96-149d08697553', '33d681f1-5772-5c79-ace1-d1e90e6204d3', 4, 31, 'አጋንንቱም “ታወጣንስ እንደሆንህ፥ ወደ እሪያው መንጋ ስደደን፤” ብለው ለመኑት። “ሂዱ፤” አላቸው።'),
  ('3144f539-424b-545c-a1ac-5871e7f7106d', 'c97bc561-dae4-5847-ae96-149d08697553', '33d681f1-5772-5c79-ace1-d1e90e6204d3', 5, 32, 'እነርሱም ወጥተው ወደ እሪያዎቹ ሄዱና ገቡ፤ እነሆም የእሪያዎቹ መንጋ ሁሉ ከአፋፉ ወደ ባሕር እየተጣደፉ ሮጡ፤ በውሃም ውስጥ ሞቱ።'),
  ('bbeb496d-a0dd-595a-a2c0-0bd9c8ffaf78', 'c97bc561-dae4-5847-ae96-149d08697553', '33d681f1-5772-5c79-ace1-d1e90e6204d3', 6, 33, 'እረኞችም ሸሹ፤ ወደ ከተማይቱም ሄደው ነገሩን ሁሉ አጋንንትም በአደሩባቸው የሆነውን አወሩ።'),
  ('1c1bf278-ab76-53cc-a054-b20bcd22c3a5', 'c97bc561-dae4-5847-ae96-149d08697553', '33d681f1-5772-5c79-ace1-d1e90e6204d3', 7, 34, 'እነሆም ከተማው ሁሉ ኢየሱስን ሊገናኝ ወጣ፤ ባዩትም ጊዜ ከአገራቸው እንዲሄድላቸው ለመኑት።'),
  ('db701774-f966-50d7-a986-759d5333d823', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '511b7f50-be5f-5e6b-a5fc-1015c7df61ae', 1, 1, 'በታንኳም ገብቶ ተሻገረና ወደ ገዛ ከተማው መጣ።'),
  ('813600ce-cd89-54eb-afcb-4b884a21d502', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '511b7f50-be5f-5e6b-a5fc-1015c7df61ae', 2, 2, 'እነሆም፥ በአልጋ የተኛ ሽባ ወደ እርሱ አመጡ። ኢየሱስም እምነታቸውን አይቶ ሽባውን “አንተ ልጅ! አይዞህ፤ ኀጢአትህ ተሰረየችልህ፤” አለው።'),
  ('6a1b0b77-cab3-5191-a301-49e9b2139c00', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '511b7f50-be5f-5e6b-a5fc-1015c7df61ae', 3, 3, 'እነሆም ከጻፎቹ አንዳንዶቹ በልባቸው “ይህስ ይሳደባል፤” አሉ።'),
  ('412c8b46-6789-583a-a247-808c49a5aa7a', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '511b7f50-be5f-5e6b-a5fc-1015c7df61ae', 4, 4, 'ኢየሱስም አሳባቸውን አውቆ እንዲህ አለ “ስለ ምን በልባችሁ ክፉ ታስባላችሁ?'),
  ('4bec0959-099f-54c2-abc8-fedd18056e74', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '511b7f50-be5f-5e6b-a5fc-1015c7df61ae', 5, 5, '‘ኀጢአትህ ተሰረየችልህ’ ከማለት ወይስ ‘ተነሣና ሂድ’ ከማለት ማናቸው ይቀላል?'),
  ('c8650547-ff95-5929-a75c-2324f7b70702', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '511b7f50-be5f-5e6b-a5fc-1015c7df61ae', 6, 6, 'ነገር ግን በምድር ላይ ኀጢአትን ያስተሰርይ ዘንድ ለሰው ልጅ ሥልጣን እንዳለው እንድታውቁ፤” በዚያን ጊዜ ሽባውን “ተነሣ፤ አልጋህን ተሸከምና ወደ ቤትህ ሂድ፤” አለው።'),
  ('068d3734-bc01-5f73-aa63-c862e45d508c', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '511b7f50-be5f-5e6b-a5fc-1015c7df61ae', 7, 7, 'ተነሥቶም ወደ ቤቱ ሄደ።'),
  ('a3b16aa9-c4da-5c7e-a956-fd593dc9e566', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '511b7f50-be5f-5e6b-a5fc-1015c7df61ae', 8, 8, 'ሕዝቡም አይተው ተደነቁ፤ ለሰውም እንዲህ ያለ ሥልጣን የሰጠ እግዚአብሔርን አከበሩ።'),
  ('488f39d1-fb86-533a-a823-64d452a80ca3', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'ceb6009f-37c8-5090-a663-0b75703c0e71', 1, 9, 'ኢየሱስም ከዚያ አልፎ በመቅረጫው ተቀምጦ የነበረ ማቴዎስ የሚባል አንድ ሰው አየና “ተከተለኝ” አለው። ተነሥቶም ተከተለው።'),
  ('432e088e-c6d1-5470-a997-7926f0841074', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'ceb6009f-37c8-5090-a663-0b75703c0e71', 2, 10, 'በቤቱም በማዕድ ተቀምጦ ሳለ፥ እነሆ፥ ብዙ ቀራጮችና ኀጢአተኞች መጥተው ከኢየሱስና ከደቀ መዛሙርቱ ጋር አብረው ተቀመጡ።'),
  ('f87a635b-8118-556f-abc6-f47c50e0d707', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'ceb6009f-37c8-5090-a663-0b75703c0e71', 3, 11, 'ፈሪሳውያንም አይተው ደቀ መዛሙርቱን “መምህራችሁ ከቀራጮችና ከኀጢአተኞች ጋር አብሮ ስለ ምን ይበላል?” አሉአቸው።'),
  ('f9de4c59-cc3c-5517-aff8-1f1fef481f45', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'ceb6009f-37c8-5090-a663-0b75703c0e71', 4, 12, 'ኢየሱስም ሰምቶ “ሕመምተኞች እንጂ ባለ ጤነኞች ባለ መድኃኒት አያስፈልጋቸውም፤'),
  ('04d0baa7-67a1-5be4-af47-583d1686ea77', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'ceb6009f-37c8-5090-a663-0b75703c0e71', 5, 13, 'ነገር ግን ሄዳችሁ ‘ምሕረትን እወዳለሁ መሥዋዕትንም አይደለም፤’ ያለው ምን እንደ ሆነ ተማሩ፤ ኀጢአተኞችን ወደ ንስሐ እንጂ ጻድቃንን ልጠራ አልመጣሁምና፤” አላቸው።'),
  ('21d16e35-2a07-5d57-a2be-87b068c8ff2d', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'd3eb2956-ddee-54cd-aed5-2ce25369330d', 1, 14, 'በዚያን ጊዜ የዮሐንስ ደቀ መዛሙርት ወደ እርሱ ቀርበው “እኛና ፈሪሳውያን ብዙ ጊዜ የምንጦመው፥ ደቀ መዛሙርትህ ግን የማይጦሙት ስለ ምንድር ነው?” አሉት።'),
  ('0f5f4586-5eb9-5de5-a806-093d7e2426af', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'd3eb2956-ddee-54cd-aed5-2ce25369330d', 2, 15, 'ኢየሱስም እንዲህ አላቸው “ሚዜዎች ሙሽራው ከእነርሱ ጋር ሳለ ሊያዝኑ ይችላሉን? ነገር ግን ሙሽራው ከእነርሱ የሚወሰድበት ወራት ይመጣል፤ በዚያ ጊዜም ይጦማሉ።'),
  ('fa0e742c-6d0c-5177-a708-9c3a3053e110', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'd3eb2956-ddee-54cd-aed5-2ce25369330d', 3, 16, 'በአረጀ ልብስ አዲስ እራፊ የሚያኖር የለም፤ መጣፊያው ልብሱን ይቦጭቀዋልና፤ መቀደዱም የባሰ ይሆናል።'),
  ('10a6bed7-466a-568f-a057-ece7459868ce', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'd3eb2956-ddee-54cd-aed5-2ce25369330d', 4, 17, 'በአረጀ አቁማዳም አዲስ የወይን ጠጅ የሚያኖር የለም፤ ቢደረግ ግን አቁማዳው ይፈነዳል፤ የወይን ጠጁም ይፈሳል፤ አቁማዳውም ይጠፋል፤ ነገር ግን አዲሱን የወይን ጠጅ በአዲስ አቁማዳ ያኖረዋል፤ ሁለቱም ይጠባበቃሉ።”'),
  ('a9d6a6d9-bec4-5f88-af33-bc190ef2730d', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '25d7570b-9c63-5fc1-a5ac-f5cf74893aba', 1, 18, 'ይህንም ሲነግራቸው አንድ መኰንን መጥቶ “ልጄ አሁን ሞተች፤ ነገር ግን መጥተህ እጅህን ጫንባት፥ በሕይወትም ትኖራለች፤” እያለ ሰገደለት።'),
  ('3732a181-fe5e-50e3-a909-ce2f67619885', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '25d7570b-9c63-5fc1-a5ac-f5cf74893aba', 2, 19, 'ኢየሱስም ተነሥቶ ከደቀ መዛሙርቱ ጋር ተከተለው።'),
  ('ca18da75-7721-5d74-aa6c-b25614ee5d66', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '25d7570b-9c63-5fc1-a5ac-f5cf74893aba', 3, 20, 'እነሆም ከዐሥራ ሁለት ዓመት ጀምሮ ደም የሚፈስሳት ሴት በኋላው ቀርባ የልብሱን ጫፍ ዳሰሰች፤'),
  ('ae72e286-d099-5dbc-a659-b52b6769c81d', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '25d7570b-9c63-5fc1-a5ac-f5cf74893aba', 4, 21, 'በልብዋ “ልብሱን ብቻ የዳሰስሁ እንደ ሆነ እድናለሁ፤” ትል ነበረችና።'),
  ('81c5f23f-65b1-590b-a17b-77c3c988252f', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '25d7570b-9c63-5fc1-a5ac-f5cf74893aba', 5, 22, 'ኢየሱስም ዘወር ብሎ አያትና “ልጄ ሆይ! አይዞሽ፤ እምነትሽ አድኖሻል፤” አላት። ሴቲቱም ከዚያች ሰዓት ጀምራ ዳነች።'),
  ('9cb7bc3b-c51a-5545-a36e-4d1e7d56be32', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '25d7570b-9c63-5fc1-a5ac-f5cf74893aba', 6, 23, 'ኢየሱስም ወደ መኰንኑ ቤት በደረሰ ጊዜ፥ እምቢልተኞችንና የሚንጫጫውን ሕዝብ አይቶ'),
  ('1f1c59d6-d86c-5d8b-ad69-f2113df879d5', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '25d7570b-9c63-5fc1-a5ac-f5cf74893aba', 7, 24, '“ብላቴናይቱ ተኝታለች እንጂ አልሞተችምና ፈቀቅ በሉ፤” አላቸው። በጣምም ሳቁበት።'),
  ('0e6588e1-9294-5068-aee1-cd538b17bea3', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '25d7570b-9c63-5fc1-a5ac-f5cf74893aba', 8, 25, 'ሕዝቡን ግን ከአስወጡ በኋላ ገብቶ እጅዋን ያዛት፤ ብላቴናይቱም ተነሣች።'),
  ('eaace19c-7e6b-5658-afe7-19d5c8e20c69', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', '25d7570b-9c63-5fc1-a5ac-f5cf74893aba', 9, 26, 'ያም ዝና ወደዚያ አገር ሁሉ ወጣ።'),
  ('299fcda4-f8f3-58e2-a6b3-1caac1ec7e1a', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'f3e5429d-20b9-52b8-ac6d-1ae87983c1ed', 1, 27, 'ኢየሱስም ከዚያ ሲያልፍ ሁለት ዕውሮች “የዳዊት ልጅ ሆይ! ማረን፤” ብለው እየጮሁ ተከተሉት።'),
  ('1d7eb0b5-6b60-576c-a8f6-800771b17d7f', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'f3e5429d-20b9-52b8-ac6d-1ae87983c1ed', 2, 28, 'ወደ ቤትም በገባ ጊዜ ዕውሮቹ ወደ እርሱ ቀረቡ፤ ኢየሱስም “ይህን ማድረግ እንድችል ታምናላችሁን?” አላቸው። “አዎን፥ ጌታ ሆይ!” አሉት።'),
  ('cea60890-7a4c-5481-a8ad-e1c738ed41d0', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'f3e5429d-20b9-52b8-ac6d-1ae87983c1ed', 3, 29, 'በዚያን ጊዜ “እንደ እምነታችሁ ይሁንላችሁ፤” ብሎ ዐይኖቻቸውን ዳሰሰ።'),
  ('fadfc02b-00a2-5f6f-a794-4e907785fa05', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'f3e5429d-20b9-52b8-ac6d-1ae87983c1ed', 4, 30, 'ዐይኖቻቸውም ተከፈቱ። ኢየሱስም “ማንም እንዳያውቅ ተጠንቀቁ፤” ብሎ በብርቱ አዘዛቸው።'),
  ('3dffbba8-eb62-541f-a94a-da24b50c8df4', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'f3e5429d-20b9-52b8-ac6d-1ae87983c1ed', 5, 31, 'እነርሱ ግን ወጥተው በዚያ አገር ሁሉ ስለ እርሱ አወሩ።'),
  ('926233ae-8813-5414-a78f-8a3f63434927', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'adc8630c-d306-5bf2-aa87-963435cef432', 1, 32, 'እነርሱም ሲወጡ እነሆ ጋኔን ያደረበትን ድዳ ሰው ወደ እርሱ አመጡ።'),
  ('6153df5b-a36d-5e68-a442-0e0de22e87e9', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'adc8630c-d306-5bf2-aa87-963435cef432', 2, 33, 'ጋኔኑንም ካወጣው በኋላ ድዳው ተናገረ። ሕዝቡም “እንዲህ ያለ በእስራኤል ዘንድ ከቶ አልታየም፤” እያሉ ተደነቁ።'),
  ('a6decaa1-582b-5630-a844-8b5fe84bd0d8', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'adc8630c-d306-5bf2-aa87-963435cef432', 3, 34, 'ፈሪሳውያን ግን “በአጋንንት አለቃ አጋንንትን ያወጣል፤” አሉ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('5ec295fe-5db5-5efd-ac0c-96ed70320a9e', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'adc8630c-d306-5bf2-aa87-963435cef432', 4, 35, 'ኢየሱስም በምኩራቦቻቸው እያስተማረ፥ የመንግሥትንም ወንጌል እየሰበከ፥ በሕዝብም ያለውን ደዌና ሕማም ሁሉ እየፈወሰ፥ በከተማዎችና በመንደሮች ሁሉ ይዞር ነበር።'),
  ('1365369a-762a-51da-af10-61db5d5366fd', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'adc8630c-d306-5bf2-aa87-963435cef432', 5, 36, 'ብዙ ሕዝብም ባየ ጊዜ፥ እረኛ እንደ ሌላቸው በጎች ተጨንቀው ተጥለውም ነበርና አዘነላቸው።'),
  ('96e3b4ef-ec2f-5a3e-ac0b-bd1f563c9b63', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'adc8630c-d306-5bf2-aa87-963435cef432', 6, 37, 'በዚያን ጊዜ ደቀ መዛሙርቱን “መከሩስ ብዙ ነው፤ ሠራተኞች ግን ጥቂቶች ናቸው፤'),
  ('7c09057c-3d14-52f9-a8ab-69751fd3e389', 'e559b5f3-df15-5768-a275-b3a0d3f69c93', 'adc8630c-d306-5bf2-aa87-963435cef432', 7, 38, 'እንግዲህ የመከሩን ጌታ ወደ መከሩ ሠራተኞች እንዲልክ ለምኑት፤” አላቸው።'),
  ('21260c7d-21f7-5902-a708-dffb703c9753', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 1, 1, 'አሥራ ሁለቱን ደቀ መዛሙርቱን ወደ እርሱ ጠርቶ፥ እንዲያወጡአቸው በርኩሳን መናፍስት ላይ ደዌንና ሕማምንም ሁሉ እንዲፈውሱ ሥልጣን ሰጣቸው።'),
  ('e2b59a00-8389-54aa-a184-43726a82f071', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 2, 2, 'የዐሥራ ሁለቱም ሐዋርያት ስም ይህ ነው፤ መጀመሪያው ጴጥሮስ የተባለው ስምዖን ወንድሙ እንድርያስም፥ የዘብዴዎስ ልጅ ያዕቆብም ወንድሙ ዮሐንስም፥'),
  ('f3227c7d-8dae-5696-a88d-2ee55320fd83', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 3, 3, 'ፊልጶስም በርተሎሜዎስም፥ ቶማስም ቀራጩ ማቴዎስም፥ የእልፍዮስ ልጅ ያዕቆብም ታዴዎስም የተባለው ልብድዮስ፥'),
  ('fad548a7-097f-511d-a3cc-3ebfe1bf12ec', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 4, 4, 'ቀነናዊውም ስምዖን ደግሞም አሳልፎ የሰጠው የአስቆሮቱ ይሁዳ።'),
  ('7ec72df9-d09a-57b0-aa4b-45f02bc15cb6', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 5, 5, 'እነዚህን ዐሥራ ሁለቱን ኢየሱስ ላካቸው፤ አዘዛቸውም፤ እንዲህም አለ “በአሕዛብ መንገድ አትሂዱ፤ ወደ ሳምራውያንም ከተማ አትግቡ፤'),
  ('0ddcb87b-a0a7-5198-a081-4abdad17a0eb', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 6, 6, 'ይልቅስ የእስራኤል ቤት ወደሚሆኑ ወደ ጠፉት በጎች ሂዱ እንጂ።'),
  ('6a2cc0ec-ae5a-5407-a9eb-aa0c91ce47a9', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 7, 7, 'ሄዳችሁም ‘መንግሥተ ሰማያት ቀርባለች፤’ ብላችሁ ስበኩ።'),
  ('d09044fb-41c9-5e2d-a191-482e9f687b27', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 8, 8, 'ድውዮችን ፈውሱ፤ ሙታንን አስነሡ፤ ለምጻሞችን አንጹ፤ አጋንንትን አውጡ፤ በከንቱ ተቀበላችሁ፤ በከንቱ ስጡ።'),
  ('97a444f2-eec0-5c82-ac2a-3f7c65c5a5d1', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 9, 9, 'ወርቅ ወይም ብር ወይም ናስ በመቀነታችሁ፥'),
  ('eb12399a-4928-588b-af3c-557c619b2942', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 10, 10, 'ወይም ለመንገድ ከረጢት ወይም ሁለት እጀ ጠባብ ወይም ጫማ ወይም በትር አትያዙ፤ ለሠራተኛ ምግቡ ይገባዋልና።'),
  ('a6c3c18a-0584-57fa-ad3a-14adfd74c6dc', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 11, 11, 'በምትገቡባትም በማናቸይቱም ከተማ ወይም መንደር፥ በዚያ የሚገባው ማን እንደ ሆነ በጥንቃቄ መርምሩ፤ እስክትወጡም ድረስ በዚያ ተቀመጡ።'),
  ('a1162e19-98b8-51f9-ac06-d4299919f323', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 12, 12, 'ወደ ቤትም ስትገቡ ሰላምታ ስጡ፤'),
  ('593f4a73-3b78-54e3-ab35-9056532d2bb3', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 13, 13, 'ቤቱም የሚገባው ቢሆን ሰላማችሁ ይድረስለት፤ ባይገባው ግን ሰላማችሁ ይመለስላችሁ።'),
  ('fe5e1192-3957-5b27-ab23-ea9fe8c53e5c', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 14, 14, 'ከማይቀበላችሁም ቃላችሁንም ከማይሰሙ ሁሉ፥ ከዚያ ቤት ወይም ከዚያች ከተማ ስትወጡ የእግራችሁን ትቢያ አራግፉ።'),
  ('5daa9a2d-4b7d-5a7f-a842-3b149ea6c50d', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '93c0555f-43e2-5042-abaf-cdfbefbf1952', 15, 15, 'እውነት እላችኋለሁ፤ በፍርድ ቀን ከዚያች ከተማ ይልቅ ለሰዶምና ለገሞራ አገር ይቀልላቸዋል።'),
  ('f6e2dcbe-4d95-5191-a0c1-04e20c3835af', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 1, 16, '“እነሆ እኔ እንደ በጎች በተኩላዎች መካከል እልካችኋለሁ፤ ስለዚህ እንደ እባብ ልባሞች እንደ ርግብም የዋሆች ሁኑ።'),
  ('34089c3b-9f38-5497-a401-244981f946c7', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 2, 17, 'ነገር ግን ወደ ሸንጎ አሳልፈው ይሰጡአችኋል፤ በምኩራቦቻቸውም ይገርፉአችኋልና ከሰዎች ተጠበቁ፤'),
  ('88ffa8ae-7113-54cc-a14a-70a94fd45124', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 3, 18, 'ለእነርሱና ለአሕዛብም ምስክር እንዲሆን፥ ስለ እኔ ወደ ገዥዎች ወደ ነገሥታትም ትወሰዳላችሁ።'),
  ('dafbaa81-1cfb-5b35-a15e-f0f14ce5eab2', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 4, 19, 'አሳልፈውም ሲሰጡአችሁ፥ የምትናገሩት በዚያች ሰዓት ይሰጣችኋልና እንዴት ወይስ ምን እንድትናገሩ አትጨነቁ፤'),
  ('aa53373f-80c7-55bf-aa6e-bfcbfcf93697', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 5, 20, 'በእናንተ የሚናገር የአባታችሁ መንፈስ ነው እንጂ፥ የምትናገሩ እናንተ አይደላችሁምና።'),
  ('42be5d43-74a0-51fd-ac48-e4a48e1e6625', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 6, 21, 'ወንድምም ወንድሙን፥ አባትም ልጁን ለሞት አሳልፎ ይሰጣል፤ ልጆችም በወላጆቻቸው ላይ ይነሣሉ፤ ይገድሉአቸውማል።'),
  ('93377d10-7202-5a5a-a88c-8931886451db', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 7, 22, 'በሁሉም ስለ ስሜ የተጠላችሁ ትሆናላችሁ፤ እስከ መጨረሻ የሚጸና ግን እርሱ ይድናል።'),
  ('0ba5ba34-58d9-5152-abd0-59764aa0de88', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 8, 23, 'በአንዲቱ ከተማም መከራ ቢያሳዩአችሁ ወደ ሌላይቱ ሽሹ፤ እውነት እላችኋለሁና፤ የሰው ልጅ እስኪመጣ ድረስ የእስራኤልን ከተማዎች አትዘልቁም።'),
  ('7ca22e05-3e3e-50ea-ae00-e43a2284b436', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 9, 24, '“ደቀ መዝሙር ከመምህሩ፥ ባሪያም ከጌታው አይበልጥም።'),
  ('bb4c1f88-22a5-599e-a364-aea73cf3b1dc', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 10, 25, 'ደቀ መዝሙር እንደ መምህሩ፥ ባሪያም እንደ ጌታው መሆኑ ይበቃዋል። ባለቤቱን ብዔል ዜቡል ካሉት፥ ቤተሰዎቹንማ እንዴት አብዝተው አይሉአቸው!'),
  ('57c1d3e9-58d0-5ff5-a690-f6507a2b8b2c', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 11, 26, '“እንግዲህ አትፍሩአቸው፤ የማይገለጥ የተከደነ፥ የማይታወቅም የተሰወረ ምንም የለምና።'),
  ('3cf8732f-6d80-5b08-a2e3-15e72d31d9b5', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 12, 27, 'በጨለማ የምነግራችሁን በብርሃን ተናገሩ፤ በጆሮም የምትሰሙትን በሰገነት ላይ ስበኩ።'),
  ('d0c4aa0a-b7f3-5e7f-a448-a59c23e2664c', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 13, 28, 'ሥጋንም የሚገድሉትን ነፍስን ግን መግደል የማይቻላቸውን አትፍሩ፤ ይልቅስ ነፍስንም ሥጋንም በገሃነም ሊያጠፋ የሚቻለውን ፍሩ።'),
  ('74dcc612-6d2d-5718-a142-cd34b1437492', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 14, 29, 'ሁለት ድንቢጦች በአምስት ሳንቲም ይሸጡ የለምን? ከእነርሱም አንዲቱ ያለ አባታችሁ ፈቃድ በምድር ላይ አትወድቅም።'),
  ('672fc263-8fe2-5b93-acf8-dd4371c84ae9', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 15, 30, 'የእናንተስ የራሳችሁ ጠጉር ሁሉ እንኳ ተቍኦጥሮአል።'),
  ('84ed51c3-9c6b-546c-aaaa-61003efef4b4', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 16, 31, 'እንግዲህ አትፍሩ ከብዙ ድንቢጦች እናንተ ትበልጣላችሁ።'),
  ('96859ece-1c93-577a-a117-ce1425576126', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 17, 32, 'ስለዚህ በሰው ፊት ለሚመሰክርልኝ ሁሉ እኔ ደግሞ በሰማያት ባለው በአባቴ ፊት እመሰክርለታለሁ፤'),
  ('2555b368-f6f8-57d5-a71d-53fc5b5c4242', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 18, 33, 'በሰው ፊትም የሚክደኝን ሁሉ እኔ ደግሞ በሰማያት ባለው በአባቴ ፊት እክደዋለሁ።'),
  ('349610a9-7d81-5227-a513-c5f95000bb68', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 19, 34, '“በምድር ላይ ሰላምን ለማምጣት የመጣሁ አይምሰላችሁ፤ ሰይፍን እንጂ ሰላምን ለማምጣት አልመጣሁም።'),
  ('e2cc328e-5a65-5faf-a08e-fdd0b1dbf7f2', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 20, 35, 'ሰውን ከአባቱ፥ ሴት ልጅንም ከእናትዋ፥ ምራትንም ከአማትዋ እለያይ ዘንድ መጥቻለሁና፤'),
  ('88e6ada3-619f-5710-aa09-34e71adeb233', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 21, 36, 'ለሰውም ቤተ ሰዎቹ ጠላቶች ይሆኑበታል።'),
  ('d823985a-2661-58d5-a932-e1ba0e9b8ff2', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 22, 37, 'ከእኔ ይልቅ አባቱን ወይም እናቱን የሚወድ ለእኔ ሊሆን አይገባውም፤ ከእኔ ይልቅም ወንድ ልጁን ወይም ሴት ልጁን የሚወድ ለእኔ ሊሆን አይገባውም።'),
  ('60a791b2-dbba-5d05-a136-4a8ed6c9c996', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 23, 38, 'መስቀሉንም የማይዝ በኋላዬም የማይከተለኝ ለእኔ ሊሆን አይገባውም።'),
  ('7b12ad71-4474-5273-ab99-f60414b20a38', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 24, 39, 'ነፍሱን የሚያገኝ ያጠፋታል፤ ነፍሱንም ስለ እኔ የሚያጠፋ ያገኛታል።'),
  ('18aa71f5-59de-5185-a8f3-e6dfdf3e46ef', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 25, 40, '“እናንተን የሚቀበል እኔን ይቀበላል፤ እኔንም የሚቀበል የላከኝን ይቀበላል።'),
  ('437e6312-a2f5-5b70-a0ce-f0e315069513', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 26, 41, 'ነቢይን በነቢይ ስም የሚቀበል የነቢይን ዋጋ ይወስዳል፤ ጻድቅንም በጻድቅ ስም የሚቀበል የጻድቁን ዋጋ ይወስዳል።'),
  ('ea2f0f65-59ad-5fec-a66b-a31d80d54c27', '65d1febc-7f27-5cf1-adea-4a98b0c25fb9', '0f328f95-5d92-504f-a273-8cde9f93dd86', 27, 42, 'ማንም ከእነዚህ ከታናናሾቹ ለአንዱ ቀዝቃዛ ጽዋ ውሃ ብቻ በደቀ መዝሙር ስም የሚያጠጣ፥ እውነት እላችኋለሁ፥ ዋጋው አይጠፋበትም።”'),
  ('31f11dd1-aa8d-50cd-ae43-a7a98534543c', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 1, 1, 'ኢየሱስም ዐሥራ ሁለቱን ደቀ መዛሙርቱን ማዘዝ በፈጸመ ጊዜ በከተሞቻቸው ሊያስተምርና ሊሰብክ ከዚያ አለፈ።'),
  ('21962eca-31f5-54b3-aee1-28a8e6893c95', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 2, 2, 'ዮሐንስም በወህኒ ሳለ የክርስቶስን ሥራ ሰምቶ ከደቀ መዛሙርቱ ሁለት ላከና'),
  ('90a09bf3-5d10-5df3-a5ad-4e69256f928f', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 3, 3, '“የሚመጣው አንተ ነህን? ወይስ ሌላ እንጠብቅ?” አለው።'),
  ('f41e0be8-25f3-5c1c-a8d6-cedcda8a00ff', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 4, 4, 'ኢየሱስም መልሶ እንዲህ አላቸው “ሄዳችሁ ያያችሁትን የሰማችሁትንም ለዮሐንስ ንገሩት፤'),
  ('522bd8e8-b4bb-5805-adce-8936f053f0b2', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 5, 5, 'ዕውሮች ያያሉ፤ አንካሶችም ይሄዳሉ፤ ለምጻሞችም ይነጻሉ፤ ደንቆሮችም ይሰማሉ፤ ሙታንም ይነሣሉ፤'),
  ('28caf581-353f-5755-a534-cfafbb7ccb9f', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 6, 6, 'ለድሆችም ወንጌል ይሰበካል፤ በእኔም የማይሰናከለው ሁሉ ብፁዕ ነው።”'),
  ('8f202f80-0907-5cc0-a454-cbd25c8d68c9', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 7, 7, 'እነዚያም ሲሄዱ ኢየሱስ ለሕዝቡ ስለ ዮሐንስ ሊናገር ጀመረ እንዲህም አለ “ምን ልታዩ ወደ ምድረ በዳ ወጣችሁ?'),
  ('905139a3-1eca-5dda-a93f-46bc5f384990', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 8, 8, 'ነፋስ የሚወዘውዘውን ሸምበቆን? ወይስ ምን ልታዩ ወጣችሁ? ቀጭን ልብስ የለበሰ ሰውን? እነሆ ቀጭን ልብስ የለበሱ በነገሥታት ቤት አሉ።'),
  ('ce18f89b-e524-5626-a259-0f5bfc936293', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 9, 9, 'ወይስ ምን ልታዩ ወጣችሁ? ነቢይን? አዎን እላችኋለሁ፥ ከነቢይም የሚበልጠውን።'),
  ('8c1455b2-ccd0-536e-ab44-39b9945d590d', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 10, 10, '‘እነሆ መንገድህን በፊትህ የሚጠርግ'),
  ('cdedcecb-30c8-5a4f-a004-25743c9d7890', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 11, 16, 'ነገር ግን “ይህን ትውልድ በምን እመስለዋለሁ? በገበያ የሚቀመጡትን ልጆች ይመስላሉ፤ እነርሱም ባልንጀሮቻቸውን እየጠሩ'),
  ('d8590b49-c5f1-5c90-a40d-583c13f9d4da', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 12, 17, '‘እንቢልታ ነፋንላችሁ ዘፈንም አልዘፈናችሁም ሙሾ አወጣንላችሁ፤ ዋይ ዋይም አላላችሁም’ ይሉአቸዋል።'),
  ('29c51db6-3dae-5385-aa0a-e964db140580', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 13, 18, 'ዮሐንስ ሳይበላና ሳይጠጣ መጣ፤ እነርሱም ‘ጋኔን አለበት’ አሉት።'),
  ('a3e76db2-af2c-5b2d-aab8-51432cf6cf93', '3121d784-8542-5071-a778-a3cd3caf2674', '323dd9b0-2a25-553e-a6e2-a238cdb2e851', 14, 19, 'የሰው ልጅ እየበላና እየጠጣ መጣ፤ እነርሱም ‘እነሆ በላተኛና የወይን ጠጅ ጠጭ፥ የቀራጮችና የኀጢአተኞች ወዳጅ’ ይሉታል። ጥበብም በልጆችዋ ጸደቀች።”'),
  ('a7eaee60-b2c7-5222-a257-763bc269c04c', '3121d784-8542-5071-a778-a3cd3caf2674', 'f5fe834e-48fe-5b08-a2af-aaa18e9d0bf5', 1, 20, 'በዚያን ጊዜ የሚበዙ ተአምራት የተደረገባቸውን ከተማዎች ንስሐ ስላልገቡ ሊነቅፋቸው ጀመረ እንዲህም አለ'),
  ('8dfb617e-0736-50fe-a33c-3cec0654f387', '3121d784-8542-5071-a778-a3cd3caf2674', 'f5fe834e-48fe-5b08-a2af-aaa18e9d0bf5', 2, 21, '“ወዮልሽ ኮራዚ! ወዮልሽ ቤተ ሳይዳ! በእናንተ የተደረገው ተአምራት በጢሮስና በሲዶና ተደርጎ ቢሆን፥ ማቅ ለብሰው አመድም ነስንሰው ከብዙ ጊዜ በፊት ንስሐ በገቡ ነበርና።'),
  ('902afced-9c2f-5043-aa7c-80033e344e52', '3121d784-8542-5071-a778-a3cd3caf2674', 'f5fe834e-48fe-5b08-a2af-aaa18e9d0bf5', 3, 22, 'ነገር ግን እላችኋለሁ፤ በፍርድ ቀን ከእናንተ ይልቅ ለጢሮስና ለሲዶና ይቀልላቸዋል።'),
  ('9a0c616d-bd78-5084-aef4-8125c30ad237', '3121d784-8542-5071-a778-a3cd3caf2674', 'f5fe834e-48fe-5b08-a2af-aaa18e9d0bf5', 4, 23, 'አንቺም ቅፍርናሆም፥ እስከ ሰማይ ከፍ አልሽን? ወደ ሲኦል ትወርጃለሽ፤ በአንቺ የተደረገው ተአምራት በሰዶም ተደርጎ ቢሆን፥ እስከ ዛሬ በኖረች ነበርና።'),
  ('e06bb785-e456-5e06-ad00-f0c39716a172', '3121d784-8542-5071-a778-a3cd3caf2674', 'f5fe834e-48fe-5b08-a2af-aaa18e9d0bf5', 5, 24, 'ነገር ግን እላችኋለሁ፤ በፍርድ ቀን ከአንቺ ይልቅ ለሰዶም አገር ይቀልላታል።”'),
  ('c6e46bd5-4e28-517a-a1cc-e9a02d612d34', '3121d784-8542-5071-a778-a3cd3caf2674', 'f5fe834e-48fe-5b08-a2af-aaa18e9d0bf5', 6, 25, 'በዚያን ጊዜ ኢየሱስ መልሶ እንዲህ አለ “አባት ሆይ! የሰማይና የምድር ጌታ፥ ይህን ከጥበበኞችና ከአስተዋዮች ሰውረህ ለሕፃናት ስለ ገለጥህላቸው አመሰግንሃለሁ።'),
  ('ebf330a4-081b-5503-af79-4df2636c6324', '3121d784-8542-5071-a778-a3cd3caf2674', 'f5fe834e-48fe-5b08-a2af-aaa18e9d0bf5', 7, 26, 'አዎን አባት ሆይ! ፈቃድህ በፊትህ እንዲህ ሆኖአልና።'),
  ('b81f52a2-44f6-5353-a067-52ed3840c27c', '3121d784-8542-5071-a778-a3cd3caf2674', 'f5fe834e-48fe-5b08-a2af-aaa18e9d0bf5', 8, 27, 'ሁሉ ከአባቴ ዘንድ ተሰጥቶኛል፤ ከአብ በቀር ወልድን የሚያውቅ የለም፤ ከወልድም በቀር ወልድም ሊገለጥለት ከሚፈቅድ በቀር አብን የሚያውቅ የለም።'),
  ('0b5fc633-7733-5828-aaad-b1f78db3996a', '3121d784-8542-5071-a778-a3cd3caf2674', 'f5fe834e-48fe-5b08-a2af-aaa18e9d0bf5', 9, 28, 'እናንተ ደካሞች ሸክማችሁ የከበደ ሁሉ ወደ እኔ ኑ፤ እኔም አሳርፋችኋለሁ።'),
  ('3d9db38a-3ed1-53dc-a460-de7e1b9353c6', '3121d784-8542-5071-a778-a3cd3caf2674', 'f5fe834e-48fe-5b08-a2af-aaa18e9d0bf5', 10, 29, 'ቀንበሬን በላያችሁ ተሸከሙ፤ ከእኔም ተማሩ፤ እኔ የዋህ በልቤም ትሑት ነኝና፤ ለነፍሳችሁም ዕረፍት ታገኛላችሁ፤'),
  ('3138ff4e-89c9-5815-a26f-a0f065b95290', '3121d784-8542-5071-a778-a3cd3caf2674', 'f5fe834e-48fe-5b08-a2af-aaa18e9d0bf5', 11, 30, 'ቀንበሬ ልዝብ፤ ሸክሜም ቀሊል ነውና።”'),
  ('7ed75f18-f222-54c0-aa33-c5cd900e5c42', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '0d70bc89-37a3-51fd-a94c-b0ac0421fe2f', 1, 1, 'በዚያን ጊዜ ኢየሱስ በሰንበት ቀን በእርሻ መካከል አለፈ፤ ደቀ መዛሙርቱም ተራቡና እሸት ይቀጥፉ ይበሉም ጀመር።'),
  ('ff071126-c491-5458-a6fc-0d779f28b3ce', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '0d70bc89-37a3-51fd-a94c-b0ac0421fe2f', 2, 2, 'ፈሪሳውያንም አይተው “እነሆ ደቀ መዛሙርትህ በሰንበት ማድረግ ያልተፈቀደውን ያደርጋሉ፤” አሉት።'),
  ('c3b2c846-270d-5631-a955-f26bf537dfa1', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '0d70bc89-37a3-51fd-a94c-b0ac0421fe2f', 3, 3, 'እርሱ ግን እንዲህ አላቸው “ዳዊትና ከእርሱ ጋር የነበሩት በተራቡ ጊዜ፥ እርሱ ያደረገውን፥ ወደ እግዚአብሔር ቤት እንደ ገባ ካህናትም ብቻ እንጂ እርሱና ከእርሱ ጋር የነበሩት ሊበሉት ያልተፈቀደውን የመሥዋዕቱን ኅብስት እንደ በላ አላነበባችሁምን?'),
  ('42a37583-c4f0-5a85-a5e1-a04c7221fe80', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '0d70bc89-37a3-51fd-a94c-b0ac0421fe2f', 4, 5, 'ካህናትም በሰንበት በመቅደስ ሰንበትን እንዲያረክሱ ኀጢአትም እንዳይሆንባቸው በሕጉ አላነበባችሁምን?'),
  ('bbecb587-d327-5591-a3dc-eea7711e005d', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '0d70bc89-37a3-51fd-a94c-b0ac0421fe2f', 5, 6, 'ነገር ግን እላችኋለሁ፤ ከመቅደስ የሚበልጥ ከዚህ አለ።'),
  ('0ef2a363-8c14-58ba-a3db-915b1aac9c33', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '0d70bc89-37a3-51fd-a94c-b0ac0421fe2f', 6, 7, '‘ምሕረትን እወዳለሁ፤ መሥዋዕትንም አይደለም፤’ ያለው ምን እንደሆነ ብታውቁስ ኀጢአት የሌለባቸውን ባልኵኦነናችሁም ነበር።'),
  ('24ea4caa-da8b-51ab-a66c-32406ad610b7', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '0d70bc89-37a3-51fd-a94c-b0ac0421fe2f', 7, 8, 'የሰው ልጅ የሰንበት ጌታ ነውና።”'),
  ('96ea2f7f-56fd-55b6-a103-694415bcd546', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 1, 9, 'ከዚያም አልፎ ወደ ምኩራባቸው ገባ።'),
  ('4ed27761-3224-5b83-afba-7d0c5c00f52d', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 2, 10, 'እነሆም እጁ የሰለለች ሰው ነበረ፤ ይከሱትም ዘንድ “በሰንበት መፈወስ ተፈቅዶአልን?” ብለው ጠየቁት።'),
  ('ed04ece4-f9c9-554a-a2e4-f9356fe17603', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 3, 11, 'እርሱ ግን “ከእናንተ አንድ በግ ያለው በሰንበት በጉድጓድ ቢወድቅበት፥ ይዞ የማያወጣው ሰው ማን ነው?'),
  ('b6444713-29b2-5972-a00b-96161902b6a3', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 4, 12, 'እንግዲህ ሰው ከበግ ይልቅ እንደምን አይበልጥም! ስለዚህ በሰንበት መልካም መሥራት ተፈቅዶአል፤” አላቸው።'),
  ('2d28f848-531f-5513-a2af-13f2456a1dd8', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 5, 13, 'ከዚያም በኋላ ሰውየውን “እጅህን ዘርጋ፤” አለው። ዘረጋትም፤ እንደ ሁለተኛይቱም ደህና ሆነች።'),
  ('6441d360-0b9a-5032-a568-7cb5f45d1f64', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 6, 14, 'ፈሪሳውያን ግን ወጥተው እንዴት አድርገው እንዲያጠፉት ተማከሩበት።'),
  ('f30fb653-b515-5bbd-ab97-2695b1b68360', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 7, 15, 'ኢየሱስም አውቆ ከዚያ ፈቀቅ አለ። ብዙ ሰዎችም ተከተሉት፤ ሁሉንም ፈወሳቸው፤ እንዳይገልጡትም አዘዛቸው፤'),
  ('63ba3383-a901-5937-a6c4-1ec0589dcf2b', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 8, 16, 'በነቢዩ በኢሳይያስ የተባለው ይፈጸም ዘንድ እንዲህ ሲል'),
  ('dbacbe94-c21d-5c1a-aa33-8cb8d1dbc9f6', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 9, 18, '“እነሆ የመረጥሁት ብላቴናዬ፥'),
  ('1e90103f-36d5-52ff-ae7f-823e998dfab1', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 10, 19, 'አይከራከርም፤ አይጮህምም፤'),
  ('240ff227-5022-5073-a9ea-635852472ca5', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 11, 20, 'ፍርድን ድል ለመንሣት እስኪያወጣ፥'),
  ('401f998c-ca1a-549e-a9c2-6df6f14c3dbe', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', 'eff79522-87fc-534f-aa50-45348237de39', 12, 21, 'አሕዛብም በስሙ ተስፋ ያደርጋሉ።”'),
  ('0ceedfbe-d972-550d-a9e1-51d9ecd7649f', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 1, 22, 'ከዚህም በኋላ ጋኔን ያደረበትን ዕውር ድዳም ወደ እርሱ አመጡ፤ ዕውሩም ዲዳውም እስኪያይና እስኪናገር ድረስ ፈወሰው።'),
  ('224bb490-89dc-5e1a-aa1f-7fa0d7bea179', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 2, 23, 'ሕዝቡም ሁሉ ተገረሙና “እንጃ ይህ ሰው የዳዊት ልጅ ይሆንን?” አሉ።'),
  ('a83ac568-a1a6-5a7a-a2d6-f7e8348db5fd', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 3, 24, 'ፈሪሳውያን ግን ሰምተው “ይህ በብዔል ዜቡል በአጋንንት አለቃ ካልሆነ በቀር አጋንንትን አያወጣም፤” አሉ።'),
  ('c1261fcc-f70c-5a60-a6f2-8067438caafb', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 4, 25, 'ኢየሱስ ግን አሳባቸውን አውቆ እንዲህ አላቸው “እርስ በርስዋ የምትለያይ መንግሥት ሁላ ትጠፋለች፤” እርስ በርሱ የሚለያይ ከተማም ሁሉ ወይም ቤት አይቆምም።'),
  ('95e58b66-3f24-54f1-a44b-43110e96c1f4', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 5, 26, 'ሰይጣንም ሰይጣንን የሚያወጣ ከሆነ፥ እርስ በርሱ ተለያየ፤ እንግዲህ መንግሥቱ እንዴት ትቆማለች?'),
  ('721dacd7-bb57-5765-ab78-5908c34346a0', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 6, 27, 'እኔስ በብዔል ዜቡል አጋንንትን የማወጣ ከሆንሁ፥ ልጆቻችሁ በማን ያወጡአቸዋል? ስለዚህ እነርሱ ፈራጆች ይሆኑባችኋል።'),
  ('41264635-dddf-5b32-abab-770ceef28d91', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 7, 28, 'እኔ ግን በእግዚአብሔር መንፈስ አጋንንትን የማወጣ ከሆንሁ፥ እንግዲህ የእግዚአብሔር መንግሥት ወደ እናንተ ደርሳለች።'),
  ('7710cc08-1d84-5ff3-aedf-0dfbcd6d7e97', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 8, 29, 'ወይስ ሰው አስቀድሞ ኃይለኛውን ሳያስር ወደ ኃይለኛው ቤት ገብቶ እቃውን ሊነጥቀው እንዴት ይችላል? ከዚያም ወዲያ ቤቱን ይበዘብዛል።'),
  ('4a1d087b-d0f7-56af-a67b-c74679abc495', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 9, 30, 'ከእኔ ጋር ያልሆነ ይቃወመኛል፤ ከእኔ ጋርም የማያከማች ይበትናል።'),
  ('9bfabb2f-72cc-5f00-ac76-e1944b435a1b', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 10, 31, 'ስለዚህ እላችኋለሁ፤ ኀጢአትና ስድብ ሁሉ ለሰዎች ይሰረይላቸዋል፤ ነገር ግን መንፈስ ቅዱስን ለሰደበ አይሰረይለትም።'),
  ('6cb44210-c211-5c77-a8da-7cd47d0c04ca', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 11, 32, 'በሰው ልጅ ላይ ቃል የሚናገር ሁሉ ይሰረይለታል፤ በመንፈስ ቅዱስ ላይ ግን የሚናገር ሁሉ በዚህ ዓለም ቢሆን ወይም በሚመጣው አይሰረይለትም።'),
  ('e14c1499-a9a5-5330-a3cb-b396726bf288', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 12, 33, '“ዛፍ ከፍሬዋ ትታወቃለችና ዛፍዋን መልካም፥ ፍሬዋንም መልካም አድርጉ፤ ወይም ዛፍዋን ክፉ ፍሬዋንም ክፉ አድርጉ።'),
  ('6d6d0466-f62f-5362-af90-71d6c2b4da77', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 13, 34, 'እናንተ የእፉኝት ልጆች፥ ክፉዎች ስትሆኑ መልካም ለመናገር እንዴት ትችላላችሁ? በልብ ሞልቶ ከተረፈው አፍ ይናገራልና።'),
  ('7d4659d5-2b2c-529f-aacc-6e7bb98785bd', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 14, 35, 'መልካም ሰው ከልቡ መልካም መዝገብ መልካም ነገርን ያወጣል፤ ክፉ ሰውም ከክፉ መዝገብ ክፉ ነገርን ያወጣል።'),
  ('597ef87e-4c9e-5d14-ae2e-c6f371e77d18', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 15, 36, 'እኔ እላችኋለሁ፥ ሰዎች ስለሚናገሩት ስለ ከንቱ ነገር ሁሉ በፍርድ ቀን መልስ ይሰጡበታል፤'),
  ('863bc045-0b7b-5ea5-a966-345d4cae432a', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '94b8f145-72bb-5a55-aaa2-fcf6cbd1d211', 16, 37, 'ከቃልህ የተነሣ ትጸድቃለህና ከቃልህም የተነሣ ትኰነናለህ።”'),
  ('0606cde8-9623-5dd3-ac55-3b6bca99b03b', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '21b4f8c0-1540-54e7-a786-f5f805bf63e3', 1, 38, 'በዚያን ጊዜ ከጻፎችና ከፈሪሳውያን አንዳንዶቹ መለሱና “መምህር ሆይ! ከአንተ ምልክት እንድናይ እንወዳለን፤” አሉ።'),
  ('6a4eea80-f8d2-5f56-a2c6-55f8b3e471e8', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '21b4f8c0-1540-54e7-a786-f5f805bf63e3', 2, 39, 'እርሱ ግን መልሶ እንዲህ አላቸው “ክፉና አመንዝራ ትውልድ ምልክት ይሻል፤ ከነቢዩም ከዮናስ ምልክት በቀር ምልክት አይሰጠውም።'),
  ('c6bc6066-9cf8-577d-ad9e-3067d91d1301', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '21b4f8c0-1540-54e7-a786-f5f805bf63e3', 3, 40, 'ዮናስ በዓሣ አንባሪ ሆድ ሦስት ቀንና ሦስት ሌሊት እንደ ነበረ፥ እንዲሁ የሰው ልጅ በምድር ልብ ሦስት ቀንና ሦስት ሌሊት ይኖራል።'),
  ('32ea2a38-358f-5aed-ad0d-8ac0c9d3747e', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '21b4f8c0-1540-54e7-a786-f5f805bf63e3', 4, 41, 'የነነዌ ሰዎች በፍርድ ቀን ከዚህ ትውልድ ጋር ተነሥተው ይፈርዱበታል፤ በዮናስ ስብከት ንስሐ ገብተዋልና፤ እነሆም ከዮናስ የሚበልጥ ከዚህ አለ።'),
  ('25d83ccf-f17a-5200-a902-ed14afd54dc9', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '21b4f8c0-1540-54e7-a786-f5f805bf63e3', 5, 42, 'ንግሥተ ዓዜብ በፍርድ ቀን ከዚህ ትውልድ ጋር ተነሥታ ትፈርድበታለች፤ የሰሎሞንን ጥበብ ለመስማት ከምድር ዳር መጥታለችና፤ እነሆም ከሰሎሞን የሚበልጥ ከዚህ አለ።'),
  ('160130d2-42ac-5116-aa22-c39fe8edce72', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '39b812fe-1e20-59e5-a888-55b2e3021371', 1, 43, '“ርኩስ መንፈስ ግን ከሰው በወጣ ጊዜ፥ ዕረፍት እየፈለገ ውሃ በሌለበት ቦታ ያልፋል፤ አያገኝምም።'),
  ('6cf06f0f-f973-5d71-a0a2-106268b2030d', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '39b812fe-1e20-59e5-a888-55b2e3021371', 2, 44, 'በዚያን ጊዜም ‘ወደ ወጣሁበት ቤቴ እመለሳለሁ፤’ ይላል፤ ቢመጣም ባዶ ሆኖ ተጠርጎና አጊጦ ያገኘዋል።'),
  ('59c3dd5f-032d-570d-a949-40b3dbdc68f9', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '39b812fe-1e20-59e5-a888-55b2e3021371', 3, 45, 'ከዚያ ወዲያ ይሄድና ከእርሱ የከፉትን ሰባት ሌሎችን አጋንንት ከእርሱ ጋር ይወስዳል፤ ገብተውም በዚያ ይኖራሉ፤ ለዚያም ሰው ከፊተኛው ይልቅ የኋለኛው ይብስበታል። ለዚህ ክፉ ትውልድ ደግሞ እንዲሁ ይሆንበታል።”'),
  ('e60e7903-8444-56d9-a892-d93fd91afa06', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '39b812fe-1e20-59e5-a888-55b2e3021371', 4, 46, 'ገናም ለሕዝቡ ሲናገር፥ እነሆ፥ እናቱና ወንድሞቹ ሊነጋገሩት ፈልገው በውጭ ቆመው ነበር።'),
  ('8b22ce76-be34-5fe0-ab8c-b5afbb6ae0c5', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '39b812fe-1e20-59e5-a888-55b2e3021371', 5, 47, 'አንዱም “እነሆ እናትህና ወንድሞችህ ሊነጋገሩህ ፈልገው በውጭ ቆመዋል፤” አለው።'),
  ('58a86976-7234-5737-ac19-50d3a5f54234', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '39b812fe-1e20-59e5-a888-55b2e3021371', 6, 48, 'እርሱ ግን ለነገረው መልሶ “እናቴ ማን ናት? ወንድሞቼስ እነማን ናቸው?” አለው።'),
  ('14637661-c2f1-589f-a6b7-a25ab9805650', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '39b812fe-1e20-59e5-a888-55b2e3021371', 7, 49, 'እጁንም ወደ ደቀ መዛሙርቱ ዘርግቶ “እነሆ እናቴና ወንድሞቼ፤'),
  ('44480942-7a8f-5e3d-ac06-88f2cb473a01', '4d02fab7-ae9b-5107-a92b-a38bc7cc3bdf', '39b812fe-1e20-59e5-a888-55b2e3021371', 8, 50, 'በሰማያት ያለውን የአባቴን ፈቃድ የሚያደርግ ሁሉ፥ እርሱ ወንድሜ እኅቴም እናቴም ነውና፤” አለ።'),
  ('c8f4f60a-b315-5e4f-a3f3-213630c655c0', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 1, 1, 'በዚያን ቀን ኢየሱስ ከቤት ወጥቶ በባሕር አጠገብ ተቀመጠ፤'),
  ('7f0982eb-4bb2-57e1-a191-9543bf9c1aba', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 2, 2, 'እርሱም በታንኳ ገብቶ እስኪቀመጥ ድረስ ብዙ ሰዎች ወደ እርሱ ተሰበሰቡ፤ ሕዝቡም ሁሉ በወደቡ ቆመው ነበር።'),
  ('d0fdd16c-92cf-52a8-adc6-3705f764f97d', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 3, 3, 'በምሳሌም ብዙ ነገራቸው እንዲህም አላቸው “እነሆ ዘሪ ሊዘራ ወጣ።'),
  ('ca9107b4-dee4-529f-ad8c-9a9d92d7d66c', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 4, 4, 'እርሱም ሲዘራ አንዳንዱ በመንገድ ዳር ወደቀ፤ ወፎችም መጥተው በሉት።'),
  ('37ab7e8e-d922-5886-a808-25f5a852dffd', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 5, 5, 'ሌላውም ብዙ መሬት በሌለበት በጭንጫ ላይ ወደቀ፤ ጥልቅ መሬትም ስላልነበረው ወዲያው በቀለ፤'),
  ('097f1fd8-6b07-5355-a84f-5849e84bb446', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 6, 6, 'ፀሐይ በወጣ ጊዜ ግን ጠወለገ፥ ሥርም ስላልነበረው ደረቀ።'),
  ('ba7ef121-7025-50f5-a6d4-08c1f9510c75', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 7, 7, 'ሌላውም በእሾህ መካከል ወደቀ፤ እሾህም ወጣና አነቀው።'),
  ('a3a8cae0-b85e-53ee-a421-fb3e08db2432', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 8, 8, 'ሌላውም በመልካም መሬት ወደቀ፤ አንዱም መቶ፥ አንዱም ስድሳ፥ አንዱም ሠላሳ ፍሬ ሰጠ።'),
  ('0b53e8d3-46f6-512c-ae1e-d65a0f415f42', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 9, 9, 'የሚሰማ ጆሮ ያለው ይስማ።”'),
  ('c9464002-2315-582d-a84a-2e1211d51268', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 10, 10, 'ደቀ መዛሙርቱም ቀርበው “ስለ ምን በምሳሌ ትነግራቸዋለህ?” አሉት።'),
  ('d18a2a9b-0e5a-55cb-a5a8-21454adfeda5', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 11, 11, 'እርሱም መልሶ እንዲህ አላቸ “ለእናንተ የመንግሥተ ሰማያትን ምሥጢር ማወቅ ተሰጥቶአችኋል፤ ለእነርሱ ግን አልተሰጣቸውም።'),
  ('26335b2e-e7c9-56f7-a718-bb8d0c6a67b2', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 12, 12, 'ላለው ይሰጠዋልና ይበዛለትማል፤ ከሌለው ግን ያው ያለው እንኳ ይወሰድበታል።'),
  ('2a0b91b7-0bba-5292-a687-6c4a5265e7f4', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 13, 13, 'ስለዚህ እያዩ ስለማያዩ እየሰሙም ስለማይሰሙ ስለማያስተውሉም በምሳሌ እነግራቸዋለሁ።'),
  ('b896497d-ae6c-58e5-acae-546010e6fa8f', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 14, 14, '‘መስማት ትሰማላችሁና አታስተውሉም፤'),
  ('61654d0f-3733-59cb-a3ca-d2924f4b1c47', 'd5877eec-3840-5163-a157-4ad9af8520da', '0001a997-a3db-5583-ac85-38623c1347f7', 15, 15, 'በዐይናቸው እንዳያዩ፥ በጆሮአቸውም እንዳይሰሙ፥'),
  ('bf0f9baa-3281-568c-a815-a8f743adc0fc', 'd5877eec-3840-5163-a157-4ad9af8520da', '25031906-e4d8-5d97-ac69-125f6e7e8a73', 1, 18, '“እንግዲህ እናንተ የዘሪውን ምሳሌ ስሙ።'),
  ('2b7c43c1-de98-519a-a33d-fae4abe2b6cd', 'd5877eec-3840-5163-a157-4ad9af8520da', '25031906-e4d8-5d97-ac69-125f6e7e8a73', 2, 19, 'የመንግሥትን ቃል ሰምቶ በማያስተውል ሁሉ፥ ክፉው ይመጣል፤ በልቡ የተዘራውንም ይነጥቃል፤ በመንገድ ዳር የተዘራው ይህ ነው።'),
  ('a3c5fe85-3022-5605-a647-65508862eade', 'd5877eec-3840-5163-a157-4ad9af8520da', '25031906-e4d8-5d97-ac69-125f6e7e8a73', 3, 20, 'በጭንጫ ላይ የተዘራውም ይህ ቃሉን ሰምቶ ወዲያው በደስታ የሚቀበለው ነው፤'),
  ('c53ae174-130f-5c59-ad46-b6efd90f00e9', 'd5877eec-3840-5163-a157-4ad9af8520da', '25031906-e4d8-5d97-ac69-125f6e7e8a73', 4, 21, 'ነገር ግን ለጊዜው ነው እንጂ በእርሱ ሥር የለውም፤ በቃሉ ምክንያትም መከራ ወይም ስደት በሆነ ጊዜ ወዲያው ይሰናከላል።'),
  ('34a31181-5ff0-555e-af82-d6cb8a852ef8', 'd5877eec-3840-5163-a157-4ad9af8520da', '25031906-e4d8-5d97-ac69-125f6e7e8a73', 5, 22, 'በእሾህ መካከል የተዘራውም ይህ ቃሉን የሚሰማ ነው፤ የዚህም ዓለም አሳብና የባለጠግነት መታለል ቃሉን ያንቃል፤ የማያፈራም ይሆናል።'),
  ('36f8dfd5-6cc2-582b-a031-09287957eebb', 'd5877eec-3840-5163-a157-4ad9af8520da', '25031906-e4d8-5d97-ac69-125f6e7e8a73', 6, 23, 'በመልካም መሬት የተዘራውም ይህ ቃሉን ሰምቶ የሚያስተውል ነው፤ እርሱም ፍሬ ያፈራል፤ አንዱም መቶ አንዱም ስድሳ አንዱም ሠላሳ ያደርጋል።”'),
  ('da906bc2-ca8a-5088-abd8-ad0ec6724c4a', 'd5877eec-3840-5163-a157-4ad9af8520da', '516aecbe-f622-55a7-a2a3-c15fcbcd06e2', 1, 24, 'ሌላ ምሳሌ አቀረበላቸው፤ እንዲህም አለ “መንግሥተ ሰማያት በእርሻው መልካም ዘርን የዘራን ሰው ትመስላለች።'),
  ('33ce1e6a-bb19-5297-a226-f3192122e70f', 'd5877eec-3840-5163-a157-4ad9af8520da', '516aecbe-f622-55a7-a2a3-c15fcbcd06e2', 2, 25, 'ሰዎቹ ሲተኙ ግን ጠላቱ መጣና በስንዴው መካከል እንክርዳድን ዘርቶ ሄደ።'),
  ('297bd441-ba30-50d1-a0f6-c842ca262c66', 'd5877eec-3840-5163-a157-4ad9af8520da', '516aecbe-f622-55a7-a2a3-c15fcbcd06e2', 3, 26, 'ስንዴውም በበቀለና በአፈራ ጊዜ እንክርዳዱ ደግሞ ያን ጊዜ ታየ።'),
  ('29ec9328-6224-5756-a651-99261fc5d881', 'd5877eec-3840-5163-a157-4ad9af8520da', '516aecbe-f622-55a7-a2a3-c15fcbcd06e2', 4, 27, 'የባለቤቱም ባሮች ቀርበው ‘ጌታ ሆይ! መልካምን ዘር በእርሻህ ዘርተህ አልነበርህምን? እንክርዳዱንስ ከወዴት አገኘ?’ አሉት።'),
  ('4ee9684c-2435-5fbf-a4d2-152311bc6e80', 'd5877eec-3840-5163-a157-4ad9af8520da', '516aecbe-f622-55a7-a2a3-c15fcbcd06e2', 5, 28, 'እርሱም ‘ጠላት ይህን አደረገ፤’ አላቸው። ባሮቹም ‘እንግዲህ ሄደን ብንለቅመው ትወዳለህን?’ አሉት።'),
  ('396af4d9-075f-5d6d-ad3e-17084c8a0050', 'd5877eec-3840-5163-a157-4ad9af8520da', '516aecbe-f622-55a7-a2a3-c15fcbcd06e2', 6, 29, 'እርሱ ግን ‘እንክርዳዱን ስትለቅሙ ስንዴውን ከእርሱ ጋር እንዳትነቅሉት አይሆንም።'),
  ('0153c1e4-8cef-5363-a6e2-fa506f107918', 'd5877eec-3840-5163-a157-4ad9af8520da', '516aecbe-f622-55a7-a2a3-c15fcbcd06e2', 7, 30, 'ተዉአቸው፤ እስከ መከር ጊዜ አብረው ይደጉ፤ በመከር ጊዜም አጫጆችን “እንክርዳዱን አስቀድማችሁ ልቀሙ በእሳትም ለማቃጠል በየነዶው እሰሩ፤ ስንዴውን ግን በጎተራዬ ክተቱ፤” እላለሁ’ አለ።”'),
  ('a638ab21-f18b-5efd-a899-9437d15e653b', 'd5877eec-3840-5163-a157-4ad9af8520da', 'db0c86f4-9ca1-5d58-a9b0-60b900fd52f5', 1, 31, 'ሌላ ምሳሌ አቀረበላቸው፤ እንዲህም አለ “መንግሥተ ሰማያት ሰው ወስዶ በእርሻው የዘራትን የሰናፍጭ ቅንጣት ትመስላለች፤'),
  ('b6761627-d188-53e6-a1fb-720e10650291', 'd5877eec-3840-5163-a157-4ad9af8520da', 'db0c86f4-9ca1-5d58-a9b0-60b900fd52f5', 2, 32, 'እርስዋም ከዘር ሁሉ ታንሳለች፤ በአደገች ጊዜ ግን፥ ከአታክልቶች ትበልጣለች የሰማይም ወፎች መጥተው በቅርንጫፎችዋ እስኪሰፍሩ ድረስ ዛፍ ትሆናለች።”'),
  ('6b08101c-a515-59b5-ae7e-aeaa4ec66e85', 'd5877eec-3840-5163-a157-4ad9af8520da', 'db0c86f4-9ca1-5d58-a9b0-60b900fd52f5', 3, 33, 'ሌላ ምሳሌ ነገራቸው፤ እንዲህም አለ “መንግሥተ ሰማያት ሁሉ እስኪቦካ ድረስ ሴት ወስዳ በሦስት መስፈሪያ ዱቄት የሸሸገችውን እርሾ ትመስላለች።”'),
  ('2812fc6e-2e56-5180-ab0f-3259b20f94ef', 'd5877eec-3840-5163-a157-4ad9af8520da', 'db0c86f4-9ca1-5d58-a9b0-60b900fd52f5', 4, 34, 'ኢየሱስም ለሕዝቡ ይህን ሁሉ በምሳሌ ተናገረ፤ በነቢዩም'),
  ('b09561b5-55e4-5ffa-a803-35d567c975ab', 'd5877eec-3840-5163-a157-4ad9af8520da', 'df20c3d2-338a-59d6-a8d8-0cadb04c6e6e', 1, 36, 'በዚያን ጊዜ ሕዝቡን ትቶ ወደ ቤት ገባ። ደቀ መዛሙርቱም ወደ እርሱ ቀርበው “የእርሻውን እንክርዳድ ምሳሌ ተርጕምልን፤” አሉት።'),
  ('1107f488-4363-5a17-a3b4-fdebfe0f7c97', 'd5877eec-3840-5163-a157-4ad9af8520da', 'df20c3d2-338a-59d6-a8d8-0cadb04c6e6e', 2, 37, 'እርሱም መልሶ እንዲህ አላቸው “መልካምን ዘር የዘራው የሰው ልጅ ነው፤ እርሻውም ዓለም ነው፤'),
  ('57cc3d7b-6d8c-5c2d-a8cf-d0b122bc94d1', 'd5877eec-3840-5163-a157-4ad9af8520da', 'df20c3d2-338a-59d6-a8d8-0cadb04c6e6e', 3, 38, 'መልካሙም ዘር የመንግሥት ልጆች ናቸው፤'),
  ('a43e0c22-8e44-5982-a9cf-bd24380ea893', 'd5877eec-3840-5163-a157-4ad9af8520da', 'df20c3d2-338a-59d6-a8d8-0cadb04c6e6e', 4, 39, 'እንክርዳዱም የክፉው ልጆች ናቸው፤ የዘራውም ጠላት ዲያብሎስ ነው፤ መከሩም የዓለም መጨረሻ ነው፤ አጫጆችም መላእክት ናቸው።'),
  ('bbd19498-9451-55b8-ad97-486236b7428a', 'd5877eec-3840-5163-a157-4ad9af8520da', 'df20c3d2-338a-59d6-a8d8-0cadb04c6e6e', 5, 40, 'እንግዲህ እንክርዳድ ተለቅሞ በእሳት እንደሚቃጠል፥ በዓለም መጨረሻ እንዲሁ ይሆናል።'),
  ('a2f59c95-1633-5bbe-a7fc-abb68b0cd050', 'd5877eec-3840-5163-a157-4ad9af8520da', 'df20c3d2-338a-59d6-a8d8-0cadb04c6e6e', 6, 41, 'የሰው ልጅ መላእክቱን ይልካል፤ ከመንግሥቱም እንቅፋትን ሁሉ ዓመፃንም የሚያደርጉትን ይለቅማሉ፤'),
  ('4cd93d2b-4480-585f-a042-57fac063f5e0', 'd5877eec-3840-5163-a157-4ad9af8520da', 'df20c3d2-338a-59d6-a8d8-0cadb04c6e6e', 7, 42, 'ወደ እቶነ እሳትም ይጥሉአቸዋል፤ በዚያ ልቅሶና ጥርስ ማፋጨት ይሆናል።'),
  ('1ee59c8e-cf52-5f7c-a4ff-94bde3e9023e', 'd5877eec-3840-5163-a157-4ad9af8520da', 'df20c3d2-338a-59d6-a8d8-0cadb04c6e6e', 8, 43, 'በዚያን ጊዜ ጻድቃን በአባታቸው መንግሥት እንደ ፀሐይ ይበራሉ። የሚሰማ ጆሮ ያለው ይስማ።'),
  ('778751d7-74c3-55e6-a0fa-c6f71bdf62bc', 'd5877eec-3840-5163-a157-4ad9af8520da', '230cc117-3197-5cf9-a278-905de325c8d2', 1, 44, '“ደግሞ መንግሥተ ሰማያት በእርሻ ውስጥ የተሰወረውን መዝገብ ትመስላለች፤ ሰውም አግኝቶ ሰወረው፤ ከደስታውም የተነሣ ሄዶ ያለውን ሁሉ ሸጠና ያን እርሻ ገዛ።'),
  ('0e03e530-0737-5e36-ab36-c4a8bde6c47e', 'd5877eec-3840-5163-a157-4ad9af8520da', '230cc117-3197-5cf9-a278-905de325c8d2', 2, 45, '“ደግሞ መንግሥተ ሰማያት መልካምን ዕንቁ የሚሻ ነጋዴን ትመስላለች፤'),
  ('7db34a47-0f43-5faf-a7f5-03593a6370ba', 'd5877eec-3840-5163-a157-4ad9af8520da', '230cc117-3197-5cf9-a278-905de325c8d2', 3, 46, 'ዋጋዋም እጅግ የበዛ አንዲት ዕንቁ በአገኘ ጊዜ ሄዶ ያለውን ሁሉ ሸጠና ገዛት።'),
  ('10ed8c48-1e6f-541e-a5f7-09d551dc9c12', 'd5877eec-3840-5163-a157-4ad9af8520da', '230cc117-3197-5cf9-a278-905de325c8d2', 4, 47, '“ደግሞ መንግሥተ ሰማያት ወደ ባሕር የተጣለች ከሁሉም ዐይነት የሰበሰበች መረብን ትመስላለች፤'),
  ('eb92b6df-e874-56e6-afb0-f5c4bce155f6', 'd5877eec-3840-5163-a157-4ad9af8520da', '230cc117-3197-5cf9-a278-905de325c8d2', 5, 48, 'በሞላችም ጊዜ ወደ ወደቡ አወጡአት፤ ተቀምጠውም መልካሙን ለቅመው በዕቃዎች ውስጥ አከማቹ፤ ክፉውን ግን ወደ ውጭ ጣሉት።'),
  ('f1e17d19-7901-58b1-a973-5139a2bbffa0', 'd5877eec-3840-5163-a157-4ad9af8520da', '230cc117-3197-5cf9-a278-905de325c8d2', 6, 49, 'በዓለም መጨረሻ እንዲሁ ይሆናል፤ መላእክት መጥተው ኀጢአተኞችን ከጻድቃን መካከል ይለዩአቸዋል፤ ወደ እቶነ እሳትም ይጥሉአቸዋል፤'),
  ('8cd1d0db-48fa-5591-af9e-d97701037637', 'd5877eec-3840-5163-a157-4ad9af8520da', '230cc117-3197-5cf9-a278-905de325c8d2', 7, 50, 'በዚያ ልቅሶና ጥርስ ማፋጨት ይሆናል።”'),
  ('66984bb5-50e4-57ad-a11e-5a74f3641a8c', 'd5877eec-3840-5163-a157-4ad9af8520da', 'e641ec07-f7a7-5994-a4da-0ccb95f39848', 1, 51, 'ኢየሱስም “ይህን ሁሉ አስተዋላችሁን?” አላቸው፤ “አዎን” አሉት።'),
  ('96701fcf-3778-552e-a2d9-fb275d25ea8b', 'd5877eec-3840-5163-a157-4ad9af8520da', 'e641ec07-f7a7-5994-a4da-0ccb95f39848', 2, 52, 'እርሱም “ስለዚህ የመንግሥተ ሰማያት ደቀ መዝሙር የሆነ ጻፊ ሁሉ ከመዝገቡ አዲሱንና አሮጌውን የሚያወጣ ባለቤትን ይመስላል፤” አላቸው።'),
  ('cf775c07-ecdf-5b1f-a9e1-8cff27e0e303', 'd5877eec-3840-5163-a157-4ad9af8520da', '67eb65e9-a635-562c-a4aa-b20eac42e4d0', 1, 53, 'ኢየሱስም እነዚህም ምሳሌዎች ከጨረሰ በኋላ ከዚያ ሄደ።'),
  ('89d9b45e-69f6-58bd-abd7-31e22b6369f3', 'd5877eec-3840-5163-a157-4ad9af8520da', '67eb65e9-a635-562c-a4aa-b20eac42e4d0', 2, 54, 'ወደ ገዛ አገሩም መጥቶ እስኪገረሙ ድረስ በምኩራባቸው ያስተምራቸው ነበር፤ እንዲህም አሉ “ይህን ጥበብና ተአምራት ይህ ከወዴት አገኘው?'),
  ('6b962fbb-f7d0-5607-ae54-8a92f624d1fb', 'd5877eec-3840-5163-a157-4ad9af8520da', '67eb65e9-a635-562c-a4aa-b20eac42e4d0', 3, 55, 'ይህ የጸራቢ ልጅ አይደለምን? እናቱስ ማርያም ትባል የለምን? ወንድሞቹስ ያዕቆብና ዮሳ፥ ስምዖንም ይሁዳም አይደሉምን?'),
  ('6ded7e3b-4d72-54dd-a92d-cdc9b71bcf2c', 'd5877eec-3840-5163-a157-4ad9af8520da', '67eb65e9-a635-562c-a4aa-b20eac42e4d0', 4, 56, 'እኅቶቹስ ሁሉ በእኛ ዘንድ ያሉ አይደሉምን? እንኪያስ ይህን ሁሉ ከወዴት አገኘው?” ተሰናከሉበትም።'),
  ('e5f3da5d-4ad3-5ca2-ae7d-f173779b214e', 'd5877eec-3840-5163-a157-4ad9af8520da', '67eb65e9-a635-562c-a4aa-b20eac42e4d0', 5, 57, 'ኢየሱስ ግን “ነቢይ ከገዛ አገሩና ከገዛ ቤቱ በቀር ሳይከበር አይቀርም፤” አላቸው።'),
  ('5c1f27dc-2b01-56a1-a2ef-cb23f43659be', 'd5877eec-3840-5163-a157-4ad9af8520da', '67eb65e9-a635-562c-a4aa-b20eac42e4d0', 6, 58, 'በአለማመናቸውም ምክንያት በዚያ ብዙ ተአምራት አላደረገም።'),
  ('02783d9c-6e38-52dc-a537-e707b58912c8', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 1, 1, 'በዚያ ዘመን የአራተኛው ክፍል ገዥ ሄሮድስ የኢየሱስን ዝና ሰማ፤'),
  ('674a9bc4-8216-5896-a457-390cc2bd9b96', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 2, 2, 'ለሎሌዎቹም “ይህ መጥምቁ ዮሐንስ ነው፤ እርሱ ከሙታን ተነሥቶአል፤ ስለዚህም ኃይል በእርሱ ይደረጋል፤” አለ።'),
  ('895b7847-c1e5-5382-a12d-d98cdff294f2', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 3, 3, 'ሄሮድስ በወንድሙ በፊልጶስ ሚስት በሄሮድያዳ ምክንያት ዮሐንስን አስይዞ አሳስሮት በወህኒ አኑሮት ነበርና፤'),
  ('c9cc9db9-f96f-5686-a66e-6ee45c0d3f72', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 4, 4, 'ዮሐንስ “እርስዋ ለአንተ ትሆን ዘንድ አልተፈቀደም፤” ይለው ነበርና።'),
  ('52c97155-7a3d-577b-a69f-48cf9461abec', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 5, 5, 'ሊገድለውም ወዶ ሳለ፥ ሕዝቡ እንደ ነቢይ ስለ አዩት ፈራቸው።'),
  ('3164e4a1-0892-57d1-a6a5-9a92772e909e', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 6, 6, 'ነገር ግን ሄሮድስ የተወለደበት ቀን በሆነ ጊዜ፥ የሄሮድያዳ ልጅ በመካከላቸው ዘፈነች፤ ሄሮድስንም ደስ አሰኘችው፤'),
  ('0400e964-8f85-508a-ac5d-3525154b6ed3', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 7, 7, 'ስለዚህም የምትለምነውን ሁሉ እንዲሰጣት በመሐላ ተስፋ አደረገላት።'),
  ('753360e3-28fc-56ab-a78e-b8ffcccd9b1e', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 8, 8, 'እርስዋም በእናትዋ ተመክራ “የመጥምቁን የዮሐንስን ራስ በዚህ በወጭት ስጠኝ፤” አለችው።'),
  ('0a751f07-df22-53cb-a427-c8389fb7df44', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 9, 9, 'ንጉሡም አዘነ፤ ነገር ግን ስለ መሐላው ከእርሱም ጋር ተቀምጠው ስላሉት ሰዎች እንዲሰጡአት፤ አዘዘ፤'),
  ('6232d021-fa23-55f4-aa7f-20225313aa57', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 10, 10, 'ልኮም የዮሐንስን ራስ በወህኒ አስቆረጠው።'),
  ('1c67fc81-fb71-5932-ad7a-f7e69f6b0080', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 11, 11, 'ራሱንም በወጭት አምጥተው ለብላቴናይቱ ሰጡአት፤ ወደ እናትዋም ወሰደችው።'),
  ('4cb0f1da-d736-5c8e-ab71-c07cdf36597f', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '262402fc-6ade-5ab7-a6f6-86eacf7997f7', 12, 12, 'ደቀ መዛሙርቱም ቀርበው በድኑን ወሰዱና ቀበሩት፤ መጥተውም ለኢየሱስ አወሩለት።'),
  ('a9ca32d2-48e0-5380-aaba-48c8a52681c4', '85c1cef2-6591-53a0-a3e7-88ccb323502d', 'b16a6023-5fd6-561c-a6ac-dd1d98f9c7cf', 1, 13, 'ኢየሱስም በሰማ ጊዜ ከዚያ ብቻውን ወደ ምድረ በዳ በታንኳ ፈቀቅ አለ፤ ሕዝቡም ሰምተው ከከተማዎቹ በእግር ተከተሉት።'),
  ('dc097df6-bbd1-555a-a98f-4fa3ef2c0ca9', '85c1cef2-6591-53a0-a3e7-88ccb323502d', 'b16a6023-5fd6-561c-a6ac-dd1d98f9c7cf', 2, 14, 'ወጥቶም ብዙ ሕዝብ አየና አዘነላቸው፤ ድውዮቻቸውንም ፈወሰ።'),
  ('22b33b51-a3e6-51eb-a8f9-561aa3737179', '85c1cef2-6591-53a0-a3e7-88ccb323502d', 'b16a6023-5fd6-561c-a6ac-dd1d98f9c7cf', 3, 15, 'በመሸም ጊዜ ደቀ መዛሙርቱ ወደ እርሱ ቀርበው “ቦታው ምድረ በዳ ነው፤ አሁንም ሰዓቱ አልፎአል፤ ወደ መንደሮች ሄደው ለራሳቸው ምግብ እንዲገዙ ሕዝቡን አሰናብት፤” አሉት።'),
  ('c05480b6-a461-534b-ab97-010db3ece5f1', '85c1cef2-6591-53a0-a3e7-88ccb323502d', 'b16a6023-5fd6-561c-a6ac-dd1d98f9c7cf', 4, 16, 'ኢየሱስም “እናንተ የሚበሉትን ስጡአቸው እንጂ ሊሄዱ አያስፈልግም፤” አላቸው።'),
  ('38f9a7ef-fd8f-5d0a-a8cb-c33435548e01', '85c1cef2-6591-53a0-a3e7-88ccb323502d', 'b16a6023-5fd6-561c-a6ac-dd1d98f9c7cf', 5, 17, 'እነርሱም “ከአምስት እንጀራና ከሁለት ዓሣ በቀር በዚህ የለንም፤” አሉት።'),
  ('e014947b-ac3f-5cd4-a2c8-6847ae729ede', '85c1cef2-6591-53a0-a3e7-88ccb323502d', 'b16a6023-5fd6-561c-a6ac-dd1d98f9c7cf', 6, 18, 'እርሱም “እነዚያን ወደዚህ አምጡልኝ፤” አላቸው።'),
  ('d23ae166-46cd-5108-acac-68f31f8df00c', '85c1cef2-6591-53a0-a3e7-88ccb323502d', 'b16a6023-5fd6-561c-a6ac-dd1d98f9c7cf', 7, 19, 'ሕዝቡም በሣር ላይ እንዲቀመጡ አዘዘ፤ አምስቱንም እንጀራና ሁለቱን ዓሣ ይዞ ወደ ሰማይ አሻቅቦ አየና ባረከ፤ እንጀራውንም ቆርሶ ለደቀ መዛሙርቱ ሰጠ፤ ደቀ መዛሙርቱም ለሕዝቡ።'),
  ('f37431df-3707-5959-a67e-358a77614b49', '85c1cef2-6591-53a0-a3e7-88ccb323502d', 'b16a6023-5fd6-561c-a6ac-dd1d98f9c7cf', 8, 20, 'ሁሉም በልተው ጠገቡ፤ የተረፈውንም ቁርስራሽ ዐሥራ ሁለት መሶብ ሙሉ አነሡ።'),
  ('58e0a4bb-eb0a-58e2-a922-70c917962484', '85c1cef2-6591-53a0-a3e7-88ccb323502d', 'b16a6023-5fd6-561c-a6ac-dd1d98f9c7cf', 9, 21, 'ከሴቶችና ከልጆችም በቀር የበሉት አምስት ሺህ ወንዶች ያህሉ ነበር።'),
  ('b806ee8e-643d-5e43-acbf-5c4c69e950d9', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 1, 22, 'ወዲያውም ሕዝቡን ሲያሰናብት ሳለ፥ ደቀ መዛሙርቱ በታንኳይቱ ገብተው ወደ ማዶ እንዲቀድሙት ግድ አላቸው።'),
  ('00731da9-7f4d-529d-a0dc-7ae6496c19a6', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 2, 23, 'ሕዝቡንም አሰናብቶ ይጸልይ ዘንድ ብቻውን ወደ ተራራ ወጣ። በመሸም ጊዜ ብቻውን በዚያ ነበረ።'),
  ('061aebae-571a-58ba-aaf8-9eae0a549eca', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 3, 24, 'ታንኳይቱም አሁን በባሕር መካከል ሳለች፥ ነፋስ ከወደ ፊት ነበርና በማዕበል ትጨነቅ ነበር።'),
  ('971d32ff-fbdb-5bf9-a84d-f99b5244b054', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 4, 25, 'ከሌሊቱም በአራተኛው ክፍል ኢየሱስ በባሕር ላይ እየሄደ ወደ እነርሱ መጣ።'),
  ('ae59fb45-5055-5902-a048-b47fc47f7131', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 5, 26, 'ደቀ መዛሙርቱም በባሕር ላይ ሲሄድ ባዩት ጊዜ “ምትሐት ነው” ብለው ታወኩ፤ በፍርሃትም ጮኹ።'),
  ('2e70804f-6cd6-5325-afa8-c7f0db6e40ac', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 6, 27, 'ወዲያውም ኢየሱስ ተናገራቸውና “አይዞአችሁ፤ እኔ ነኝ፤ አትፍሩ፤” አላቸው።'),
  ('6af80a2b-d5cd-53fa-a1b1-0c856de75920', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 7, 28, 'ጴጥሮስም መልሶ “ጌታ ሆይ! አንተስ ከሆንህ በውሃው ላይ ወደ አንተ እንድመጣ እዘዘኝ፤” አለው።'),
  ('66ab6436-93d2-5bce-a61a-cd58741c8dd1', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 8, 29, 'እርሱም፦ ና አለው። ጴጥሮስም ከታንኳይቱ ወርዶ ወደ ኢየሱስ ሊደርስ በውሃው ላይ ሄደ።'),
  ('0fa16b47-4468-5e37-a748-1d1642b23004', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 9, 30, 'ነገር ግን የነፋሱን ኃይል አይቶ ፈራ፤ ሊሰጥምም በጀመረ ጊዜ “ጌታ ሆይ! አድነኝ፤” ብሎ ጮኸ።'),
  ('3ad47499-c0ec-571c-a027-a74b8db522b2', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 10, 31, 'ወዲያውም ኢየሱስ እጁን ዘርግቶ ያዘውና “አንተ እምነት የጎደለህ፤ ስለምን ተጠራጠርህ?” አለው።'),
  ('a457ecd2-374d-5b3f-aa96-5819d88f5f81', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 11, 32, 'ወደ ታንኳይቱም በወጡ ጊዜ ነፋሱ ተወ።'),
  ('18ec44be-2e22-5401-aca3-83a2f89c1093', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 12, 33, 'በታንኳይቱም የነበሩት “በእውነት የእግዚአብሔር ልጅ ነህ፤” ብለው ሰገዱለት።'),
  ('748b2103-c787-579b-a0f4-f33facbc5154', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 13, 34, 'ተሻግረውም ወደ ጌንሴሬጥ ምድር መጡ።'),
  ('0c6cc3fa-1cab-52f5-a2b0-e668adb91188', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 14, 35, 'የዚያ ቦታ ሰዎችም ባወቁት ጊዜ በዙርያው ወዳለ አገር ሁሉ ላኩ፤ ሕመምተኞችንም ሁሉ ወደ እርሱ አመጡ፤'),
  ('7200e991-187e-5b5c-ae34-69f7480d7f75', '85c1cef2-6591-53a0-a3e7-88ccb323502d', '92ebe360-a9ad-508d-add5-b4c59a352a39', 15, 36, 'የልብሱንም ጫፍ ብቻ ሊዳስሱ ይለምኑት ነበር፤ የዳሰሱትም ሁሉ ዳኑ።'),
  ('323f4d35-1c68-5657-afd8-13b809ed7f1b', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 1, 1, 'በዚያን ጊዜ ጻፎችና ፈሪሳውያን ከኢየሩሳሌም ወደ ኢየሱስ ቀረቡና'),
  ('71328a02-9072-57ff-a65c-739c2a675931', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 2, 2, '“ደቀ መዛሙርትህ ስለ ምን የሽማግሎችን ወግ ይተላለፋሉ? እንጀራ ሲበሉ እጃቸውን አይታጠቡምና፤” አሉት።'),
  ('c493eeba-a362-5d89-ad45-f1a0fb8d3f18', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 3, 3, 'እርሱም መልሶ እንዲህ አላቸው “እናንተስ ስለ ወጋችሁ የእግዚአብሔርን ትእዛዝ ስለ ምን ትተላለፋላችሁ?'),
  ('7d6a0918-33fc-583f-ae49-a1355dd3e3c7', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 4, 4, 'እግዚአብሔር ‘አባትህንና እናትህን አክብር፤’ ደግሞ ‘አባቱን ወይም እናቱን የሰደበ ፈጽሞ ይሙት፤’ ብሎአልና፤'),
  ('b2054258-0f69-5e9b-a8af-ab9c4a5a972b', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 5, 5, 'እናንተ ግን ‘አባቱን ወይም እናቱን “ከእኔ የምትጠቀምበት መባ ነው የሚል ሁሉ፥'),
  ('721740ed-8eb1-5876-abfb-f671e0ad3543', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 6, 6, 'አባቱን ወይም እናቱን አያከብርም፤” ትላላችሁ፤’ ስለ ወጋችሁም የእግዚአብሔርን ቃል ሻራችሁ።'),
  ('dc7c985b-3a04-5853-abe1-80ded5740c82', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 7, 7, 'እናንተ ግብዞች፥ ኢሳይያስ ስለ እናንተ'),
  ('0f88ccc6-19fe-5046-abe6-7f6b252316d0', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 8, 8, '‘ይህ ሕዝብ በከንፈሩ ያከብረኛል፥'),
  ('85d18160-0abd-5b82-a5e4-64a06d579ccc', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 9, 9, 'የሰውም ሥርዓት የሆነ ትምህርት እያስተማሩ በከንቱ ያመልኩኛል፤’'),
  ('e235e5ae-9fb0-5533-ab03-461d93d548a6', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 10, 10, 'ሕዝቡንም ጠርቶ “ስሙ አስተውሉም፤'),
  ('856f48c6-3258-5e45-ae47-4c2f9ccdd965', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 11, 11, 'ሰውን የሚያረክሰው ወደ አፍ የሚገባ አይደለም፤ ከአፍ የሚወጣው ግን ሰውን የሚያረክሰው ይህ ነው፤” አላቸው።'),
  ('e7e8de98-e9bb-5403-a05f-1d814e55d785', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 12, 12, 'በዚያን ጊዜ ደቀ መዛሙርቱ ቀርበው “ፈሪሳውያን ይህን ቃል ሰምተው እንደ ተሰናከሉ አወቅህን?” አሉት።'),
  ('01fe53d5-1cac-58c7-ab8a-2437a58f45ff', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 13, 13, 'እርሱ ግን መልሶ “የሰማዩ አባቴ ያልተከለው ተክል ሁሉ ይነቀላል።'),
  ('4726232f-3f8b-5015-a158-f0077d9f3f60', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 14, 14, 'ተዉአቸው፤ ዕውሮችን የሚመሩ ዕውሮች ናቸው፤ ዕውርም ዕውርን ቢመራው ሁለቱም ወደ ጉድጓድ ይወድቃሉ፤” አለ።'),
  ('669fc74c-f5e8-5c1e-acce-e84bc67b38da', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 15, 15, 'ጴጥሮስም መልሶ “ምሳሌውን ተርጕምልን፤” አለው።'),
  ('d58cd1ef-2f66-58ea-a721-51fe652926f5', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 16, 16, 'ኢየሱስም እንዲህ አለ “እናንተ ደግሞ እስካሁን የማታስተውሉ ናችሁን?'),
  ('a5d06fbd-50b3-5369-ac0b-8f3ffe74605d', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 17, 17, 'ወደ አፍ የሚገባ ሁሉ ወደ ሆድ አልፎ ወደ እዳሪ እንዲጣል አትመለከቱምን?'),
  ('07cb0313-9208-5c46-a827-19d88d4a112c', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 18, 18, 'ከአፍ የሚወጣ ግን ከልብ ይወጣል፤ ሰውንም የሚያረክሰው ያ ነው።'),
  ('db9bddc4-5367-5a18-af6c-a71ad3fefa6c', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 19, 19, 'ከልብ ክፉ አሳብ፥ መግደል፥ ምንዝርነት፥ ዝሙት፥ መስረቅ፥ በውሸት መመስከር፥ ስድብ ይወጣልና።'),
  ('ecf081ee-1d72-5558-af08-c07835db32f6', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'b32ecca7-f62d-5b37-a52c-133c7f59f5aa', 20, 20, 'ሰውን የሚያረክሰው ይህ ነው እንጂ፥ ባልታጠበ እጅ መብላትስ ሰውን አያረክሰውም።”'),
  ('25050bbd-8e55-5da7-a433-658fcb283d58', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'fea25605-befe-51e1-ad05-223b513c1b93', 1, 21, 'ኢየሱስም ከዚያ ወጥቶ ወደ ጢሮስና ወደ ሲዶና አገር ሄደ።'),
  ('7bb651ba-11f5-54b7-a62e-e1ddab6ac047', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'fea25605-befe-51e1-ad05-223b513c1b93', 2, 22, 'እነሆም ከነናዊት ሴት ከዚያ አገር ወጥታ “ጌታ ሆይ! የዳዊት ልጅ ማረኝ፤ ልጄን ጋኔን ክፉኛ ይዞአታል፤” ብላ ጮኸች።'),
  ('3b565a20-8e44-53a5-afce-cecf3c77649e', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'fea25605-befe-51e1-ad05-223b513c1b93', 3, 23, 'እርሱ ግን አንዳች አልመለሰላትም። ደቀ መዛሙርቱም ቀርበው “በኋላችን ትጮኻለችና አሰናብታት፤” እያሉ ለመኑት።'),
  ('d196748a-4693-5fbe-a457-301ef96f9b2a', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'fea25605-befe-51e1-ad05-223b513c1b93', 4, 24, 'እርሱም መልሶ “ከእስራኤል ቤት ለጠፉት በጎች በቀር አልተላክሁም፤” አለ።'),
  ('36590f6e-cd21-5e1f-a5b5-5c63d14d2c84', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'fea25605-befe-51e1-ad05-223b513c1b93', 5, 25, 'እርስዋ ግን መጥታ “ጌታ ሆይ! እርዳኝ፤” እያለች ሰገደችለት።'),
  ('270cc5b8-2a11-5680-a93f-c95b5802a6bc', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'fea25605-befe-51e1-ad05-223b513c1b93', 6, 26, 'እርሱ ግን መልሶ “የልጆችን እንጀራ ይዞ ለቡችሎች መጣል አይገባም፤” አለ።'),
  ('e4026f2a-1bae-5230-ac9f-7056677e63fd', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'fea25605-befe-51e1-ad05-223b513c1b93', 7, 27, 'እርስዋም “አዎን ጌታ ሆይ! ቡችሎችም እኮ ከጌቶቻቸው ማዕድ የወደቀውን ፍርፋሪ ይበላሉ፤” አለች።'),
  ('e1dfc7d3-7daa-5d07-a0c7-77cea30baf12', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'fea25605-befe-51e1-ad05-223b513c1b93', 8, 28, 'በዚያን ጊዜ ኢየሱስ መልሶ “አንቺ ሴት፥ እምነትሽ ታላቅ ነው፤ እንደወደድሽ ይሁንልሽ፤” አላት። ልጅዋም ከዚያች ሰዓት ጀምሮ ዳነች።'),
  ('2d83262d-6760-512c-ac60-7e0d0a5593c0', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'ec0b144b-8b59-5db6-a982-466d0f11bfee', 1, 29, 'ኢየሱስም ከዚያ አልፎ ወደ ገሊላ ባሕር አጠገብ መጣ፤ ወደ ተራራም ወጥቶ በዚያ ተቀመጠ።'),
  ('b287ab5c-61c6-56f7-a0f9-bd0a00ed0d29', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'ec0b144b-8b59-5db6-a982-466d0f11bfee', 2, 30, 'ብዙ ሕዝብም አንካሶችን፥ ዕውሮችንም፥ ድዳዎችንም፥ ጉንድሾችንም፥ ሌሎችንም ብዙ ይዘው ወደ እርሱ ቀረቡ በኢየሱስም እግር አጠገብ አስቀመጡአቸው፤ ፈወሳቸውም፤'),
  ('c1b0f6a3-cd72-5bb4-a9ff-41c194043cf5', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', 'ec0b144b-8b59-5db6-a982-466d0f11bfee', 3, 31, 'ስለዚህም ሕዝቡ ድዳዎች ሲናገሩ፥ ጉንድሾችም ሲድኑ፥ አንካሶችም ሲሄዱ፥ ዕውሮችም ሲያዩ አይተው ተደነቁ፤ የእስራኤልንም አምላክ አከበሩ።'),
  ('bf3ab993-d1cf-5490-a01d-e1d026ca979b', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', '5ac254a1-f4a7-588f-a2f1-f42cd9f56664', 1, 32, 'ኢየሱስም ደቀ መዛሙርቱን ጠርቶ “ሕዝቡ ከእኔ ጋር እስካሁን ሦስት ቀን ውለዋልና የሚበሉት ስለሌላቸው አዝንላቸዋለሁ፤ በመንገድም እንዳይዝሉ ጦማቸውን ላሰናብታቸው አልወድም፤” አላቸው።'),
  ('0cb550d4-93d2-50cd-a860-8df70b4bd7d4', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', '5ac254a1-f4a7-588f-a2f1-f42cd9f56664', 2, 33, 'ደቀ መዛሙርቱም “ይህን ያህል ሕዝብ የሚያጠግብ ይህን ያህል እንጀራ በምድረ በዳ ከወዴት እናገኛለን?” አሉት።'),
  ('5470c4df-20bf-5d9e-afa8-68dbfd799d54', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', '5ac254a1-f4a7-588f-a2f1-f42cd9f56664', 3, 34, 'ኢየሱስም “ስንት እንጀራ አላችሁ?” አላቸው። እነርሱም “ሰባት፥ ጥቂትም ትንሽ ዓሣ” አሉት።'),
  ('b8ddabe9-ae1d-527a-a5e6-4f5dc40f77cd', '86ed2ed2-abef-5aba-aecb-b13ec30b1e69', '5ac254a1-f4a7-588f-a2f1-f42cd9f56664', 4, 35, 'ሕዝቡም በምድር ላይ እንዲቀመጡ አዘዘ፤'),
